const featuredGlow: Field = (u, v, t, ar) => {
  const x = (u - 0.8) * ar;
  const d = Math.hypot(x, v + 0.1);
  return clamp(0.9 - d * 0.9 + Math.sin(u * 14 - t * 0.8 + v * 6) * 0.08);
};

