function PeerCursor({ name, color, path, scale }: { name: string; color: string; path: number[][]; scale: number }) {
  const [i, setI] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setI((n) => (n + 1) % path.length), 2400);
    return () => clearInterval(id);
  }, [path.length]);
