    <div className="pointer-events-none absolute left-0 top-0 z-30 transition-transform duration-[2200ms] ease-smooth" style={{ transform: `translate(${x * scale}px, ${y * scale}px)` }}>
      <MousePointer2 className="h-5 w-5 -rotate-12" style={{ color, fill: color }} />
      <span className="ml-4 inline-block rounded-full px-2 py-0.5 text-[11px] font-medium text-white shadow-sm" style={{ background: color }}>{name}</span>
    </div>
  );
}

type Drag = { id: string; mode: 'move' | 'resize'; sx: number; sy: number; ox: number; oy: number; ow: number; oh: number };

export function Editor() {
  const [shapes, setShapes] = useState<Shape[]>(initialShapes);
  const [selected, setSelected] = useState<string | null>('r1');
  const [tool, setTool] = useState<Tool>('select');
  const [prompt, setPrompt] = useState('Pricing card, dark, with CTA');
  const [generating, setGenerating] = useState(false);
  const [scale, setScale] = useState(1);
  const boardRef = useRef<HTMLDivElement>(null);
  const drag = useRef<Drag | null>(null);
  const timers = useRef<number[]>([]);

  useEffect(() => {
    const el = boardRef.current;
    if (!el) return;
    const ro = new ResizeObserver(([entry]) => setScale(Math.min(1, entry.contentRect.width / BOARD_W)));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  useEffect(() => () => timers.current.forEach(clearTimeout), []);

  const update = (id: string, patch: Partial<Shape>) => setShapes((list) => list.map((s) => (s.id === id ? { ...s, ...patch } : s)));
  const remove = (id: string) => {
    setShapes((list) => list.filter((s) => s.id !== id));
    setSelected(null);
  };

  const local = (e: PointerEvent) => {
    const b = boardRef.current!.getBoundingClientRect();
    return { x: (e.clientX - b.left) / scale, y: (e.clientY - b.top) / scale };
  };

  const onBoardDown = (e: PointerEvent<HTMLDivElement>) => {
    if (tool === 'select') {
      setSelected(null);
      return;
    }
    const p = local(e);
    const shape = makeShape(tool, p.x, p.y, shapes.length + 1);
    setShapes((list) => [...list, shape]);
    setSelected(shape.id);
    setTool('select');
  };

  const startDrag = (e: PointerEvent<HTMLElement>, s: Shape, mode: Drag['mode']) => {
    if (tool !== 'select') return;
    e.stopPropagation();
    setSelected(s.id);
    const p = local(e);
    drag.current = { id: s.id, mode, sx: p.x, sy: p.y, ox: s.x, oy: s.y, ow: s.w, oh: s.h };
    e.currentTarget.setPointerCapture(e.pointerId);
  };

  const onMove = (e: PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d) return;
    const p = local(e);
    const dx = p.x - d.sx;
    const dy = p.y - d.sy;
    if (d.mode === 'move') update(d.id, { x: Math.round(d.ox + dx), y: Math.round(d.oy + dy) });
    else update(d.id, { w: Math.max(12, Math.round(d.ow + dx)), h: Math.max(2, Math.round(d.oh + dy)) });
  };

  const generate = (e: FormEvent) => {
    e.preventDefault();
    if (generating || !prompt.trim()) return;
    setGenerating(true);
    const offset = (shapes.filter((s) => s.name === 'AI / Pricing card').length % 3) * 18;
    const parts = generatedCard(580 + offset, 40 + offset);
    timers.current.push(
      window.setTimeout(() => {
        parts.forEach((part, i) => {
          timers.current.push(window.setTimeout(() => setShapes((list) => [...list, part]), i * 130));
        });
        timers.current.push(
          window.setTimeout(() => {
            setSelected(parts[0].id);
            setGenerating(false);
          }, parts.length * 130),
        );
      }, 1100),
    );
  };

  const onKey = (e: KeyboardEvent<HTMLDivElement>) => {
    if ((e.target as HTMLElement).tagName === 'INPUT') return;
    const t = tools.find((x) => x.key.toLowerCase() === e.key.toLowerCase());
    if (t) return setTool(t.id);
    if (!selected) return;
    const s = shapes.find((x) => x.id === selected);
    if (!s) return;
    const step = e.shiftKey ? 10 : 1;
    const nudges: Record<string, Partial<Shape>> = {
      ArrowLeft: { x: s.x - step }, ArrowRight: { x: s.x + step }, ArrowUp: { y: s.y - step }, ArrowDown: { y: s.y + step },
    };
    if (nudges[e.key]) {
      e.preventDefault();
      update(s.id, nudges[e.key]);
    } else if (e.key === 'Delete' || e.key === 'Backspace') remove(s.id);
    else if (e.key === 'Escape') setSelected(null);
  };

  const current = shapes.find((s) => s.id === selected) ?? null;

  return (
    <div tabIndex={0} onKeyDown={onKey} className="flex h-[560px] flex-col overflow-hidden rounded-2xl border border-zinc-200 bg-white shadow-[0_50px_100px_-40px_rgba(24,24,27,0.35)] outline-none focus-visible:ring-2 focus-visible:ring-[#0d99ff]/40">
      <div className="flex h-12 shrink-0 items-center justify-between border-b border-zinc-200 bg-zinc-950 px-3 text-white">
        <div className="flex items-center gap-1">
          {tools.map((t) => (
            <button
              key={t.id}
              onClick={() => setTool(t.id)}
              title={`${t.label} (${t.key})`}
              aria-label={t.label}
              className={cn('grid h-8 w-8 place-items-center rounded-md transition-colors', tool === t.id ? 'bg-[#0d99ff] text-white' : 'text-zinc-400 hover:bg-white/10 hover:text-white')}
            >
              <t.icon className="h-4 w-4" />
            </button>
          ))}
        </div>
        <span className="hidden text-xs text-zinc-400 sm:block">Marketing site <span className="text-zinc-600">/</span> <span className="text-white">Hero v3</span></span>
        <div className="flex items-center gap-2">
          <div className="flex -space-x-1.5">
            {[['M', '#f97316'], ['T', '#10b981'], ['Y', '#0d99ff']].map(([l, c]) => (
              <span key={l} className="grid h-7 w-7 place-items-center rounded-full text-[11px] font-semibold ring-2 ring-zinc-950" style={{ background: c }}>{l}</span>
            ))}
          </div>
          <button aria-label="Present" className="grid h-8 w-8 place-items-center rounded-md text-zinc-400 hover:bg-white/10 hover:text-white"><Play className="h-4 w-4" /></button>
          <button className="h-8 rounded-md bg-[#0d99ff] px-3 text-xs font-medium text-white transition-colors hover:bg-[#0b87e0]">Share</button>
        </div>
      </div>

      <div className="flex min-h-0 flex-1">
        <LayersPanel shapes={shapes} selected={selected} onSelect={setSelected} />
        <div className="relative min-w-0 flex-1 overflow-hidden bg-[#f5f5f5]" style={{ backgroundImage: 'radial-gradient(#d4d4d8 1px, transparent 1px)', backgroundSize: '16px 16px' }}>
          <div
            ref={boardRef}
            onPointerDown={onBoardDown}
            onPointerMove={onMove}
            onPointerUp={() => (drag.current = null)}
            className={cn('absolute inset-0 touch-none', tool === 'select' ? 'cursor-default' : 'cursor-crosshair')}
          >
            {shapes.map((s) => {
              const isSel = s.id === selected;
              return (
                <div
                  key={s.id}
                  onPointerDown={(e) => startDrag(e, s, 'move')}
                  className={cn('group absolute', s.fresh && 'animate-scale-in', tool === 'select' && 'cursor-move')}
                  style={{ left: s.x * scale, top: s.y * scale, width: s.w * scale, height: s.h * scale }}
                >
                  {s.kind === 'text' ? (
                    <div className="h-full w-full select-none whitespace-nowrap font-semibold leading-none tracking-tight" style={{ color: s.fill, fontSize: s.h * 0.78 * scale }}>{s.text}</div>
                  ) : (
                    <div
                      className={cn('h-full w-full', s.kind === 'frame' && 'shadow-[0_1px_3px_rgba(0,0,0,0.08),0_10px_30px_-12px_rgba(0,0,0,0.15)]')}
                      style={{ background: s.fill, borderRadius: s.kind === 'ellipse' ? '9999px' : s.radius * scale }}
                    />
                  )}
                  {s.kind === 'frame' && <span className="absolute -top-5 left-0 whitespace-nowrap text-[10px] text-zinc-500">{s.name}</span>}
                  <div className={cn('pointer-events-none absolute -inset-px border-[1.5px] border-[#0d99ff] transition-opacity', isSel ? 'opacity-100' : 'opacity-0 group-hover:opacity-60')} />
                  {isSel && (
                    <>
                      {['-left-1 -top-1', '-right-1 -top-1', '-left-1 -bottom-1'].map((p) => (
                        <span key={p} className={cn('pointer-events-none absolute h-2 w-2 border-[1.5px] border-[#0d99ff] bg-white', p)} />
                      ))}
                      <span onPointerDown={(e) => startDrag(e, s, 'resize')} className="absolute -bottom-1.5 -right-1.5 h-3 w-3 cursor-nwse-resize border-[1.5px] border-[#0d99ff] bg-white" />
                      <span className="pointer-events-none absolute left-1/2 top-full mt-2 -translate-x-1/2 whitespace-nowrap rounded bg-[#0d99ff] px-1.5 py-0.5 font-mono text-[10px] text-white">
                        {Math.round(s.w)} × {Math.round(s.h)}
                      </span>
                    </>
                  )}
                </div>
              );
            })}
            {peers.map((p) => <PeerCursor key={p.name} {...p} scale={scale} />)}
            {generating && (
              <div className="absolute overflow-hidden rounded-2xl border-2 border-dashed border-[#0d99ff]/60 bg-[#0d99ff]/5" style={{ left: 580 * scale, top: 40 * scale, width: 210 * scale, height: 230 * scale }}>
                <div className="absolute inset-0 -translate-x-full animate-shimmer bg-gradient-to-r from-transparent via-[#0d99ff]/20 to-transparent" />
              </div>
            )}
          </div>

          <form onSubmit={generate} onPointerDown={(e) => e.stopPropagation()} className="absolute bottom-4 left-1/2 z-40 flex w-[min(92%,440px)] -translate-x-1/2 items-center gap-2 rounded-xl border border-zinc-200 bg-white p-1.5 pl-3 shadow-[0_12px_40px_-12px_rgba(0,0,0,0.25)]">
            <Sparkles className={cn('h-4 w-4 shrink-0 text-[#0d99ff]', generating && 'animate-spin-slow')} />
            <input
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              aria-label="Describe what to generate"
              placeholder="Describe a component..."
              className="min-w-0 flex-1 bg-transparent text-sm text-zinc-900 outline-none placeholder:text-zinc-400"
            />
            <button disabled={generating} className="flex h-8 items-center gap-1.5 rounded-lg bg-zinc-950 px-3 text-xs font-medium text-white transition-colors hover:bg-zinc-800 disabled:opacity-70">
              {generating ? <><Loader2 className="h-3.5 w-3.5 animate-spin" /> Generating</> : 'Generate'}
            </button>
          </form>
          <span className="pointer-events-none absolute left-3 top-3 rounded-md bg-white/80 px-2 py-1 font-mono text-[10px] text-zinc-500 ring-1 ring-zinc-200 backdrop-blur">{Math.round(scale * 100)}%</span>
        </div>
        <Inspector shape={current} onChange={(patch) => current && update(current.id, patch)} onDelete={() => current && remove(current.id)} />
      </div>
    </div>
  );
}

export type ShapeKind = 'frame' | 'rect' | 'ellipse' | 'text';
export type Tool = 'select' | 'frame' | 'rect' | 'ellipse' | 'text';

export interface Shape {
  id: string;
  kind: ShapeKind;
  name: string;
  x: number;
  y: number;
  w: number;
  h: number;
  fill: string;
  radius: number;
  text?: string;
  fresh?: boolean;
}

export const swatches = ['#ffffff', '#18181b', '#0d99ff', '#f97316', '#10b981', '#f43f5e', '#facc15', '#e4e4e7'];

export const initialShapes: Shape[] = [
  { id: 'f1', kind: 'frame', name: 'Hero / Desktop', x: 40, y: 36, w: 340, h: 250, fill: '#ffffff', radius: 14 },
  { id: 't1', kind: 'text', name: 'Headline', x: 64, y: 70, w: 230, h: 30, fill: '#18181b', radius: 0, text: 'Ship it faster' },
  { id: 'r1', kind: 'rect', name: 'Image', x: 64, y: 116, w: 292, h: 100, fill: '#0d99ff', radius: 10 },
  { id: 'r2', kind: 'rect', name: 'Button', x: 64, y: 232, w: 112, h: 34, fill: '#18181b', radius: 17 },
  { id: 'e1', kind: 'ellipse', name: 'Avatar', x: 420, y: 70, w: 84, h: 84, fill: '#f97316', radius: 0 },
  { id: 'r3', kind: 'rect', name: 'Sticky note', x: 410, y: 182, w: 130, h: 104, fill: '#facc15', radius: 6 },
];

const defaults: Record<ShapeKind, Pick<Shape, 'w' | 'h' | 'fill' | 'radius'> & { text?: string }> = {
  frame: { w: 200, h: 140, fill: '#ffffff', radius: 12 },
  rect: { w: 120, h: 80, fill: '#10b981', radius: 8 },
  ellipse: { w: 80, h: 80, fill: '#f43f5e', radius: 0 },
  text: { w: 160, h: 28, fill: '#18181b', radius: 0, text: 'Type something' },
};

export function makeShape(kind: ShapeKind, x: number, y: number, n: number): Shape {
  const d = defaults[kind];
  const label = kind[0].toUpperCase() + kind.slice(1);
  return { id: crypto.randomUUID(), kind, name: `${label} ${n}`, x: x - d.w / 2, y: y - d.h / 2, ...d, fresh: true };
}

export function generatedCard(ox: number, oy: number): Shape[] {
  const id = crypto.randomUUID();
  return [
    { id: `g-${id}-0`, kind: 'frame', name: 'AI / Pricing card', x: ox, y: oy, w: 210, h: 230, fill: '#18181b', radius: 16, fresh: true },
    { id: `g-${id}-1`, kind: 'text', name: 'Plan', x: ox + 20, y: oy + 22, w: 120, h: 18, fill: '#a1a1aa', radius: 0, text: 'PRO PLAN', fresh: true },
    { id: `g-${id}-2`, kind: 'text', name: 'Price', x: ox + 20, y: oy + 48, w: 150, h: 40, fill: '#ffffff', radius: 0, text: '$24/mo', fresh: true },
    { id: `g-${id}-3`, kind: 'rect', name: 'Divider', x: ox + 20, y: oy + 104, w: 170, h: 2, fill: '#3f3f46', radius: 1, fresh: true },
    { id: `g-${id}-4`, kind: 'rect', name: 'Feature', x: ox + 20, y: oy + 124, w: 140, h: 10, fill: '#52525b', radius: 5, fresh: true },
    { id: `g-${id}-5`, kind: 'rect', name: 'Feature', x: ox + 20, y: oy + 144, w: 110, h: 10, fill: '#52525b', radius: 5, fresh: true },
    { id: `g-${id}-6`, kind: 'rect', name: 'CTA', x: ox + 20, y: oy + 178, w: 170, h: 34, fill: '#0d99ff', radius: 10, fresh: true },
  ];
}

import { Circle, Frame, Square, Trash2, Type } from 'lucide-react';
import { cn } from '@/lib/cn';
import { swatches, type Shape, type ShapeKind } from './editorModel';

export const kindIcon: Record<ShapeKind, typeof Frame> = { frame: Frame, rect: Square, ellipse: Circle, text: Type };

export function LayersPanel({ shapes, selected, onSelect }: { shapes: Shape[]; selected: string | null; onSelect: (id: string) => void }) {
  return (
    <aside className="hidden w-52 shrink-0 flex-col border-r border-zinc-200 bg-white lg:flex">
      <div className="flex items-center justify-between border-b border-zinc-200 px-4 py-3">
        <span className="text-xs font-semibold text-zinc-900">Layers</span>
        <span className="font-mono text-[10px] text-zinc-400">{shapes.length}</span>
      </div>
      <div className="flex-1 overflow-y-auto p-1.5">
        {[...shapes].reverse().map((s) => {
          const Icon = kindIcon[s.kind];
          const active = s.id === selected;
          return (
            <button
              key={s.id}
              onClick={() => onSelect(s.id)}
              className={cn(
                'flex w-full items-center gap-2 rounded-md px-2.5 py-1.5 text-left text-xs transition-colors',
                active ? 'bg-[#0d99ff]/10 text-[#0b7fd4]' : 'text-zinc-700 hover:bg-zinc-100',
                s.fresh && 'animate-slide-in-right',
              )}
            >
              <Icon className={cn('h-3.5 w-3.5 shrink-0', active ? 'text-[#0d99ff]' : 'text-zinc-400')} />
              <span className="truncate">{s.name}</span>
            </button>
          );
        })}
      </div>
    </aside>
  );
}

function NumField({ label, value, onChange }: { label: string; value: number; onChange: (v: number) => void }) {
  return (
    <label className="flex items-center gap-2 rounded-md bg-zinc-100 px-2 py-1.5 transition-colors focus-within:bg-white focus-within:ring-1 focus-within:ring-[#0d99ff]">
      <span className="w-3 text-[10px] font-medium text-zinc-400">{label}</span>
      <input
        type="number"
        value={Math.round(value)}
        onChange={(e) => {
          const n = Number(e.target.value);
          if (Number.isFinite(n)) onChange(n);
        }}
        className="w-full min-w-0 bg-transparent font-mono text-[11px] text-zinc-900 outline-none [appearance:textfield] [&::-webkit-inner-spin-button]:appearance-none"
      />
    </label>
  );
}

export function Inspector({ shape, onChange, onDelete }: { shape: Shape | null; onChange: (patch: Partial<Shape>) => void; onDelete: () => void }) {
  return (
    <aside className="hidden w-60 shrink-0 flex-col border-l border-zinc-200 bg-white xl:flex">
      <div className="flex items-center gap-4 border-b border-zinc-200 px-4 py-3 text-xs">
        <span className="font-semibold text-zinc-900">Design</span>
        <span className="text-zinc-400">Prototype</span>
        <span className="text-zinc-400">Inspect</span>
      </div>
      {shape ? (
        <div key={shape.id} className="flex-1 space-y-5 overflow-y-auto p-4 animate-fade-in">
          <div>
            <div className="flex items-center justify-between">
              <span className="truncate text-xs font-semibold text-zinc-900">{shape.name}</span>
              <button onClick={onDelete} aria-label="Delete layer" className="rounded p-1 text-zinc-400 transition-colors hover:bg-rose-50 hover:text-rose-600">
                <Trash2 className="h-3.5 w-3.5" />
              </button>
            </div>
            <div className="mt-3 grid grid-cols-2 gap-1.5">
              <NumField label="X" value={shape.x} onChange={(x) => onChange({ x })} />
              <NumField label="Y" value={shape.y} onChange={(y) => onChange({ y })} />
              <NumField label="W" value={shape.w} onChange={(w) => onChange({ w: Math.max(8, w) })} />
              <NumField label="H" value={shape.h} onChange={(h) => onChange({ h: Math.max(2, h) })} />
            </div>
          </div>
          {shape.kind !== 'ellipse' && shape.kind !== 'text' && (
            <div>
              <div className="flex justify-between text-[11px] text-zinc-500">
                <span>Corner radius</span>
                <span className="font-mono text-zinc-900">{shape.radius}</span>
              </div>
              <input
                type="range" min={0} max={40} value={shape.radius}
                onChange={(e) => onChange({ radius: Number(e.target.value) })}
                className="mt-2 w-full accent-[#0d99ff]"
              />
            </div>
          )}
          {shape.kind === 'text' && (
            <div>
              <span className="text-[11px] text-zinc-500">Content</span>
              <input
                value={shape.text ?? ''}
                onChange={(e) => onChange({ text: e.target.value })}
                className="mt-2 w-full rounded-md bg-zinc-100 px-2 py-1.5 text-xs text-zinc-900 outline-none focus:bg-white focus:ring-1 focus:ring-[#0d99ff]"
              />
            </div>
          )}
          <div>
            <span className="text-[11px] text-zinc-500">Fill</span>
            <div className="mt-2 grid grid-cols-8 gap-1.5">
              {swatches.map((c) => (
                <button
                  key={c}
                  onClick={() => onChange({ fill: c })}
                  aria-label={`Fill ${c}`}
                  className={cn('aspect-square rounded-md ring-1 ring-zinc-200 transition-transform hover:scale-110', shape.fill === c && 'ring-2 ring-[#0d99ff] ring-offset-1')}
                  style={{ background: c }}
                />
              ))}
            </div>
            <div className="mt-2 flex items-center gap-2 rounded-md bg-zinc-100 px-2 py-1.5 font-mono text-[11px] text-zinc-700">
              <span className="h-3.5 w-3.5 rounded-sm ring-1 ring-zinc-300" style={{ background: shape.fill }} />
              {shape.fill.toUpperCase()}
              <span className="ml-auto text-zinc-400">100%</span>
            </div>
          </div>
        </div>
      ) : (
        <div className="flex flex-1 flex-col items-center justify-center p-6 text-center">
          <Square className="h-6 w-6 text-zinc-300" />
          <p className="mt-3 text-xs leading-relaxed text-zinc-500">Select a layer to edit its size, radius and fill.</p>
        </div>
      )}
    </aside>
  );
}

