                <Avatar name={m.name} color={m.color} size={16} /> {m.name.split(' ')[0]} · {fmtDate(n.updated)}
                <span className="ml-auto truncate rounded-[4px] bg-[var(--sub)] px-1.5 py-px text-[var(--fg)]">{recordName(crm, n.target)}</span>
