export type Source = { title: string; domain: string; snippet: string };

export type Attachment = { id: string; name: string; size: number; kind: 'image' | 'file'; url?: string };

export type Artifact = { id: string; title: string; language: string; code: string };

export type Part =
  | { type: 'thinking'; text: string; shown: number; seconds: number; done: boolean }
  | { type: 'tool'; name: string; label: string; detail: string; done: boolean; sources?: Source[] }
  | { type: 'text'; text: string; shown: number }
  | { type: 'artifact'; artifact: Artifact; done: boolean }
  | { type: 'image'; prompt: string; urls: string[]; progress: number; aspect: 'square' | 'wide' }
  | { type: 'video'; prompt: string; poster: string; progress: number; seconds: number }
  | { type: 'error'; message: string };

export type Message =
  | { id: string; role: 'user'; text: string; attachments: Attachment[] }
  | { id: string; role: 'assistant'; parts: Part[]; status: 'streaming' | 'done' | 'stopped' | 'error'; model: string; rating?: 'up' | 'down' };

export type AssistantMessage = Extract<Message, { role: 'assistant' }>;

export type Conversation = { id: string; title: string; updatedAt: number; pinned?: boolean; messages: Message[] };

export type Mode = 'auto' | 'search' | 'image' | 'video' | 'code';

export type ModelId = 'opus' | 'sonnet' | 'haiku';

export type Model = { id: ModelId; name: string; blurb: string; speed: number; thinks: boolean };

import { artifacts, imageSets, searchSources, videoPosters } from './data';
import type { Artifact, Attachment, Mode, Source } from './types';

export type ScenarioCtx = {
  think: (text: string, seconds: number) => Promise<void>;
  tool: (name: string, label: string, detail: string, ms: number, sources?: Source[]) => Promise<void>;
  stream: (text: string) => Promise<void>;
  artifact: (a: Artifact) => Promise<void>;
  image: (prompt: string, urls: string[], aspect: 'square' | 'wide') => Promise<void>;
  video: (prompt: string, poster: string, seconds: number) => Promise<void>;
  fail: (message: string) => Promise<void>;
};

export type ScenarioInput = { text: string; attachments: Attachment[]; thinking: boolean; retry: boolean };

type ScenarioId = 'text' | 'search' | 'code' | 'image' | 'video' | 'files' | 'error';

export function pickScenario(text: string, mode: Mode, hasFiles: boolean): ScenarioId {
  if (mode !== 'auto') return mode;
  const t = text.toLowerCase();
  if (/\b(error|fail|break|crash)\b/.test(t)) return 'error';
  if (hasFiles) return 'files';
  if (/\b(video|clip|animate|film|footage|drone)\b/.test(t)) return 'video';
  if (/\b(image|picture|photo|draw|illustrat|render|art|logo|poster)\w*/.test(t)) return 'image';
  if (/\b(code|component|html|app|build|function|script|timer|pricing|website|ui)\b/.test(t)) return 'code';
  if (/\b(search|latest|news|research|today|current|trend|2026|sources?)\b/.test(t)) return 'search';
  return 'text';
}

const quoted = (s: string) => (s.length > 64 ? `${s.slice(0, 64).trim()}…` : s);

const scripts: Record<ScenarioId, (ctx: ScenarioCtx, input: ScenarioInput) => Promise<void>> = {
  async text(ctx, { text, thinking, retry }) {
    if (thinking) {
      await ctx.think(
        `The user wants a clear explanation of "${quoted(text)}". I should open with a one-line intuition, then build up in layers, use an analogy that fits their background, and finish with something they can act on. Keep it skimmable with short sections.`,
        3,
      );
    }
    await ctx.stream(
      `${retry ? 'Connection restored, here is the full answer.\n' : ''}## The short version\nThink of it as a **very attentive reader**. Every word looks at every other word and decides how much each one matters for understanding it.\n## How it works\n1. Text is split into small pieces called **tokens**.\n2. Each token asks the others "how relevant are you to me?", a step called **attention**.\n3. Those relevance scores blend information across the whole sentence, layer after layer.\n4. The final layer predicts the most likely next token, and the loop repeats.\n## Why designers should care\n- Context is everything: the clearer your prompt, the better the attention has to work with.\n- Streaming exists because the model genuinely produces one token at a time.\n- Long inputs cost more because every token attends to every other token.\nWant me to turn this into a one-page visual explainer?`,
    );
  },

  async search(ctx, { text, thinking }) {
    if (thinking) await ctx.think(`I need recent, credible sources for "${quoted(text)}". I'll search broadly, then narrow to research and practitioner writing, and synthesize the key trends with citations.`, 2);
    await ctx.tool('web_search', 'Searching the web', quoted(text), 1600, searchSources.slice(0, 2));
    await ctx.tool('web_search', 'Reading 4 sources', 'AI interface design research 2026', 1400, searchSources);
    await ctx.stream(
      `## What changed this year\n- **Agents became the default.** Most new launches are agentic, so showing intermediate steps is now table stakes [1].\n- **Transparency builds trust.** Products that expose sources and offer a clear stop control see higher retention [2].\n- **Perceived speed wins.** A first token under 400ms feels instant, even when the full answer takes longer [3].\n- **Multimodal is mainstream.** Image and short video quality roughly tripled on preference evals [4].\n## What it means for your product\nDesign for visible progress: thinking states, tool cards and citations, exactly like this answer.`,
    );
  },

  async code(ctx, { text, thinking }) {
    const a = /timer|pomodoro|clock|countdown/i.test(text) ? artifacts.timer : artifacts.pricing;
    if (thinking) await ctx.think(`Plan: a single self-contained HTML file so it previews instantly. Dark theme, accessible contrast, clear states. For "${quoted(text)}" I'll keep the logic small and readable and avoid external dependencies.`, 3);
    await ctx.stream(`I built a self-contained **${a.title.toLowerCase()}**. It runs as a single file with no dependencies, so you can preview it live on the right or copy the code straight into your project.`);
    await ctx.artifact(a);
    await ctx.stream(`\n## What's included\n- Fully responsive layout with hover and focus states\n- Accessible color contrast on a dark surface\n- Zero external dependencies\nAsk me to change colors, add states or convert it to React.`);
  },

  async image(ctx, { text, thinking }) {
    const urls = /city|neon|street|urban|night/i.test(text) ? imageSets.city : imageSets.nature;
    if (thinking) await ctx.think(`Translating "${quoted(text)}" into a detailed visual prompt: subject, lighting, lens, mood and composition. I'll generate four variations with slightly different framing.`, 2);
    await ctx.stream('Generating four variations for you now.');
    await ctx.image(text, urls, 'square');
    await ctx.stream('\nHover any image to download, upscale or create variations. Click to open it full size.');
  },

  async video(ctx, { text, thinking }) {
    if (thinking) await ctx.think(`Storyboarding "${quoted(text)}": one continuous 6-second shot, slow forward dolly, golden-hour grade, 24fps for a cinematic feel.`, 2);
    await ctx.tool('storyboard', 'Writing storyboard', '1 shot · 6s · 24fps · 16:9', 1200);
    await ctx.stream('Rendering your clip. Video takes a little longer than images.');
    await ctx.video(text, videoPosters[Math.floor(Math.random() * videoPosters.length)], 6);
    await ctx.stream('\nYour 6-second clip is ready. Press play to preview, or ask me to extend it or change the camera move.');
  },

  async files(ctx, { attachments, thinking }) {
    const names = attachments.map((a) => a.name).join(', ');
    await ctx.tool('read_files', `Reading ${attachments.length} file${attachments.length > 1 ? 's' : ''}`, quoted(names), 1500);
    if (thinking) await ctx.think('Scanning structure first, then pulling out the key facts, numbers and open questions. I will summarize, then suggest next steps.', 2);
    await ctx.stream(
      `## Summary of ${attachments.length > 1 ? 'your files' : `**${attachments[0].name}**`}\n- The document is well structured and easy to follow.\n- Three themes stand out: **timelines**, **budget** and **ownership**.\n- Two sections reference figures that are not sourced, worth double-checking.\n## Suggested next steps\n1. Add owners to every open item.\n2. Move the budget table up front.\n3. Cut the appendix by half.\nWant me to rewrite any section?`,
    );
  },

  async error(ctx, input) {
    if (input.retry) return scripts.text(ctx, input);
    await ctx.stream('Let me look into that');
    await ctx.fail('The connection was interrupted while generating this response. Nothing was lost, and you can retry.');
  },
};

export function runScenario(ctx: ScenarioCtx, input: ScenarioInput, mode: Mode) {
  const id = pickScenario(input.text, mode, input.attachments.length > 0);
  return scripts[id](ctx, input);
}

import { useMemo, useRef, useState } from 'react';
import { MessageSquare, MoreHorizontal, PanelLeftClose, Pencil, Pin, PinOff, Plus, Search, Sparkle, Trash2, X } from 'lucide-react';
import { cn } from '@/lib/cn';
import { useClickOutside } from '@/components/ui/motion/hooks';
import type { Conversation } from './types';

type Props = {
  conversations: Conversation[];
  activeId: string | null;
  onSelect: (id: string | null) => void;
  onRename: (id: string, title: string) => void;
  onPin: (id: string) => void;
  onDelete: (id: string) => void;
  onClose: () => void;
};

const DAY = 86_400_000;

function group(list: Conversation[]) {
  const now = Date.now();
  const sorted = [...list].sort((a, b) => b.updatedAt - a.updatedAt);
  const groups: { label: string; items: Conversation[] }[] = [
    { label: 'Pinned', items: sorted.filter((c) => c.pinned) },
    { label: 'Today', items: sorted.filter((c) => !c.pinned && now - c.updatedAt < DAY) },
    { label: 'Previous 7 days', items: sorted.filter((c) => !c.pinned && now - c.updatedAt >= DAY && now - c.updatedAt < 7 * DAY) },
    { label: 'Older', items: sorted.filter((c) => !c.pinned && now - c.updatedAt >= 7 * DAY) },
  ];
  return groups.filter((g) => g.items.length > 0);
}

export function Sidebar({ conversations, activeId, onSelect, onRename, onPin, onDelete, onClose }: Props) {
  const [query, setQuery] = useState('');
  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return q ? conversations.filter((c) => c.title.toLowerCase().includes(q)) : conversations;
  }, [conversations, query]);
  const groups = group(filtered);

  return (
    <aside className="flex h-full w-[272px] flex-col border-r border-white/[0.06] bg-ink-950">
      <div className="flex items-center justify-between px-3 pb-2 pt-3">
        <div className="flex items-center gap-2 px-1">
          <span className="grid h-7 w-7 place-items-center rounded-lg bg-gradient-to-br from-brand-400 to-sky-600 text-white"><Sparkle className="h-3.5 w-3.5 fill-current" /></span>
          <span className="text-sm font-semibold tracking-tight text-white">Nova</span>
        </div>
        <button onClick={onClose} aria-label="Close sidebar" className="grid h-8 w-8 place-items-center rounded-lg text-ink-400 transition-colors hover:bg-white/5 hover:text-white">
          <PanelLeftClose className="h-4 w-4" />
        </button>
      </div>

      <div className="space-y-2 px-3">
        <button onClick={() => onSelect(null)} className="group flex w-full items-center gap-2 rounded-xl border border-white/[0.08] bg-white/[0.03] px-3 py-2 text-sm font-medium text-ink-100 transition-all hover:border-white/15 hover:bg-white/[0.06]">
          <Plus className="h-4 w-4 transition-transform duration-300 group-hover:rotate-90" /> New chat
          <kbd className="ml-auto rounded border border-white/10 px-1.5 font-mono text-[10px] text-ink-500">⌘K</kbd>
        </button>
        <label className="flex items-center gap-2 rounded-xl bg-white/[0.03] px-3 py-2 text-ink-500 focus-within:ring-1 focus-within:ring-white/15">
          <Search className="h-3.5 w-3.5" />
          <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search chats" className="w-full bg-transparent text-sm text-ink-100 outline-none placeholder:text-ink-500" />
          {query && <button onClick={() => setQuery('')} aria-label="Clear search"><X className="h-3.5 w-3.5 hover:text-white" /></button>}
        </label>
      </div>

      <nav className="mt-3 flex-1 space-y-4 overflow-y-auto px-2 pb-4">
        {groups.length === 0 && <p className="px-3 py-6 text-center text-xs text-ink-500">{query ? 'No chats match your search' : 'No conversations yet'}</p>}
        {groups.map((g) => (
          <div key={g.label}>
            <div className="px-3 pb-1 text-[11px] font-medium uppercase tracking-wider text-ink-600">{g.label}</div>
            {g.items.map((c) => (
              <ChatRow key={c.id} c={c} active={c.id === activeId} onSelect={() => onSelect(c.id)} onRename={(t) => onRename(c.id, t)} onPin={() => onPin(c.id)} onDelete={() => onDelete(c.id)} />
            ))}
          </div>
        ))}
      </nav>

      <div className="border-t border-white/[0.06] p-3">
        <div className="flex items-center gap-3 rounded-xl p-2 transition-colors hover:bg-white/5">
          <span className="grid h-8 w-8 place-items-center rounded-full bg-gradient-to-br from-amber-300 to-rose-400 text-xs font-semibold text-ink-950">AL</span>
          <div className="min-w-0 flex-1">
            <div className="truncate text-sm font-medium text-ink-100">Alex Lindqvist</div>
            <div className="text-[11px] text-ink-500">Pro plan</div>
          </div>
        </div>
      </div>
    </aside>
  );
}

function ChatRow({ c, active, onSelect, onRename, onPin, onDelete }: { c: Conversation; active: boolean; onSelect: () => void; onRename: (t: string) => void; onPin: () => void; onDelete: () => void }) {
  const [menu, setMenu] = useState(false);
  const [editing, setEditing] = useState(false);
  const [confirm, setConfirm] = useState(false);
  const [draft, setDraft] = useState(c.title);
  const ref = useRef<HTMLDivElement>(null);
  useClickOutside([ref], menu, () => { setMenu(false); setConfirm(false); });

  if (editing) {
    return (
      <input
        autoFocus
        value={draft}
        onChange={(e) => setDraft(e.target.value)}
        onBlur={() => { onRename(draft); setEditing(false); }}
        onKeyDown={(e) => {
          if (e.key === 'Enter') { onRename(draft); setEditing(false); }
          if (e.key === 'Escape') { setDraft(c.title); setEditing(false); }
        }}
        className="w-full rounded-lg bg-ink-800 px-3 py-2 text-sm text-white outline-none ring-1 ring-brand-500/50"
      />
    );
  }

  return (
    <div ref={ref} className="group relative">
      <button
        onClick={onSelect}
        className={cn('flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left text-sm transition-colors', active ? 'bg-white/[0.08] text-white' : 'text-ink-300 hover:bg-white/[0.04] hover:text-ink-100')}
      >
        <MessageSquare className="h-3.5 w-3.5 shrink-0 opacity-50" />
        <span className="truncate pr-6">{c.title}</span>
      </button>
      <button
        onClick={() => setMenu((m) => !m)}
        aria-label="Chat options"
        className={cn('absolute right-1 top-1/2 grid h-6 w-6 -translate-y-1/2 place-items-center rounded-md text-ink-400 transition-opacity hover:bg-white/10 hover:text-white', menu ? 'opacity-100' : 'opacity-0 group-hover:opacity-100 focus:opacity-100')}
      >
        <MoreHorizontal className="h-4 w-4" />
      </button>
      {menu && (
        <div className="absolute right-0 top-9 z-30 w-44 rounded-xl border border-white/10 bg-ink-900 p-1 shadow-pop animate-scale-in">
          <MenuItem icon={Pencil} label="Rename" onClick={() => { setMenu(false); setDraft(c.title); setEditing(true); }} />
          <MenuItem icon={c.pinned ? PinOff : Pin} label={c.pinned ? 'Unpin' : 'Pin'} onClick={() => { setMenu(false); onPin(); }} />
          {confirm ? (
            <MenuItem icon={Trash2} label="Confirm delete" danger onClick={() => { setMenu(false); onDelete(); }} />
          ) : (
            <MenuItem icon={Trash2} label="Delete" danger onClick={() => setConfirm(true)} />
          )}
        </div>
      )}
    </div>
  );
}

function MenuItem({ icon: Icon, label, onClick, danger }: { icon: typeof Pin; label: string; onClick: () => void; danger?: boolean }) {
  return (
    <button onClick={onClick} className={cn('flex w-full items-center gap-2 rounded-lg px-2.5 py-1.5 text-sm transition-colors', danger ? 'text-rose-400 hover:bg-rose-500/10' : 'text-ink-200 hover:bg-white/5')}>
      <Icon className="h-3.5 w-3.5" /> {label}
    </button>
  );
}

import { useEffect, useState, type ReactNode, type RefObject } from 'react';
import { createPortal } from 'react-dom';

/**
 * Keeps an element mounted while it animates out.
 * `mounted` controls rendering, `visible` drives the enter/exit classes.
 */
export function usePresence(open: boolean, exitMs = 220) {
  const [mounted, setMounted] = useState(open);
  const [visible, setVisible] = useState(open);

  useEffect(() => {
    if (open) {
      setMounted(true);
      let inner = 0;
      const outer = requestAnimationFrame(() => {
        inner = requestAnimationFrame(() => setVisible(true));
      });
      return () => {
        cancelAnimationFrame(outer);
        cancelAnimationFrame(inner);
      };
    }
    setVisible(false);
    const t = window.setTimeout(() => setMounted(false), exitMs);
    return () => window.clearTimeout(t);
  }, [open, exitMs]);

  return { mounted, visible };
}

/** Calls `handler` when Escape is pressed while `active`. */
export function useEscape(active: boolean, handler: () => void) {
  useEffect(() => {
    if (!active) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') handler();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [active, handler]);
}

/** Calls `handler` on pointerdown outside every provided ref while `active`. */
export function useClickOutside(
  refs: Array<RefObject<HTMLElement>>,
  active: boolean,
  handler: () => void,
) {
  useEffect(() => {
    if (!active) return;
    const onDown = (e: PointerEvent) => {
      const target = e.target as Node;
      if (refs.some((r) => r.current?.contains(target))) return;
      handler();
    };
    document.addEventListener('pointerdown', onDown);
    return () => document.removeEventListener('pointerdown', onDown);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [active, handler]);
}

/**
 * Renders overlays into document.body so `position: fixed` is relative to the
 * viewport even when an ancestor has a transform (e.g. entrance animations).
 */
export function Portal({ children }: { children: ReactNode }) {
  if (typeof document === 'undefined') return null;
  return createPortal(children, document.body);
}

import { useEffect, useRef, useState, type DragEvent, type KeyboardEvent } from 'react';
import { ArrowUp, Brain, Check, ChevronDown, Clapperboard, Code2, Globe, ImageIcon, Paperclip, Square } from 'lucide-react';
import { cn } from '@/lib/cn';
import { useClickOutside } from '@/components/ui/motion/hooks';
import { models } from './data';
import { AttachmentChip } from './Message';
import type { Attachment, Mode, Model, ModelId } from './types';

const modes: { id: Exclude<Mode, 'auto'>; label: string; icon: typeof Globe; placeholder: string }[] = [
  { id: 'search', label: 'Search', icon: Globe, placeholder: 'Search the web for anything…' },
  { id: 'image', label: 'Image', icon: ImageIcon, placeholder: 'Describe the image you want…' },
  { id: 'video', label: 'Video', icon: Clapperboard, placeholder: 'Describe a shot, camera move and mood…' },
  { id: 'code', label: 'Code', icon: Code2, placeholder: 'Describe the component or app to build…' },
];

type Props = {
  onSend: (text: string, attachments: Attachment[], mode: Mode) => void;
  onStop: () => void;
  isStreaming: boolean;
  model: Model;
  onModel: (id: ModelId) => void;
  extended: boolean;
  onExtended: (v: boolean) => void;
  autoFocus?: boolean;
};

export function Composer({ onSend, onStop, isStreaming, model, onModel, extended, onExtended, autoFocus }: Props) {
  const [text, setText] = useState('');
  const [files, setFiles] = useState<Attachment[]>([]);
  const [mode, setMode] = useState<Mode>('auto');
  const [picker, setPicker] = useState(false);
  const [dragging, setDragging] = useState(false);
  const ta = useRef<HTMLTextAreaElement>(null);
  const fileInput = useRef<HTMLInputElement>(null);
  const pickerRef = useRef<HTMLDivElement>(null);
  useClickOutside([pickerRef], picker, () => setPicker(false));

  useEffect(() => {
    const el = ta.current;
    if (!el) return;
    el.style.height = '0px';
    el.style.height = `${Math.min(220, el.scrollHeight)}px`;
  }, [text]);

  useEffect(() => {
    if (autoFocus) ta.current?.focus();
  }, [autoFocus]);

  const addFiles = (list: FileList | null) => {
    if (!list) return;
    const next = Array.from(list).slice(0, 6).map<Attachment>((f) => ({
      id: crypto.randomUUID(),
      name: f.name,
      size: f.size,
      kind: f.type.startsWith('image/') ? 'image' : 'file',
      url: f.type.startsWith('image/') ? URL.createObjectURL(f) : undefined,
    }));
    setFiles((cur) => [...cur, ...next].slice(0, 6));
  };

  const canSend = (text.trim().length > 0 || files.length > 0) && !isStreaming;
  const submit = () => {
    if (!canSend) return;
    onSend(text.trim() || 'Summarize these files', files, mode);
    setText('');
    setFiles([]);
    setMode('auto');
  };

  const onKey = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
      e.preventDefault();
      submit();
    }
  };

  const onDrop = (e: DragEvent) => {
    e.preventDefault();
    setDragging(false);
    addFiles(e.dataTransfer.files);
  };

  const activeMode = modes.find((m) => m.id === mode);

  return (
    <div className="w-full">
      <div
        onDragOver={(e) => { e.preventDefault(); setDragging(true); }}
        onDragLeave={() => setDragging(false)}
        onDrop={onDrop}
        className={cn(
          'relative rounded-[22px] border bg-ink-900/90 shadow-[0_20px_60px_-20px_rgba(0,0,0,0.6)] backdrop-blur-xl transition-all duration-300',
          dragging ? 'border-brand-400 ring-4 ring-brand-500/15' : 'border-white/[0.08] focus-within:border-white/20',
        )}
      >
        {dragging && <div className="absolute inset-0 z-10 grid place-items-center rounded-[22px] bg-ink-950/80 text-sm font-medium text-brand-200">Drop files to attach</div>}
        {files.length > 0 && (
          <div className="flex flex-wrap gap-2 px-3 pt-3">
            {files.map((f) => <AttachmentChip key={f.id} a={f} onRemove={() => setFiles((cur) => cur.filter((x) => x.id !== f.id))} />)}
          </div>
        )}
        <textarea
          ref={ta}
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={onKey}
          rows={1}
          aria-label="Message"
          placeholder={activeMode?.placeholder ?? 'Ask Nova anything, or drop a file…'}
          className="block max-h-[220px] w-full resize-none bg-transparent px-4 pb-2 pt-4 text-[15px] leading-relaxed text-ink-50 outline-none placeholder:text-ink-500"
        />
        <div className="flex items-center gap-1 px-2 pb-2">
          <input ref={fileInput} type="file" multiple hidden onChange={(e) => { addFiles(e.target.files); e.target.value = ''; }} />
          <button onClick={() => fileInput.current?.click()} aria-label="Attach files" title="Attach files" className="grid h-9 w-9 place-items-center rounded-xl text-ink-400 transition-colors hover:bg-white/5 hover:text-ink-100">
            <Paperclip className="h-4 w-4" />
          </button>
          <div className="flex gap-1 overflow-x-auto">
            {modes.map((m) => (
              <button
                key={m.id}
                onClick={() => setMode(mode === m.id ? 'auto' : m.id)}
                className={cn(
                  'flex h-9 shrink-0 items-center gap-1.5 rounded-xl px-2.5 text-xs font-medium transition-all duration-200',
                  mode === m.id ? 'bg-brand-500/15 text-brand-200 ring-1 ring-brand-500/40' : 'text-ink-400 hover:bg-white/5 hover:text-ink-100',
                )}
              >
                <m.icon className="h-3.5 w-3.5" /><span className="hidden sm:inline">{m.label}</span>
              </button>
            ))}
          </div>

          <div ref={pickerRef} className="relative ml-auto">
