                    <button onClick={() => setZoom(url)} aria-label="Expand" className="grid h-7 w-7 place-items-center rounded-lg bg-white/15 text-white backdrop-blur hover:bg-white/25"><Maximize2 className="h-3.5 w-3.5" /></button>
