const tokenData = Array.from({ length: 24 }, (_, i) => ({ label: `${i}h`, value: 12000 + Math.sin(i / 3) * 6000 + Math.random() * 4000 }));

const costBreakdown = [
  { label: 'GPT-4o', value: 1840, color: '#38bdf8' },
  { label: 'Claude 3.5', value: 1120, color: '#34d399' },
