          </span>
          <span className="mt-1.5 block text-sm font-medium leading-snug text-ink-50">{source.title}</span>
          <span className="mt-1 line-clamp-3 block text-xs leading-relaxed text-ink-400">{source.snippet}</span>
        </span>
      )}
