import { Fragment, useEffect, useState } from 'react';
import { ArrowRight, Check, ChevronRight, CreditCard, RotateCcw, Route, Wrench } from 'lucide-react';
import { cn } from '@/lib/cn';

const TONE = {
  violet: { text: 'text-violet-300', bg: 'bg-violet-500/15', ring: 'ring-violet-400/40', dot: 'bg-violet-400' },
  emerald: { text: 'text-emerald-300', bg: 'bg-emerald-500/15', ring: 'ring-emerald-400/40', dot: 'bg-emerald-400' },
  sky: { text: 'text-brand-300', bg: 'bg-brand-500/15', ring: 'ring-brand-400/40', dot: 'bg-brand-400' },
  amber: { text: 'text-amber-300', bg: 'bg-amber-500/15', ring: 'ring-amber-400/40', dot: 'bg-amber-400' },
} as const;

export type HandoffAgent = { id: string; name: string; role: string; icon: typeof Route; tone: keyof typeof TONE };

export type HandoffEvent =
  | { type: 'user'; text: string }
  | { type: 'agent'; agent: string; text: string; tool?: { name: string; duration: string } }
  | { type: 'handoff'; from: string; to: string; reason: string; context: string[] };

export type AgentHandoffProps = {
  agents: HandoffAgent[];
  events: HandoffEvent[];
  /** Agent id currently composing a reply. */
  typing?: string | null;
  resolved?: boolean;
  onReplay?: () => void;
  className?: string;
};

function Avatar({ agent, size = 'md' }: { agent: HandoffAgent; size?: 'sm' | 'md' }) {
  const t = TONE[agent.tone];
  const Icon = agent.icon;
  return (
    <span className={cn('grid shrink-0 place-items-center rounded-full ring-1', t.bg, t.ring, t.text, size === 'md' ? 'h-8 w-8' : 'h-5 w-5')}>
      <Icon className={size === 'md' ? 'h-4 w-4' : 'h-2.5 w-2.5'} />
    </span>
  );
}

/** A multi-agent thread where ownership passes between specialists, with the context each handoff carries. */
export function AgentHandoff({ agents, events, typing = null, resolved = false, onReplay, className }: AgentHandoffProps) {
  const byId = (id: string) => agents.find((a) => a.id === id) ?? agents[0];
  const owners = [agents[0].id, ...events.flatMap((e) => (e.type === 'handoff' ? [e.to] : []))];

  return (
    <div className={cn('w-full overflow-hidden rounded-2xl bg-ink-900 shadow-card', className)}>
      <header className="flex flex-wrap items-center gap-x-1.5 gap-y-2 border-b border-white/5 px-4 py-3">
        <span className="mr-1 text-[11px] font-medium uppercase tracking-wider text-ink-500">Owners</span>
        {owners.map((id, i) => {
          const a = byId(id);
          const current = i === owners.length - 1;
          return (
            <Fragment key={`${id}-${i}`}>
              {i > 0 && <ChevronRight className="h-3.5 w-3.5 text-ink-600" />}
              <span className={cn('flex items-center gap-1.5 rounded-full py-0.5 pl-0.5 pr-2 text-xs transition-all duration-500 animate-fade-in', current ? 'bg-white/[0.06] text-ink-100 ring-1 ring-white/10' : 'text-ink-500')}>
                <Avatar agent={a} size="sm" />
                {a.name}
              </span>
            </Fragment>
          );
        })}
        <span className="ml-auto flex items-center gap-2">
          <span className={cn('flex items-center gap-1.5 rounded-full px-2 py-0.5 text-[11px] font-medium', resolved ? 'bg-emerald-500/10 text-emerald-300' : 'bg-brand-500/10 text-brand-300')}>
            {resolved ? <Check className="h-3 w-3" /> : <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-brand-400" />}
            {resolved ? 'Resolved' : 'Live'}
          </span>
          {onReplay && resolved && (
            <button onClick={onReplay} aria-label="Replay conversation" className="focus-ring grid h-7 w-7 place-items-center rounded-md text-ink-400 transition-colors hover:bg-white/5 hover:text-ink-100">
              <RotateCcw className="h-3.5 w-3.5" />
            </button>
          )}
        </span>
      </header>

      <div className="space-y-4 px-4 py-4" aria-live="polite">
        {events.map((e, i) => {
          if (e.type === 'user')
            return (
              <div key={i} className="flex justify-end animate-fade-up">
                <p className="max-w-[85%] rounded-2xl rounded-br-md bg-white/[0.07] px-3.5 py-2 text-sm leading-relaxed text-ink-100">{e.text}</p>
              </div>
            );
          if (e.type === 'agent') {
            const a = byId(e.agent);
            return (
              <div key={i} className="flex gap-3 animate-fade-up">
                <Avatar agent={a} />
                <div className="min-w-0 flex-1">
                  <p className="flex flex-wrap items-baseline gap-x-2 text-xs">
                    <span className={cn('font-medium', TONE[a.tone].text)}>{a.name}</span>
                    <span className="text-ink-500">{a.role}</span>
                  </p>
                  <p className="mt-1 text-sm leading-relaxed text-ink-200">{e.text}</p>
                  {e.tool && (
                    <span className="mt-2 inline-flex items-center gap-1.5 rounded-md bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-ink-400 ring-1 ring-white/5">
                      <Check className="h-3 w-3 text-emerald-400" />
                      {e.tool.name}
                      <span className="text-ink-600">·</span>
                      {e.tool.duration}
                    </span>
                  )}
                </div>
              </div>
            );
          }
          const from = byId(e.from);
          const to = byId(e.to);
          return (
            <div key={i} className="animate-fade-up py-1">
              <div className="flex items-center gap-2">
                <span className="h-px flex-1 bg-gradient-to-r from-transparent to-white/10" />
                <span className="flex items-center gap-1.5 rounded-full bg-ink-850 py-1 pl-1 pr-2.5 text-[11px] ring-1 ring-white/10">
                  <Avatar agent={from} size="sm" />
                  <ArrowRight className="h-3 w-3 text-ink-500" />
                  <Avatar agent={to} size="sm" />
                  <span className="text-ink-400">
                    Handed to <span className={cn('font-medium', TONE[to.tone].text)}>{to.name}</span>
                  </span>
                </span>
                <span className="h-px flex-1 bg-gradient-to-l from-transparent to-white/10" />
              </div>
              <div className="mx-auto mt-2 max-w-md rounded-xl border border-dashed border-white/10 bg-white/[0.02] px-3 py-2">
                <p className="text-[11px] text-ink-500">{e.reason}</p>
                <div className="mt-1.5 flex flex-wrap gap-1">
                  {e.context.map((c) => (
                    <span key={c} className="rounded-md bg-white/[0.05] px-1.5 py-0.5 font-mono text-[10.5px] text-ink-300">
                      {c}
                    </span>
                  ))}
                </div>
              </div>
            </div>
          );
        })}
        {typing && (
          <div className="flex items-center gap-3 animate-fade-in">
            <Avatar agent={byId(typing)} />
            <span className="flex items-center gap-1 rounded-full bg-white/[0.04] px-3 py-2">
              {[0, 1, 2].map((d) => (
                <span key={d} className="h-1.5 w-1.5 animate-pulse rounded-full bg-ink-400" style={{ animationDelay: `${d * 160}ms` }} />
              ))}
            </span>
            <span className="text-xs text-ink-500">{byId(typing).name} is replying…</span>
          </div>
        )}
      </div>
    </div>
  );
}

/* ——— demo ——— */

const AGENTS: HandoffAgent[] = [
  { id: 'triage', name: 'Triage', role: 'Routes requests', icon: Route, tone: 'violet' },
  { id: 'billing', name: 'Billing', role: 'Refunds and invoices', icon: CreditCard, tone: 'emerald' },
  { id: 'tech', name: 'Technical', role: 'API and integrations', icon: Wrench, tone: 'sky' },
];

const SCRIPT: { at: number; typing?: string; event: HandoffEvent }[] = [
  { at: 0, event: { type: 'user', text: 'I was charged twice this month, and now the export API keeps returning 500 errors.' } },
  { at: 700, typing: 'triage', event: { type: 'agent', agent: 'triage', text: 'Two separate issues: a duplicate charge and an API failure. Sending you to Billing first, Technical is next.' } },
  { at: 1300, event: { type: 'handoff', from: 'triage', to: 'billing', reason: 'Context passed to Billing', context: ['Ana Ruiz · Pro plan', 'Duplicate charge · Oct 2', 'Invoice #4821', 'Open: export API 500'] } },
  { at: 2000, typing: 'billing', event: { type: 'agent', agent: 'billing', text: 'Found it. I refunded $49.00 for invoice #4821. It will land in 3 to 5 business days.', tool: { name: 'billing.refund', duration: '0.8s' } } },
  { at: 2900, event: { type: 'handoff', from: 'billing', to: 'tech', reason: 'Context passed to Technical', context: ['Refund issued', 'Export API 500 since 09:14', 'Workspace acme-prod'] } },
  { at: 3900, typing: 'tech', event: { type: 'agent', agent: 'tech', text: 'The export timed out on a 2 GB CSV. I re-ran it with streaming enabled and your file is ready to download.', tool: { name: 'exports.retry', duration: '2.4s' } } },
];

export function AgentHandoffDemo() {
  const [run, setRun] = useState(0);
  const [shown, setShown] = useState(1);
  const [typing, setTyping] = useState<string | null>(null);

  useEffect(() => {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      setShown(SCRIPT.length);
      setTyping(null);
      return;
    }
    setShown(1);
    setTyping(null);
    const ids: number[] = [];
    SCRIPT.forEach((s, i) => {
      if (i === 0) return;
      const prev = SCRIPT[i - 1].at;
      if (s.typing) ids.push(window.setTimeout(() => setTyping(s.typing!), prev + 120));
      ids.push(
        window.setTimeout(() => {
          setTyping(null);
          setShown(i + 1);
        }, s.at),
      );
    });
    return () => ids.forEach(clearTimeout);
  }, [run]);

  return (
    <div className="mx-auto w-full max-w-xl">
      <AgentHandoff agents={AGENTS} events={SCRIPT.slice(0, shown).map((s) => s.event)} typing={typing} resolved={shown === SCRIPT.length} onReplay={() => setRun((r) => r + 1)} />
    </div>
  );
}

ai/plan-review.content:
import { useEffect, useRef, useState, type KeyboardEvent, type ReactNode } from 'react';
import { ArrowDown, ArrowUp, Check, Circle, ListChecks, Loader2, MessageSquareText, Play, Plus, RotateCcw, Sparkles } from 'lucide-react';
import { cn } from '@/lib/cn';

export type PlanStep = { id: string; text: string; enabled?: boolean; /** Simulated run time in ms. */ duration?: number };
type Step = Required<PlanStep> & { isNew?: boolean };
type Status = 'draft' | 'changes' | 'revising' | 'running' | 'done';

export type PlanReviewProps = {
  title: string;
  steps: PlanStep[];
  /** Step the agent adds when changes are requested. */
  revision?: { after: number; text: string };
  className?: string;
};

const STATUS: Record<Status, { label: string; className: string }> = {
  draft: { label: 'Awaiting approval', className: 'bg-amber-500/10 text-amber-300' },
  changes: { label: 'Requesting changes', className: 'bg-white/[0.06] text-ink-300' },
  revising: { label: 'Revising', className: 'bg-brand-500/10 text-brand-300' },
  running: { label: 'Running', className: 'bg-brand-500/10 text-brand-300' },
  done: { label: 'Complete', className: 'bg-emerald-500/10 text-emerald-300' },
};

function IconButton({ label, onClick, disabled, children }: { label: string; onClick: () => void; disabled?: boolean; children: ReactNode }) {
  return (
    <button onClick={onClick} disabled={disabled} aria-label={label} title={label} className="focus-ring grid h-7 w-7 place-items-center rounded-md text-ink-400 transition-colors hover:bg-white/5 hover:text-ink-100 disabled:pointer-events-none disabled:opacity-25">
      {children}
    </button>
  );
}

/** An editable agent plan: reorder, rewrite, skip or add steps, then approve and watch it run. */
export function PlanReview({ title, steps: initial, revision, className }: PlanReviewProps) {
  const make = (s: PlanStep): Step => ({ enabled: true, duration: 1200, ...s });
  const [steps, setSteps] = useState<Step[]>(() => initial.map(make));
  const [status, setStatus] = useState<Status>('draft');
  const [editing, setEditing] = useState<string | null>(null);
  const [draft, setDraft] = useState('');
  const [moved, setMoved] = useState<string | null>(null);
  const [feedback, setFeedback] = useState('');
  const [note, setNote] = useState<string | null>(null);
  const [active, setActive] = useState(-1);
  const [progress, setProgress] = useState(0);
  const [elapsed, setElapsed] = useState(0);
  const timers = useRef<number[]>([]);
  useEffect(() => () => timers.current.forEach(clearTimeout), []);

  const runnable = steps.filter((s) => s.enabled);

  // Execute enabled steps one after another.
  useEffect(() => {
    if (status !== 'running') return;
    const order = steps.filter((s) => s.enabled);
    let i = 0;
    let start = performance.now();
    const t0 = start;
    setActive(0);
    setProgress(0);
    const id = window.setInterval(() => {
      const now = performance.now();
      setElapsed(now - t0);
      const p = (now - start) / order[i].duration;
      if (p < 1) return setProgress(p);
      i += 1;
      start = now;
      setProgress(0);
      if (i >= order.length) {
        window.clearInterval(id);
        setActive(order.length);
        setStatus('done');
      } else setActive(i);
    }, 40);
    return () => window.clearInterval(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [status]);

  const flash = (id: string) => {
    setMoved(id);
    timers.current.push(window.setTimeout(() => setMoved((m) => (m === id ? null : m)), 700));
  };
  const move = (i: number, dir: -1 | 1) =>
    setSteps((s) => {
      const n = [...s];
      [n[i], n[i + dir]] = [n[i + dir], n[i]];
      flash(n[i + dir].id);
      return n;
    });
  const startEdit = (s: Step) => {
    setEditing(s.id);
    setDraft(s.text);
  };
  const commit = () => {
    if (editing && draft.trim()) setSteps((s) => s.map((x) => (x.id === editing ? { ...x, text: draft.trim() } : x)));
    setEditing(null);
  };
  const onKey = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') commit();
    if (e.key === 'Escape') setEditing(null);
  };
  const add = () => {
    const id = `new-${Date.now()}`;
    setSteps((s) => [...s, { id, text: '', enabled: true, duration: 1000, isNew: true }]);
    setEditing(id);
    setDraft('');
  };
  const sendChanges = () => {
    setStatus('revising');
    timers.current.push(
      window.setTimeout(() => {
        if (revision) {
          const id = `rev-${Date.now()}`;
          setSteps((s) => {
            const n = [...s];
            n.splice(Math.min(revision.after, n.length), 0, { id, text: revision.text, enabled: true, duration: 1100, isNew: true });
            return n;
          });
          flash(id);
        }
        setNote('Plan updated with your feedback · 1 step added');
        setFeedback('');
        setStatus('draft');
      }, 1300),
    );
  };
  const reset = () => {
    setSteps(initial.map(make));
    setStatus('draft');
    setActive(-1);
    setElapsed(0);
    setNote(null);
  };

  const live = status === 'running' || status === 'done';
  const overall = live ? Math.min(1, (Math.max(0, active) + (status === 'done' ? 0 : progress)) / Math.max(1, runnable.length)) : 0;
  let runIndex = -1;

  return (
    <div className={cn('w-full overflow-hidden rounded-2xl bg-ink-900 shadow-card', className)}>
      <div className="relative h-0.5 bg-white/[0.04]">
        <div className="absolute inset-y-0 left-0 bg-brand-400 transition-[width] duration-200" style={{ width: `${overall * 100}%` }} />
      </div>
      <header className="flex flex-wrap items-start gap-3 px-4 pb-3 pt-4">
        <span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-white/5 text-ink-200">
          <ListChecks className="h-[18px] w-[18px]" />
        </span>
        <div className="min-w-0 flex-1">
          <p className="text-sm font-medium text-ink-50">Proposed plan</p>
          <p className="truncate text-xs text-ink-500">
            {title} · {runnable.length} steps
          </p>
        </div>
        <span className={cn('shrink-0 rounded-full px-2 py-0.5 text-[11px] font-medium', STATUS[status].className)}>{STATUS[status].label}</span>
      </header>

      {note && status === 'draft' && (
        <p className="mx-4 mb-2 flex items-center gap-1.5 rounded-lg bg-brand-500/[0.07] px-2.5 py-1.5 text-xs text-brand-200 animate-fade-in">
          <Sparkles className="h-3.5 w-3.5" /> {note}
        </p>
      )}

      <ol className={cn('space-y-0.5 px-2 pb-2 transition-opacity', status === 'revising' && 'opacity-50')}>
        {steps.map((s, i) => {
          if (s.enabled) runIndex += 1;
          const ri = runIndex;
          const state = !live || !s.enabled ? 'idle' : ri < active ? 'done' : ri === active && status === 'running' ? 'running' : status === 'done' ? 'done' : 'queued';
          return (
            <li key={s.id} className={cn('group relative rounded-xl px-2.5 py-2 transition-colors duration-500', moved === s.id ? 'bg-brand-500/[0.08]' : 'hover:bg-white/[0.02]', !s.enabled && 'opacity-45')}>
              <div className="flex items-start gap-2.5">
                {live ? (
                  <span className="mt-0.5 grid h-[18px] w-[18px] shrink-0 place-items-center">
                    {state === 'done' && <Check className="h-4 w-4 text-emerald-400 animate-scale-in" />}
                    {state === 'running' && <Loader2 className="h-4 w-4 animate-spin text-brand-400" />}
                    {(state === 'queued' || state === 'idle') && <Circle className="h-3.5 w-3.5 text-ink-600" />}
                  </span>
                ) : (
                  <button
                    role="checkbox"
                    aria-checked={s.enabled}
                    aria-label={`Include step ${i + 1}`}
                    onClick={() => setSteps((x) => x.map((y) => (y.id === s.id ? { ...y, enabled: !y.enabled } : y)))}
                    className={cn('focus-ring mt-0.5 grid h-[18px] w-[18px] shrink-0 place-items-center rounded-[6px] ring-1 transition-colors', s.enabled ? 'bg-brand-500 text-white ring-brand-400' : 'ring-white/20 hover:ring-white/40')}
                  >
                    {s.enabled && <Check className="h-3 w-3" strokeWidth={3} />}
                  </button>
                )}
                <span className="mt-0.5 w-5 shrink-0 font-mono text-[11px] tabular-nums text-ink-500">{String(i + 1).padStart(2, '0')}</span>
                {editing === s.id ? (
                  <input
                    autoFocus
                    value={draft}
                    onChange={(e) => setDraft(e.target.value)}
                    onKeyDown={onKey}
                    onBlur={commit}
                    placeholder="Describe the step…"
                    aria-label={`Step ${i + 1}`}
                    className="-my-1 min-w-0 flex-1 rounded-md bg-ink-950/60 px-2 py-1 text-sm text-ink-50 outline-none ring-1 ring-brand-400/50 placeholder:text-ink-600"
                  />
                ) : (
                  <button
                    onClick={() => !live && status !== 'revising' && startEdit(s)}
                    disabled={live}
                    aria-label={`Edit step ${i + 1}: ${s.text}`}
                    className={cn('focus-ring min-w-0 flex-1 rounded-md text-left text-sm leading-snug transition-colors', state === 'running' ? 'shimmer-text font-medium' : 'text-ink-200 enabled:hover:text-ink-50', !s.enabled && 'line-through decoration-ink-500')}
                  >
                    {s.text || <span className="text-ink-600">Untitled step</span>}
                    {s.isNew && <span className="ml-2 rounded bg-brand-500/15 px-1.5 py-px align-middle text-[10px] font-medium text-brand-300">new</span>}
                  </button>
                )}
                {!live && editing !== s.id && (
                  <span className="flex shrink-0 items-center opacity-100 transition-opacity sm:opacity-0 sm:group-focus-within:opacity-100 sm:group-hover:opacity-100">
                    <IconButton label={`Move step ${i + 1} up`} onClick={() => move(i, -1)} disabled={i === 0}>
                      <ArrowUp className="h-3.5 w-3.5" />
                    </IconButton>
                    <IconButton label={`Move step ${i + 1} down`} onClick={() => move(i, 1)} disabled={i === steps.length - 1}>
                      <ArrowDown className="h-3.5 w-3.5" />
                    </IconButton>
                  </span>
                )}
              </div>
              {state === 'running' && (
                <div className="ml-[58px] mt-2 h-1 overflow-hidden rounded-full bg-white/[0.06]">
                  <div className="h-full rounded-full bg-brand-400" style={{ width: `${progress * 100}%` }} />
                </div>
              )}
            </li>
          );
        })}
      </ol>

      {status === 'changes' && (
        <div className="mx-4 mb-3 animate-fade-in">
          <textarea
            autoFocus
            value={feedback}
            onChange={(e) => setFeedback(e.target.value)}
            rows={2}
            placeholder="e.g. Add a rollback before the rollout"
            aria-label="Feedback for the agent"
            className="w-full resize-none rounded-xl bg-ink-950/60 px-3 py-2 text-sm text-ink-100 outline-none ring-1 ring-white/10 placeholder:text-ink-600 focus:ring-brand-400/50"
          />
        </div>
      )}

      <footer className="flex flex-wrap items-center gap-2 border-t border-white/5 px-4 py-3">
        {status === 'draft' && (
          <>
            <button onClick={add} className="focus-ring flex h-8 items-center gap-1.5 rounded-lg px-2 text-xs text-ink-400 transition-colors hover:bg-white/5 hover:text-ink-100">
              <Plus className="h-3.5 w-3.5" /> Add step
            </button>
            <span className="ml-auto flex flex-wrap justify-end gap-2">
              <button onClick={() => setStatus('changes')} className="focus-ring flex h-8 items-center gap-1.5 whitespace-nowrap rounded-lg px-3 text-xs font-medium text-ink-200 ring-1 ring-white/10 transition-colors hover:bg-white/5">
                <MessageSquareText className="h-3.5 w-3.5" /> Request changes
              </button>
              <button onClick={() => setStatus('running')} disabled={!runnable.length} className="focus-ring flex h-8 items-center gap-1.5 whitespace-nowrap rounded-lg bg-brand-500 px-3 text-xs font-medium text-white shadow-glow transition-all hover:bg-brand-400 active:scale-[0.97] disabled:opacity-40">
                <Play className="h-3.5 w-3.5 fill-current" /> Approve & run
              </button>
            </span>
          </>
        )}
        {status === 'changes' && (
          <span className="ml-auto flex gap-2">
            <button onClick={() => setStatus('draft')} className="focus-ring h-8 rounded-lg px-3 text-xs text-ink-400 hover:bg-white/5 hover:text-ink-100">
              Cancel
            </button>
            <button onClick={sendChanges} className="focus-ring flex h-8 items-center gap-1.5 rounded-lg bg-white px-3 text-xs font-medium text-ink-950 transition-all hover:bg-ink-100 active:scale-[0.97]">
              <Sparkles className="h-3.5 w-3.5" /> Send to agent
            </button>
          </span>
        )}
        {status === 'revising' && <span className="shimmer-text text-xs font-medium">Revising the plan…</span>}
        {live && (
          <>
            <span className="font-mono text-xs tabular-nums text-ink-400">
              {status === 'done' ? `Done · ${runnable.length} steps in ${(elapsed / 1000).toFixed(1)}s` : `Step ${Math.min(active + 1, runnable.length)} of ${runnable.length} · ${(elapsed / 1000).toFixed(1)}s`}
            </span>
            {status === 'done' && (
              <button onClick={reset} className="focus-ring ml-auto flex h-8 items-center gap-1.5 rounded-lg px-2.5 text-xs text-ink-400 transition-colors hover:bg-white/5 hover:text-ink-100">
                <RotateCcw className="h-3.5 w-3.5" /> Reset
              </button>
            )}
          </>
        )}
      </footer>
    </div>
  );
}

/* ——— demo ——— */

const STEPS: PlanStep[] = [
  { id: 'a', text: 'Audit the current auth middleware and session usage', duration: 1100 },
  { id: 'b', text: 'Add the OAuth provider config behind a feature flag', duration: 1300 },
  { id: 'c', text: 'Move session storage from cookies to signed tokens', duration: 1500 },
  { id: 'd', text: 'Write integration tests for login and token refresh', duration: 1200 },
  { id: 'e', text: 'Roll out to 10% of users and watch error rates', duration: 1000 },
];

export function PlanReviewDemo() {
  return (
    <div className="mx-auto w-full max-w-xl">
      <PlanReview title="Migrate auth to OAuth" steps={STEPS} revision={{ after: 3, text: 'Add a one-click rollback for the token migration' }} />
    </div>
  );
}

ai/knowledge-base.content:
import { Fragment, useEffect, useMemo, useRef, useState, type FormEvent } from 'react';
import { Check, ChevronDown, Database, FileCode2, FileSpreadsheet, FileText, Plus, Search } from 'lucide-react';
import { cn } from '@/lib/cn';

export type KbFile = {
  id: string;
  name: string;
  kind: 'pdf' | 'md' | 'csv' | 'doc';
  size: string;
  units: number;
  chunks: number;
  tokens: number;
  /** 0 → 4 through upload, parse, chunk, embed. 4 means ready. */
  stage: number;
};
export type KbChunk = { file: string; where: string; text: string };

const STAGES = ['Upload', 'Parse', 'Chunk', 'Embed'];
const ICON = { pdf: FileText, doc: FileText, md: FileCode2, csv: FileSpreadsheet };
const UNIT = { pdf: 'pages', doc: 'pages', md: 'sections', csv: 'rows' };
const STOP = new Set(['the', 'and', 'for', 'how', 'what', 'does', 'with', 'are', 'can', 'our', 'your', 'you', 'work', 'is', 'do']);

const fmt = (n: number) => (n >= 1000 ? `${(n / 1000).toFixed(1)}k` : String(Math.round(n)));
const terms = (q: string) => q.toLowerCase().split(/[^a-z0-9]+/).filter((w) => w.length > 2 && !STOP.has(w)).map((w) => w.slice(0, 5));

function Highlight({ text, words }: { text: string; words: string[] }) {
  if (!words.length) return <>{text}</>;
  const re = new RegExp(`(\\b(?:${words.join('|')})[a-z]*)`, 'gi');
  return (
    <>
      {text.split(re).map((part, i) =>
        i % 2 ? (
          <mark key={i} className="rounded-[3px] bg-brand-400/20 px-0.5 text-brand-100">
            {part}
          </mark>
        ) : (
          <Fragment key={i}>{part}</Fragment>
        ),
      )}
    </>
  );
}

function FileRow({ f }: { f: KbFile }) {
  const Icon = ICON[f.kind];
  const ready = f.stage >= 4;
  const k = Math.min(3, Math.floor(f.stage));
  const units = f.stage >= 2 ? f.units : 0;
  const chunks = f.chunks * Math.min(1, Math.max(0, f.stage - 2));
  const tokens = f.tokens * Math.min(1, Math.max(0, f.stage - 3));
  return (
    <li className="rounded-xl bg-white/[0.02] p-3 ring-1 ring-white/5 animate-fade-up">
      <div className="flex items-center gap-2.5">
        <span className="grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-white/5 text-ink-300">
          <Icon className="h-4 w-4" />
        </span>
        <span className="min-w-0 flex-1">
          <span className="block truncate text-sm text-ink-100">{f.name}</span>
          <span className="block font-mono text-[11px] tabular-nums text-ink-500">
            {f.size} · {units ? `${units} ${UNIT[f.kind]}` : '—'} · {fmt(chunks)} chunks · {fmt(tokens)} tokens
          </span>
        </span>
        {ready ? (
          <span className="flex shrink-0 items-center gap-1 rounded-full bg-emerald-500/10 px-2 py-0.5 text-[11px] font-medium text-emerald-300">
            <Check className="h-3 w-3" /> Ready
          </span>
        ) : (
          <span className="shrink-0 font-mono text-[11px] tabular-nums text-brand-300">{Math.round((f.stage / 4) * 100)}%</span>
        )}
      </div>
      {!ready && (
        <div className="mt-2.5">
          <div className="grid grid-cols-4 gap-1">
            {STAGES.map((s, i) => (
              <span key={s} className="h-1 overflow-hidden rounded-full bg-white/[0.06]">
                <span className={cn('block h-full rounded-full', i < k ? 'bg-brand-400/70' : 'bg-brand-400')} style={{ width: `${Math.min(1, Math.max(0, f.stage - i)) * 100}%` }} />
              </span>
            ))}
          </div>
          <p className="mt-1.5 text-[11px] text-ink-500">
            <span className="shimmer-text font-medium">{['Uploading', 'Parsing', 'Chunking', 'Embedding'][k]}…</span>
          </p>
        </div>
      )}
    </li>
  );
}

export type KnowledgeBaseProps = {
  name: string;
  files: KbFile[];
  chunks: KbChunk[];
  library?: KbFile[];
  examples?: string[];
  defaultQuery?: string;
  className?: string;
};

/** Sources indexed through upload, parse, chunk and embed, plus a retrieval tester that only searches ready files. */
export function KnowledgeBase({ name, files: initial, chunks, library = [], examples = [], defaultQuery = '', className }: KnowledgeBaseProps) {
  const [files, setFiles] = useState(initial);
  const [menu, setMenu] = useState(false);
  const [query, setQuery] = useState(defaultQuery);
  const [asked, setAsked] = useState(defaultQuery);
  const menuRef = useRef<HTMLDivElement>(null);
  const indexing = files.some((f) => f.stage < 4);

  useEffect(() => {
    if (!indexing) return;
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      setFiles((fs) => fs.map((f) => ({ ...f, stage: 4 })));
      return;
    }
    const id = window.setInterval(() => setFiles((fs) => fs.map((f) => (f.stage < 4 ? { ...f, stage: Math.min(4, f.stage + 0.025) } : f))), 50);
    return () => window.clearInterval(id);
  }, [indexing]);

  useEffect(() => {
    if (!menu) return;
    const close = (e: PointerEvent) => !menuRef.current?.contains(e.target as Node) && setMenu(false);
    document.addEventListener('pointerdown', close);
    return () => document.removeEventListener('pointerdown', close);
  }, [menu]);

  const ready = new Set(files.filter((f) => f.stage >= 4).map((f) => f.name));
  const words = terms(asked);
  const results = useMemo(() => {
    if (!words.length) return [];
    return chunks
      .filter((c) => ready.has(c.file))
      .map((c) => {
        const t = c.text.toLowerCase();
        const hits = words.reduce((n, w) => n + (t.match(new RegExp(`\\b${w}`, 'g'))?.length ?? 0), 0);
        const covered = words.filter((w) => new RegExp(`\\b${w}`).test(t)).length / words.length;
        return { c, score: hits ? 0.55 + covered * 0.33 + Math.min(0.09, hits * 0.02) : 0 };
      })
      .filter((r) => r.score > 0)
      .sort((a, b) => b.score - a.score)
      .slice(0, 3);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [asked, chunks, files.filter((f) => f.stage >= 4).length]);

  const remaining = library.filter((l) => !files.some((f) => f.name === l.name));
  const total = files.reduce((a, f) => ({ chunks: a.chunks + (f.stage >= 4 ? f.chunks : 0), tokens: a.tokens + (f.stage >= 4 ? f.tokens : 0) }), { chunks: 0, tokens: 0 });

  const ask = (q: string) => {
    setQuery(q);
    setAsked(q);
  };
  const submit = (e: FormEvent) => {
    e.preventDefault();
    setAsked(query);
  };

  return (
    <div className={cn('grid w-full grid-cols-[minmax(0,1fr)] gap-3 md:grid-cols-2', className)}>
      <section className="rounded-2xl bg-ink-900 p-4 shadow-card">
        <header className="flex items-center gap-2.5">
          <span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-white/5 text-ink-200">
            <Database className="h-[18px] w-[18px]" />
          </span>
          <div className="min-w-0 flex-1">
            <p className="truncate text-sm font-medium text-ink-50">{name}</p>
            <p className="font-mono text-[11px] tabular-nums text-ink-500">
              {files.length} sources · {fmt(total.chunks)} chunks · {fmt(total.tokens)} tokens
            </p>
          </div>
          <div ref={menuRef} className="relative shrink-0">
            <button onClick={() => setMenu((m) => !m)} disabled={!remaining.length} aria-expanded={menu} aria-haspopup="menu" className="focus-ring flex h-8 items-center gap-1 rounded-lg px-2.5 text-xs font-medium text-ink-200 ring-1 ring-white/10 transition-colors hover:bg-white/5 disabled:opacity-40">
              <Plus className="h-3.5 w-3.5" /> Add
              <ChevronDown className={cn('h-3 w-3 transition-transform', menu && 'rotate-180')} />
            </button>
            {menu && (
              <div role="menu" className="absolute right-0 top-[calc(100%+6px)] z-20 w-56 rounded-xl bg-ink-850 p-1 shadow-pop animate-scale-in">
                {remaining.map((l) => {
                  const Icon = ICON[l.kind];
                  return (
                    <button
                      key={l.id}
                      role="menuitem"
                      onClick={() => {
                        setFiles((fs) => [...fs, { ...l, stage: 0 }]);
                        setMenu(false);
                      }}
                      className="focus-ring flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-left text-xs text-ink-200 hover:bg-white/5"
                    >
                      <Icon className="h-3.5 w-3.5 text-ink-400" />
                      <span className="min-w-0 flex-1 truncate">{l.name}</span>
                      <span className="font-mono text-[10px] text-ink-500">{l.size}</span>
                    </button>
                  );
                })}
              </div>
            )}
          </div>
        </header>
        <ul className="mt-3 space-y-2">
          {files.map((f) => (
            <FileRow key={f.id} f={f} />
          ))}
        </ul>
      </section>

      <section className="flex min-w-0 flex-col rounded-2xl bg-ink-900 p-4 shadow-card">
        <p className="text-sm font-medium text-ink-50">Test retrieval</p>
        <p className="text-xs text-ink-500">Searches only sources that finished indexing.</p>
        <form onSubmit={submit} className="mt-3 flex items-center gap-2 rounded-xl bg-ink-950/60 px-3 ring-1 ring-white/10 transition-shadow focus-within:ring-brand-400/50">
          <Search className="h-4 w-4 shrink-0 text-ink-500" />
          <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Ask your knowledge base…" aria-label="Retrieval query" className="h-10 min-w-0 flex-1 bg-transparent text-sm text-ink-100 outline-none placeholder:text-ink-600" />
          <kbd className="hidden rounded bg-white/5 px-1.5 font-mono text-[10px] text-ink-500 sm:block">↵</kbd>
        </form>
        <div className="mt-2 flex flex-wrap gap-1.5">
          {examples.map((q) => (
            <button key={q} onClick={() => ask(q)} className={cn('focus-ring rounded-full px-2.5 py-1 text-[11px] transition-colors', asked === q ? 'bg-brand-500/15 text-brand-200' : 'bg-white/[0.04] text-ink-400 hover:text-ink-100')}>
              {q}
            </button>
          ))}
        </div>
        <div className="mt-3 min-h-0 flex-1 space-y-2" aria-live="polite">
          {asked && (
            <p className="font-mono text-[11px] text-ink-500">
              {results.length ? `${results.length} chunks · ${42 + asked.length * 3}ms` : 'No matches in ready sources yet'}
            </p>
          )}
          {results.map(({ c, score }, i) => (
            <article key={`${asked}-${c.file}-${c.where}`} className="rounded-xl bg-white/[0.02] p-3 ring-1 ring-white/5 animate-fade-up" style={{ animationDelay: `${i * 70}ms` }}>
              <div className="flex items-center gap-2">
                <span className="font-mono text-[11px] tabular-nums text-brand-300">{score.toFixed(2)}</span>
                <span className="h-1 w-16 overflow-hidden rounded-full bg-white/[0.06]">
                  <span className="block h-full rounded-full bg-brand-400" style={{ width: `${score * 100}%` }} />
                </span>
                <span className="ml-auto truncate font-mono text-[10.5px] text-ink-500">
                  {c.file} · {c.where}
                </span>
              </div>
              <p className="mt-1.5 text-[13px] leading-relaxed text-ink-300">
                <Highlight text={c.text} words={words} />
              </p>
            </article>
          ))}
        </div>
      </section>
    </div>
  );
}

/* ——— demo ——— */

const FILES: KbFile[] = [
  { id: 'f1', name: 'refund-policy.pdf', kind: 'pdf', size: '1.2 MB', units: 12, chunks: 48, tokens: 18200, stage: 4 },
  { id: 'f2', name: 'api-reference.md', kind: 'md', size: '340 KB', units: 34, chunks: 126, tokens: 51400, stage: 4 },
  { id: 'f3', name: 'pricing-2026.pdf', kind: 'pdf', size: '2.8 MB', units: 18, chunks: 64, tokens: 23900, stage: 1.6 },
];
const LIBRARY: KbFile[] = [
  { id: 'l1', name: 'support-macros.csv', kind: 'csv', size: '88 KB', units: 240, chunks: 31, tokens: 9800, stage: 0 },
  { id: 'l2', name: 'onboarding-guide.docx', kind: 'doc', size: '760 KB', units: 9, chunks: 27, tokens: 10400, stage: 0 },
];
const CHUNKS: KbChunk[] = [
  { file: 'refund-policy.pdf', where: 'p.4', text: 'Refunds are issued to the original payment method within 5 business days. Annual plans can be refunded in full within 30 days of purchase.' },
  { file: 'refund-policy.pdf', where: 'p.6', text: 'Duplicate charges are refunded automatically once billing confirms the second transaction. No ticket is needed.' },
  { file: 'api-reference.md', where: '§ Rate limits', text: 'The API allows 600 requests per minute per workspace. Exceeding the rate limit returns 429 with a Retry-After header.' },
  { file: 'api-reference.md', where: '§ Exports', text: 'Large exports run as background jobs. Poll the job endpoint or subscribe to the export.completed webhook.' },
  { file: 'pricing-2026.pdf', where: 'p.2', text: 'Enterprise pricing starts at 40 seats with SSO, audit logs and a dedicated success manager. Annual billing only.' },
  { file: 'pricing-2026.pdf', where: 'p.5', text: 'Seats can be added at any time and are prorated. Refunds for removed seats are applied as account credit.' },
  { file: 'support-macros.csv', where: 'row 112', text: 'Macro: double charge. Apologize, confirm the refund timeline of 5 business days, and link the refund policy.' },
  { file: 'onboarding-guide.docx', where: 'p.3', text: 'Invite teammates from Settings → Members. New members inherit the workspace rate limits and export permissions.' },
];

export function KnowledgeBaseDemo() {
  return (
    <KnowledgeBase
      name="Support knowledge"
      files={FILES}
      library={LIBRARY}
      chunks={CHUNKS}
      examples={['How do refunds work?', 'API rate limits', 'Enterprise pricing']}
      defaultQuery="How do refunds work?"
    />
  );
}

ai/agent-builder.content:
import { useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { ArrowUp, Bot, Calculator, CalendarDays, Check, FileText, Globe, Headphones, Leaf, Library, Loader2, Plus, Rocket, Sparkles, X } from 'lucide-react';
import { cn } from '@/lib/cn';

const AVATARS = [
  { icon: Sparkles, className: 'bg-brand-500/15 text-brand-300 ring-brand-400/40' },
  { icon: Bot, className: 'bg-violet-500/15 text-violet-300 ring-violet-400/40' },
  { icon: Rocket, className: 'bg-amber-500/15 text-amber-300 ring-amber-400/40' },
  { icon: Leaf, className: 'bg-emerald-500/15 text-emerald-300 ring-emerald-400/40' },
  { icon: Headphones, className: 'bg-rose-500/15 text-rose-300 ring-rose-400/40' },
];
const MODELS = ['Nova Pro', 'Nova Mini', 'Atlas Reasoner'];
const TOOLS = [
  { id: 'web', label: 'Web search', hint: 'Fresh answers from the web', icon: Globe },
  { id: 'calendar', label: 'Calendar', hint: 'Find and book times', icon: CalendarDays },
  { id: 'code', label: 'Code interpreter', hint: 'Run quick calculations', icon: Calculator },
  { id: 'knowledge', label: 'Knowledge', hint: 'Answer from your files', icon: Library },
] as const;
type ToolId = (typeof TOOLS)[number]['id'];
const SPARE_FILES = ['benefits-2026.pdf', 'office-map.png', 'security-policy.md'];

export type AgentConfig = {
  name: string;
  avatar: number;
  instructions: string;
  model: string;
  tools: Record<ToolId, boolean>;
  files: string[];
  creativity: number;
};
type Msg = { id: number; role: 'user' | 'agent'; text: string; used?: string[] };

const tone = (c: number) => (c < 34 ? 'Precise' : c < 67 ? 'Balanced' : 'Playful');

function list(items: string[]) {
  if (items.length <= 1) return items[0] ?? 'answer questions';
  return `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`;
}

/** The first message the agent sends, derived from its settings. */
export function greeting(c: AgentConfig) {
  const can = list(
    [c.tools.knowledge && c.files.length ? `answer from ${c.files.length} file${c.files.length > 1 ? 's' : ''}` : '', c.tools.calendar ? 'book time on calendars' : '', c.tools.web ? 'search the web' : '', c.tools.code ? 'run quick calculations' : ''].filter(Boolean),
  );
  const name = c.name.trim() || 'Your agent';
  if (c.creativity < 34) return `${name}. I can ${can}. What do you need?`;
  if (c.creativity < 67) return `Hi, I'm ${name}. I can ${can}. How can I help today?`;
  return `Hey there, ${name} here and ready to go. I can ${can}, so throw anything at me.`;
}

function Toggle({ on, onClick, label }: { on: boolean; onClick: () => void; label: string }) {
  return (
    <button role="switch" aria-checked={on} aria-label={label} onClick={onClick} className={cn('focus-ring relative h-5 w-9 shrink-0 rounded-full transition-colors duration-300', on ? 'bg-brand-500' : 'bg-white/10')}>
      <span className={cn('absolute top-0.5 h-4 w-4 rounded-full bg-white shadow transition-all duration-300 ease-spring', on ? 'left-[18px]' : 'left-0.5')} />
    </button>
  );
}

function Field({ label, aside, children }: { label: string; aside?: ReactNode; children: ReactNode }) {
  return (
    <div>
      <div className="mb-1.5 flex items-center justify-between gap-2">
        <span className="text-[11px] font-medium uppercase tracking-wider text-ink-500">{label}</span>
        {aside}
      </div>
      {children}
    </div>
  );
}

export type AgentBuilderProps = { initial: AgentConfig; className?: string };

/** A no-code agent builder: settings on the left, a live test chat on the right that reflects every change. */
export function AgentBuilder({ initial, className }: AgentBuilderProps) {
  const [c, setC] = useState(initial);
  const [publish, setPublish] = useState<'idle' | 'busy' | 'done'>('done');
  const [msgs, setMsgs] = useState<Msg[]>([
    { id: 1, role: 'user', text: 'When is my laptop pickup?' },
    { id: 2, role: 'agent', text: 'Tuesday at 10:00 at the IT desk on the 3rd floor. I added it to your calendar.', used: ['it-setup.md', 'Calendar'] },
  ]);
  const [draft, setDraft] = useState('');
  const [typing, setTyping] = useState(false);
  const timers = useRef<number[]>([]);
  const list$ = useRef<HTMLDivElement>(null);
  useEffect(() => () => timers.current.forEach(clearTimeout), []);
  useEffect(() => {
    const el = list$.current;
    if (el) el.scrollTo({ top: el.scrollHeight, behavior: 'smooth' });
  }, [msgs, typing]);

  const set = (patch: Partial<AgentConfig>) => {
    setC((x) => ({ ...x, ...patch }));
    setPublish('idle');
  };
  const Avatar = AVATARS[c.avatar];
  const tokens = Math.ceil(c.instructions.length / 4);

  const send = (e: FormEvent) => {
    e.preventDefault();
    const text = draft.trim();
    if (!text || typing) return;
    setDraft('');
    setMsgs((m) => [...m, { id: Date.now(), role: 'user', text }]);
    setTyping(true);
    const used = [c.tools.knowledge && c.files[0], c.tools.web && /news|latest|today|weather/i.test(text) ? 'Web search' : ''].filter(Boolean) as string[];
    const reply =
      c.creativity < 34
        ? `Short answer: check ${c.files[0] ?? 'the handbook'}, section 2. I can book a follow-up if you need it.`
        : c.creativity < 67
          ? `Good question. According to ${c.files[0] ?? 'our docs'}, you can sort that out in your first week. Want me to set a reminder?`
          : `Love this one! ${c.files[0] ?? 'The docs'} has the details, and I can turn it into a tiny checklist for you.`;
    timers.current.push(
      window.setTimeout(() => {
        setTyping(false);
        setMsgs((m) => [...m, { id: Date.now(), role: 'agent', text: reply, used }]);
      }, 900),
    );
  };

  const doPublish = () => {
    setPublish('busy');
    timers.current.push(window.setTimeout(() => setPublish('done'), 1200));
  };

  return (
    <div className={cn('grid w-full grid-cols-[minmax(0,1fr)] overflow-hidden rounded-2xl bg-ink-900 shadow-card md:grid-cols-[minmax(0,1.05fr)_minmax(0,1fr)]', className)}>
      <section className="space-y-4 border-white/5 p-4 md:max-h-[560px] md:overflow-y-auto md:border-r [scrollbar-width:thin]">
        <Field label="Identity">
          <div className="flex items-center gap-2">
            <span className={cn('grid h-10 w-10 shrink-0 place-items-center rounded-xl ring-1 transition-all', Avatar.className)}>
              <Avatar.icon className="h-5 w-5" />
            </span>
            <input value={c.name} onChange={(e) => set({ name: e.target.value })} aria-label="Agent name" className="h-10 min-w-0 flex-1 rounded-xl bg-ink-950/60 px-3 text-sm text-ink-50 outline-none ring-1 ring-white/10 focus:ring-brand-400/50" />
          </div>
          <div className="mt-2 flex gap-1.5" role="radiogroup" aria-label="Avatar">
            {AVATARS.map((a, i) => (
              <button key={i} role="radio" aria-checked={c.avatar === i} aria-label={`Avatar ${i + 1}`} onClick={() => set({ avatar: i })} className={cn('focus-ring grid h-7 w-7 place-items-center rounded-lg ring-1 transition-all', a.className, c.avatar === i ? 'scale-110' : 'opacity-50 ring-transparent hover:opacity-90')}>
                <a.icon className="h-3.5 w-3.5" />
              </button>
            ))}
          </div>
        </Field>

