import { useEffect, useState } from 'react';
import { BookOpen, Brain, Check, Pencil, RefreshCw, Search } from 'lucide-react';
import { cn } from '@/lib/cn';

export type ActivityKind = 'thinking' | 'searching' | 'reading' | 'writing';
export type ActivityStep = { kind: ActivityKind; title: string; detail?: string; duration: number };

const KIND = {
  thinking: { icon: Brain, color: 'text-amber-300 bg-amber-500/10' },
  searching: { icon: Search, color: 'text-sky-300 bg-sky-500/10' },
  reading: { icon: BookOpen, color: 'text-teal-300 bg-teal-500/10' },
  writing: { icon: Pencil, color: 'text-brand-300 bg-brand-500/10' },
} as const;

export type AgentActivityProps = { steps: ActivityStep[]; onComplete?: () => void; showRestart?: boolean; className?: string };

/** Live timeline: each step becomes active after the previous finishes. */
export function AgentActivity({ steps, onComplete, showRestart = true, className }: AgentActivityProps) {
  const [run, setRun] = useState(0);
  const [now, setNow] = useState(0);
  const total = steps.reduce((a, s) => a + s.duration, 0);

  useEffect(() => {
    setNow(0);
    const start = performance.now();
    let raf = 0;
    const tick = () => {
      const t = performance.now() - start;
      setNow(t);
      if (t < total + 100) raf = requestAnimationFrame(tick);
      else onComplete?.();
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [run, total]);

  let acc = 0;
  const timeline = steps.map((s) => {
    const startAt = acc;
    acc += s.duration;
    return { ...s, startAt, state: now >= acc ? 'done' : now >= startAt ? 'active' : 'hidden', elapsed: Math.min(s.duration, Math.max(0, now - startAt)) };
  });
  const visible = timeline.filter((s) => s.state !== 'hidden');
  const finished = now >= acc;

  return (
    <div className={cn('w-full rounded-2xl bg-ink-900 p-4 shadow-card', className)}>
      <div className="mb-3 flex items-center justify-between">
        <div className="flex items-center gap-2 text-sm">
          <span className="relative flex h-2 w-2">
            {!finished && <span className="absolute inset-0 animate-pulse-ring rounded-full bg-brand-400" />}
            <span className={cn('relative h-2 w-2 rounded-full transition-colors', finished ? 'bg-emerald-400' : 'bg-brand-400')} />
          </span>
          <span className="font-medium text-ink-100">{finished ? 'Completed' : 'Working'}</span>
          <span className="font-mono text-xs tabular-nums text-ink-500">{(Math.min(now, acc) / 1000).toFixed(1)}s</span>
        </div>
        {showRestart && <button
          onClick={() => setRun((r) => r + 1)}
          className="focus-ring group flex h-7 items-center gap-1.5 rounded-md px-2 text-xs text-ink-400 transition-colors hover:bg-white/5 hover:text-ink-100"
        >
          <RefreshCw className="h-3.5 w-3.5 transition-transform duration-500 group-hover:-rotate-180" /> Restart
        </button>}
      </div>
      <ol className="relative">
        {visible.map((s, i) => {
          const { icon: Icon, color } = KIND[s.kind];
          const active = s.state === 'active';
          const last = i === visible.length - 1;
          return (
            <li key={`${run}-${i}`} className="relative flex animate-fade-up gap-3 pb-4 last:pb-0">
              {!last && <span className="absolute left-[13px] top-8 h-[calc(100%-28px)] w-px origin-top animate-scale-in bg-white/10" />}
              <span className={cn('relative flex h-7 w-7 shrink-0 items-center justify-center rounded-lg transition-colors duration-500', active ? color : 'bg-white/5 text-ink-400')}>
                {active ? <Icon className="h-3.5 w-3.5" /> : <Check className="h-3.5 w-3.5 animate-scale-in text-emerald-400" />}
                {active && <span className="absolute inset-0 animate-pulse-ring rounded-lg border border-current opacity-40" />}
              </span>
              <div className="min-w-0 flex-1 pt-1">
                <div className="flex items-baseline justify-between gap-3">
                  <p className={cn('truncate text-sm', active ? 'shimmer-text font-medium' : 'text-ink-200')}>{s.title}</p>
                  <span className="shrink-0 font-mono text-[11px] tabular-nums text-ink-500">{(s.elapsed / 1000).toFixed(1)}s</span>
                </div>
                {s.detail && <p className="mt-0.5 truncate text-xs text-ink-500">{s.detail}</p>}
              </div>
            </li>
          );
        })}
      </ol>
    </div>
  );
}

const STEPS: ActivityStep[] = [
  { kind: 'thinking', title: 'Planning the comparison', detail: 'Breaking the request into pricing, limits and support', duration: 1600 },
  { kind: 'searching', title: 'Searching 3 providers', detail: 'neon.tech · planetscale.com · supabase.com', duration: 2200 },
  { kind: 'reading', title: 'Reading pricing pages', detail: '8 pages · 14,203 tokens', duration: 2400 },
  { kind: 'thinking', title: 'Normalizing plan tiers', detail: 'Mapping compute hours to monthly cost', duration: 1400 },
  { kind: 'writing', title: 'Drafting the summary table', detail: 'comparison.md', duration: 2000 },
];

export function AgentActivityDemo() {
  return (
    <div className="mx-auto w-full max-w-md">
      <AgentActivity steps={STEPS} />
    </div>
  );
}

ai/agent-loading.content:
import type { ReactNode } from 'react';
import { Sparkles } from 'lucide-react';
import { cn } from '@/lib/cn';

const KEYFRAMES =
  '@keyframes ai-dot{0%,80%,100%{transform:scale(.6);opacity:.35}40%{transform:scale(1);opacity:1}}' +
  '@keyframes ai-type{0%,60%,100%{transform:translateY(0);opacity:.4}30%{transform:translateY(-4px);opacity:1}}';

export function ThinkingShimmer({ label = 'Thinking…', className }: { label?: string; className?: string }) {
  return (
    <span className={cn('flex items-center gap-2 text-sm', className)} role="status">
      <Sparkles className="h-4 w-4 animate-pulse text-brand-300" />
      <span className="shimmer-text font-medium">{label}</span>
    </span>
  );
}

export function DotPulse({ className }: { className?: string }) {
  return (
    <span className={cn('flex items-center gap-1.5', className)} role="status" aria-label="Loading">
      <style>{KEYFRAMES}</style>
      {[0, 1, 2].map((i) => (
        <span key={i} className="h-2.5 w-2.5 rounded-full bg-brand-400" style={{ animation: `ai-dot 1.2s ease-in-out ${i * 160}ms infinite` }} />
      ))}
    </span>
  );
}

export function EqualizerBars({ bars = 7, className }: { bars?: number; className?: string }) {
  return (
    <span className={cn('flex h-8 items-center gap-[3px]', className)} role="status" aria-label="Loading">
      {Array.from({ length: bars }, (_, i) => (
        <span
          key={i}
          className="h-full w-1 animate-bar-bounce rounded-full bg-gradient-to-t from-brand-600 to-sky-300"
          style={{ animationDelay: `${(i * 137) % 600}ms`, animationDuration: `${800 + ((i * 211) % 500)}ms` }}
        />
      ))}
    </span>
  );
}

export function OrbitSpinner({ className }: { className?: string }) {
  return (
    <span className={cn('relative block h-12 w-12', className)} role="status" aria-label="Loading">
      <span className="absolute inset-0 rounded-full border border-white/10" />
      <span className="absolute inset-0 animate-spin [animation-duration:1.6s]">
        <span className="absolute -top-1 left-1/2 h-2 w-2 -translate-x-1/2 rounded-full bg-brand-400 shadow-[0_0_12px_2px_rgba(56,189,248,0.7)]" />
      </span>
      <span className="absolute inset-3 animate-spin rounded-full border border-white/10 [animation-direction:reverse] [animation-duration:1.1s]">
        <span className="absolute -top-[3px] left-1/2 h-1.5 w-1.5 -translate-x-1/2 rounded-full bg-teal-300" />
      </span>
      <span className="absolute inset-[22px] rounded-full bg-brand-300/80" />
    </span>
  );
}

export function SkeletonLines({ lines = 4, className }: { lines?: number; className?: string }) {
  const widths = ['92%', '100%', '78%', '56%', '85%'];
  return (
    <span className={cn('flex w-full flex-col gap-2', className)} role="status" aria-label="Loading">
      {Array.from({ length: lines }, (_, i) => (
        <span
          key={i}
          className="h-2.5 animate-shimmer rounded-full bg-[linear-gradient(90deg,#1a1a1e_0%,#1a1a1e_35%,#36363e_50%,#1a1a1e_65%,#1a1a1e_100%)] bg-[length:200%_100%]"
          style={{ width: widths[i % widths.length], animationDelay: `${i * 120}ms` }}
        />
      ))}
    </span>
  );
}

export function TypingIndicator({ className }: { className?: string }) {
  return (
    <span className={cn('inline-flex items-center gap-1 rounded-2xl rounded-bl-md bg-ink-800 px-3.5 py-3 shadow-hairline', className)} role="status" aria-label="Assistant is typing">
      <style>{KEYFRAMES}</style>
      {[0, 1, 2].map((i) => (
        <span key={i} className="h-1.5 w-1.5 rounded-full bg-ink-300" style={{ animation: `ai-type 1.3s ease-in-out ${i * 150}ms infinite` }} />
      ))}
    </span>
  );
}

function Tile({ label, children, i }: { label: string; children: ReactNode; i: number }) {
  return (
    <div
      className="group flex h-36 animate-fade-up flex-col rounded-2xl bg-ink-900 p-4 shadow-card transition-transform duration-300 ease-spring hover:-translate-y-0.5"
      style={{ animationDelay: `${i * 70}ms` }}
    >
      <div className="flex flex-1 items-center justify-center px-2">{children}</div>
      <p className="text-center text-xs text-ink-500 transition-colors group-hover:text-ink-300">{label}</p>
    </div>
  );
}

export function AgentLoadingDemo() {
  const items: Array<[string, ReactNode]> = [
    ['Shimmer text', <ThinkingShimmer />],
    ['Dot pulse', <DotPulse />],
    ['Equalizer', <EqualizerBars />],
    ['Orbit', <OrbitSpinner />],
    ['Skeleton lines', <SkeletonLines />],
    ['Typing indicator', <TypingIndicator />],
  ];
  return (
    <div className="mx-auto grid w-full max-w-2xl grid-cols-2 gap-3 sm:grid-cols-3">
      {items.map(([label, node], i) => (
        <Tile key={label} label={label} i={i}>
          {node}
        </Tile>
      ))}
    </div>
  );
}

ai/image-generation.content:
import { useEffect, useRef, useState } from 'react';
import { Download, RefreshCw, Wand2 } from 'lucide-react';
import { cn } from '@/lib/cn';

type Palette = string[];

const PRESETS: Array<{ prompt: string; palettes: Palette[] }> = [
  {
    prompt: 'Aurora over a frozen fjord, long exposure',
    palettes: [
      ['#0b1d3a', '#2dd4bf', '#38bdf8', '#a7f3d0'],
      ['#06122b', '#5eead4', '#1461e1', '#e0f2fe'],
      ['#0a1a2f', '#34d399', '#0ea5e9', '#fef3c7'],
      ['#071426', '#99f6e4', '#7dd3fc', '#14b8a6'],
    ],
  },
  {
    prompt: 'Desert dunes at golden hour, soft haze',
    palettes: [
      ['#3b1d0b', '#f59e0b', '#fb7185', '#fde68a'],
      ['#2a1408', '#fbbf24', '#f97316', '#fecdd3'],
      ['#33150c', '#fcd34d', '#e11d48', '#fff7ed'],
      ['#2b1a0e', '#fdba74', '#f59e0b', '#fde047'],
    ],
  },
  {
    prompt: 'Neon city reflected in rain puddles',
    palettes: [
      ['#0a0a0c', '#f43f5e', '#0ea5e9', '#22d3ee'],
      ['#0c0a10', '#fb7185', '#38bdf8', '#fbbf24'],
      ['#08080c', '#e11d48', '#14b8a6', '#bae6fd'],
      ['#0a0b10', '#f472b6', '#0ea5e9', '#5eead4'],
    ],
  },
];

function mesh(p: Palette, seed: number) {
  const a = (n: number) => 15 + ((seed * 37 + n * 53) % 70);
  return {
    backgroundColor: p[0],
    backgroundImage: [
      `radial-gradient(at ${a(1)}% ${a(2)}%, ${p[1]} 0px, transparent 55%)`,
      `radial-gradient(at ${a(3)}% ${a(4)}%, ${p[2]} 0px, transparent 50%)`,
      `radial-gradient(at ${a(5)}% ${100 - a(6) / 2}%, ${p[3]} 0px, transparent 45%)`,
      `radial-gradient(at ${a(7)}% 100%, ${p[1]} 0px, transparent 50%)`,
      `linear-gradient(180deg, transparent 55%, ${p[0]} 100%)`,
    ].join(','),
  };
}

export type GeneratedImageProps = { palette: Palette; seed: number; progress: number; selected?: boolean; onSelect?: () => void };

export function GeneratedImage({ palette, seed, progress, selected, onSelect }: GeneratedImageProps) {
  const p = Math.min(1, Math.max(0, progress));
  const done = p >= 1;
  return (
    <button
      onClick={onSelect}
      disabled={!done}
      className={cn(
        'focus-ring group relative aspect-square overflow-hidden rounded-xl bg-ink-850 shadow-hairline transition-all duration-300 ease-spring',
        done && 'hover:scale-[1.02]',
        selected && 'ring-2 ring-brand-400 ring-offset-2 ring-offset-ink-900',
      )}
    >
      <div
        className="absolute inset-0 transition-[filter] duration-150"
        style={{ ...mesh(palette, seed), filter: `blur(${(1 - p) * 28}px) saturate(${0.4 + p * 0.6})`, transform: `scale(${1.15 - p * 0.15})` }}
      />
      <div className="absolute inset-0 mix-blend-overlay opacity-30 dot-bg" />
      {!done && (
        <>
          <div className="absolute inset-0 animate-shimmer bg-[linear-gradient(110deg,transparent_30%,rgba(255,255,255,0.12)_50%,transparent_70%)] bg-[length:200%_100%]" />
          <span className="absolute bottom-2 left-2 rounded-md bg-ink-950/70 px-1.5 py-0.5 font-mono text-[11px] tabular-nums text-ink-100 backdrop-blur">
            {Math.round(p * 100)}%
          </span>
        </>
      )}
      {done && (
        <span className="absolute right-2 top-2 flex h-7 w-7 items-center justify-center rounded-lg bg-ink-950/60 text-ink-100 opacity-0 backdrop-blur transition-opacity group-hover:opacity-100">
          <Download className="h-3.5 w-3.5" />
        </span>
      )}
    </button>
  );
}

const DURATION = 4200;

export function ImageGenerationDemo() {
  const [prompt, setPrompt] = useState(PRESETS[0].prompt);
  const [job, setJob] = useState({ preset: 0, run: 0 });
  const [t, setT] = useState(0);
  const [selected, setSelected] = useState<number | null>(null);
  const raf = useRef(0);

  useEffect(() => {
    const start = performance.now();
    setSelected(null);
    const tick = (now: number) => {
      const e = now - start;
      setT(e);
      if (e < DURATION + 800) raf.current = requestAnimationFrame(tick);
    };
    raf.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf.current);
  }, [job]);

  const generate = (text = prompt) => {
    const found = PRESETS.findIndex((p) => p.prompt === text);
    const hash = [...text].reduce((a, c) => a + c.charCodeAt(0), 0);
    setJob((j) => ({ preset: found >= 0 ? found : hash % PRESETS.length, run: j.run + 1 }));
  };
  const busy = t < DURATION + 600;
  const ease = (x: number) => 1 - Math.pow(1 - Math.min(1, Math.max(0, x)), 3);

  return (
    <div className="mx-auto w-full max-w-md">
      <div className="rounded-2xl bg-ink-900 p-3 shadow-card">
        <form
          onSubmit={(e) => {
            e.preventDefault();
            generate();
          }}
          className="flex items-center gap-2 rounded-xl bg-ink-950 p-1.5 pl-3 shadow-hairline focus-within:shadow-glow"
        >
          <Wand2 className="h-4 w-4 shrink-0 text-brand-300" />
          <input
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            className="min-w-0 flex-1 bg-transparent text-sm text-ink-50 outline-none placeholder:text-ink-500"
            placeholder="Describe an image…"
          />
          <button
            type="submit"
            disabled={busy}
            className="focus-ring flex h-8 items-center gap-1.5 rounded-lg bg-brand-500 px-3 text-xs font-medium text-white transition-all hover:bg-brand-400 active:scale-95 disabled:bg-ink-800 disabled:text-ink-400"
          >
            <RefreshCw className={cn('h-3.5 w-3.5', busy && 'animate-spin')} />
            {busy ? 'Generating' : 'Generate'}
          </button>
        </form>
        <div className="mt-3 grid grid-cols-2 gap-2">
          {PRESETS[job.preset].palettes.map((pal, i) => (
            <GeneratedImage
              key={`${job.run}-${i}`}
              palette={pal}
              seed={job.run * 4 + i + 1}
              progress={ease((t - i * 250) / (DURATION - 750))}
              selected={selected === i}
              onSelect={() => setSelected(i)}
            />
          ))}
        </div>
        <div className="mt-3 flex flex-wrap gap-1.5">
          {PRESETS.map((p) => (
            <button
              key={p.prompt}
              disabled={busy}
              onClick={() => {
                setPrompt(p.prompt);
                generate(p.prompt);
              }}
              className="focus-ring rounded-full bg-white/5 px-2.5 py-1 text-[11px] text-ink-400 transition-colors hover:bg-white/10 hover:text-ink-100 disabled:opacity-50"
            >
              {p.prompt.split(',')[0]}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

ai/chat-app.content:
import { useEffect, useRef, useState } from 'react';
import { MessageSquare, PanelLeft, Search, Sparkles, SquarePen } from 'lucide-react';
import { cn } from '@/lib/cn';
import { MessageBubble } from './MessageBubble';
import { PromptInput } from './PromptInput';
import { TypingIndicator } from './AgentLoading';
import { Markdown, useStream } from './stream';

export type Msg = { id: string; role: 'user' | 'assistant'; text: string; time: string; live?: boolean };
export type Convo = { id: string; title: string; group: 'Today' | 'Previous 7 days'; messages: Msg[] };

const now = () => new Date().toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });

const SEED: Convo[] = [
  {
    id: 'c1',
    title: 'Trip plan for Lisbon',
    group: 'Today',
    messages: [
      { id: 'm1', role: 'user', text: 'Plan 3 days in Lisbon for a first-timer who loves food.', time: '9:12 AM' },
      { id: 'm2', role: 'assistant', text: '## Day 1 — Alfama & Baixa\n- Breakfast **pastéis de nata** at Manteigaria\n- Ride tram 28 up to Miradouro de Santa Luzia\n- Dinner with fado at Tasca do Chico\n## Day 2 — Belém\n- Jerónimos Monastery, then the original **Pastéis de Belém**', time: '9:12 AM' },
    ],
  },
  { id: 'c2', title: 'Refactor auth middleware', group: 'Today', messages: [{ id: 'm3', role: 'user', text: 'Why does my Next.js middleware run twice?', time: '8:03 AM' }, { id: 'm4', role: 'assistant', text: 'It usually runs once per request **and** once per prefetch. Add a `matcher` to exclude `/_next/static` and image routes.', time: '8:03 AM' }] },
  { id: 'c3', title: 'Quarterly OKR draft', group: 'Previous 7 days', messages: [{ id: 'm5', role: 'user', text: 'Draft 3 OKRs for a growth team.', time: 'Mon' }, { id: 'm6', role: 'assistant', text: '1. Grow weekly active teams from 1,200 to 1,800\n2. Lift trial-to-paid conversion from 9% to 13%\n3. Cut onboarding time to first value below 5 minutes', time: 'Mon' }] },
  { id: 'c4', title: 'SQL window functions', group: 'Previous 7 days', messages: [{ id: 'm7', role: 'user', text: 'Explain ROW_NUMBER vs RANK.', time: 'Sun' }, { id: 'm8', role: 'assistant', text: '`ROW_NUMBER` always gives unique numbers. `RANK` gives ties the same number and **skips** the next ones.', time: 'Sun' }] },
];

const REPLIES = [
  'Great question. Here is a quick breakdown:\n- **Start small** — ship the smallest version that proves the idea\n- **Measure** one metric that actually reflects value\n- **Iterate weekly** and cut anything nobody uses\nWant me to turn this into a checklist?',
  '## Short answer\nYes, and it is simpler than it looks.\n- Cache the response for 60 seconds with `stale-while-revalidate`\n- Invalidate on write using a tag per resource\nThis typically cuts p95 latency by **40–60%**.',
];

function LiveMessage({ text, active, onFinish, onTick }: { text: string; active: boolean; onFinish: (t: string) => void; onTick: () => void }) {
  const [thinking, setThinking] = useState(true);
  const { output, done } = useStream(text, { speed: 26, enabled: active && !thinking });
  useEffect(() => {
    const t = window.setTimeout(() => setThinking(false), 900);
    return () => window.clearTimeout(t);
  }, []);
  useEffect(onTick, [output, onTick]);
  useEffect(() => {
    if (done || !active) onFinish(done ? text : output || 'Stopped.');
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [done, active]);
  if (thinking) return <TypingIndicator className="!rounded-tl-md !bg-transparent !p-0 !shadow-none" />;
  return <Markdown text={output} caret={!done} className="text-ink-200" />;
}

export type ChatAppProps = { conversations?: Convo[]; replies?: string[]; defaultSidebarOpen?: boolean; className?: string };

export function ChatApp({ conversations = SEED, replies = REPLIES, defaultSidebarOpen = true, className }: ChatAppProps) {
  const [convos, setConvos] = useState(conversations);
  const [activeId, setActiveId] = useState(conversations[0]?.id ?? '');
  const [generating, setGenerating] = useState<string | null>(null);
  const [sidebar, setSidebar] = useState(defaultSidebarOpen);
  const scroller = useRef<HTMLDivElement>(null);
  const replyIdx = useRef(0);
  const convo = convos.find((c) => c.id === activeId) ?? convos[0];

  const scrollDown = useRef(() => {
    const el = scroller.current;
    if (el) el.scrollTo({ top: el.scrollHeight, behavior: 'smooth' });
  }).current;
  useEffect(scrollDown, [activeId, convo.messages.length, scrollDown]);

  const update = (id: string, fn: (m: Msg[]) => Msg[]) => setConvos((cs) => cs.map((c) => (c.id === id ? { ...c, messages: fn(c.messages) } : c)));
  const finalizeAll = () => setConvos((cs) => cs.map((c) => ({ ...c, messages: c.messages.map((m) => ({ ...m, live: false })) })));

  const send = (text: string) => {
    const reply = replies[replyIdx.current++ % replies.length];
    const aid = `a${Date.now()}`;
    update(convo.id, (m) => [...m, { id: `u${Date.now()}`, role: 'user', text: text || 'Sent an attachment', time: now() }, { id: aid, role: 'assistant', text: reply, time: now(), live: true }]);
    setGenerating(aid);
  };
  const newChat = () => {
    finalizeAll();
    setGenerating(null);
    const id = `c${Date.now()}`;
    setConvos((cs) => [{ id, title: 'New chat', group: 'Today', messages: [] }, ...cs]);
    setActiveId(id);
  };

  return (
    <div className={cn('flex h-[560px] w-full overflow-hidden rounded-2xl bg-ink-950 shadow-card', className)}>
      <aside className={cn('hidden shrink-0 flex-col overflow-hidden border-r border-white/5 bg-ink-900/60 transition-[width] duration-500 ease-smooth md:flex', sidebar ? 'w-60' : 'w-0')}>
        <div className="flex w-60 items-center justify-between px-3 py-3">
          <span className="flex items-center gap-2 text-sm font-medium text-ink-50">
            <span className="flex h-6 w-6 items-center justify-center rounded-md bg-gradient-to-br from-brand-400 to-brand-700"><Sparkles className="h-3.5 w-3.5 text-white" /></span>
            NiceUI
          </span>
          <button onClick={newChat} className="focus-ring flex h-7 w-7 items-center justify-center rounded-md text-ink-400 transition-colors hover:bg-white/5 hover:text-ink-50" aria-label="New chat">
            <SquarePen className="h-4 w-4" />
          </button>
        </div>
        <div className="mx-3 mb-2 flex w-[216px] shrink-0 items-center gap-2 rounded-lg bg-white/[0.04] px-2.5 py-1.5 text-xs text-ink-500">
          <Search className="h-3.5 w-3.5" /> Search chats
        </div>
        <nav className="w-60 flex-1 overflow-y-auto px-2 pb-3">
          {(['Today', 'Previous 7 days'] as const).map((g) => (
            <div key={g} className="mt-3">
              <p className="px-2 pb-1 text-[11px] font-medium text-ink-500">{g}</p>
              {convos.filter((c) => c.group === g).map((c) => (
                <button
                  key={c.id}
                  onClick={() => {
                    finalizeAll();
                    setGenerating(null);
                    setActiveId(c.id);
                  }}
                  className={cn('focus-ring flex w-full animate-fade-in items-center gap-2 rounded-lg px-2 py-1.5 text-left text-sm transition-colors', c.id === convo.id ? 'bg-white/[0.07] text-ink-50' : 'text-ink-400 hover:bg-white/[0.04] hover:text-ink-200')}
                >
                  <MessageSquare className="h-3.5 w-3.5 shrink-0 opacity-60" />
                  <span className="truncate">{c.title}</span>
                </button>
              ))}
            </div>
          ))}
        </nav>
        <div className="flex w-60 items-center gap-2 border-t border-white/5 px-3 py-3">
          <span className="flex h-7 w-7 items-center justify-center rounded-full bg-amber-500/20 text-xs font-medium text-amber-200">MR</span>
          <span className="text-xs"><span className="block text-ink-100">Maya Reyes</span><span className="block text-ink-500">Pro plan</span></span>
        </div>
      </aside>
      <section className="flex min-w-0 flex-1 flex-col">
        <header className="flex items-center gap-2 border-b border-white/5 px-3 py-2.5">
          <button onClick={() => setSidebar((s) => !s)} className="focus-ring hidden h-7 w-7 items-center justify-center rounded-md text-ink-400 transition-colors hover:bg-white/5 hover:text-ink-50 md:flex" aria-label="Toggle sidebar">
            <PanelLeft className="h-4 w-4" />
          </button>
          <h3 key={convo.id} className="animate-fade-in truncate text-sm font-medium text-ink-100">{convo.title}</h3>
        </header>
        <div ref={scroller} className="flex-1 overflow-y-auto px-4 py-5">
          <div key={convo.id} className="mx-auto flex max-w-2xl flex-col gap-2">
            {convo.messages.length === 0 && (
              <div className="flex animate-fade-up flex-col items-center pt-24 text-center">
                <Sparkles className="h-6 w-6 text-brand-300" />
                <p className="mt-3 text-lg font-medium text-ink-50">How can I help today?</p>
                <p className="mt-1 text-sm text-ink-500">Ask a question, paste code or attach a file.</p>
              </div>
            )}
            {convo.messages.map((m) => (
              <div key={m.id} className="animate-fade-up">
                <MessageBubble role={m.role} time={m.time} status={m.role === 'user' ? 'read' : undefined} copyText={m.text} actions={!m.live}>
                  {m.live ? (
                    <LiveMessage
                      text={m.text}
                      active={generating === m.id}
                      onTick={scrollDown}
                      onFinish={(t) => {
                        update(convo.id, (ms) => ms.map((x) => (x.id === m.id ? { ...x, text: t, live: false } : x)));
                        setGenerating((g) => (g === m.id ? null : g));
                      }}
                    />
                  ) : m.role === 'assistant' ? (
                    <Markdown text={m.text} className="text-ink-200" />
                  ) : (
                    m.text
                  )}
                </MessageBubble>
              </div>
            ))}
          </div>
        </div>
        <div className="mx-auto w-full max-w-2xl px-4 pb-4">
          <PromptInput onSubmit={send} generating={!!generating} onStop={() => setGenerating(null)} placeholder="Message NiceUI…" maxRows={5} />
        </div>
