  const close = useCallback(() => setOpen(false), []);
  const { mounted, visible } = usePresence(open, 160);
  useClickOutside([ref], open, close);
  useEscape(open, close);

  return (
    <div ref={ref} className="relative">
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
