                    <span className="ml-auto shrink-0 font-mono text-[10px] text-ink-500">{t.time}</span>
                  </span>
                  <span className={cn('block truncate text-[12px]', t.unread ? 'text-ink-200' : 'text-ink-400')}>{t.subject}</span>
