import { useEffect, useRef, useState } from 'react';
import { ChevronLeft, ChevronRight, Pause, Play } from 'lucide-react';
import { cn } from '@/lib/cn';
import { ARTWORKS, artwork, type Artwork } from './art';

export type FilmstripViewerProps = {
  items?: Artwork[];
  /** Seconds per slide while autoplaying. */
  interval?: number;
  autoplay?: boolean;
  className?: string;
};

/** A cinematic stage with crossfade and Ken Burns motion, a synced filmstrip and an autoplay ring. */
export function FilmstripViewer({ items = ARTWORKS, interval = 5, autoplay = true, className }: FilmstripViewerProps) {
  const [i, setI] = useState(0);
  const [playing, setPlaying] = useState(autoplay);
  const [hover, setHover] = useState(false);
  const [reduce, setReduce] = useState(false);
  const strip = useRef<HTMLDivElement>(null);
  const live = playing && !hover && !reduce;

  useEffect(() => setReduce(window.matchMedia('(prefers-reduced-motion: reduce)').matches), []);
  useEffect(() => {
    if (!live) return;
    const id = window.setTimeout(() => setI((v) => (v + 1) % items.length), interval * 1000);
    return () => clearTimeout(id);
  }, [i, live, interval, items.length]);
  useEffect(() => {
    const s = strip.current;
    const el = s?.children[i] as HTMLElement | undefined;
    if (s && el) s.scrollTo({ left: el.offsetLeft - s.clientWidth / 2 + el.clientWidth / 2, behavior: 'smooth' });
  }, [i]);

  const go = (d: number) => setI((v) => (v + d + items.length) % items.length);
  const a = items[i];

  return (
    <div
      className={cn('w-full overflow-hidden rounded-2xl bg-ink-900 shadow-card', className)}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      onKeyDown={(e) => {
        if (e.key === 'ArrowRight') (e.preventDefault(), go(1));
        if (e.key === 'ArrowLeft') (e.preventDefault(), go(-1));
      }}
      role="region"
      aria-roledescription="carousel"
      aria-label="Photo filmstrip"
    >
      <div className="relative aspect-[16/10] overflow-hidden bg-black">
        {items.map((it, k) => (
          <img
            key={it.id}
            src={artwork(it.id, 960, 600)}
            alt={k === i ? `${it.title} by ${it.artist}` : ''}
            aria-hidden={k !== i}
            className={cn('absolute inset-0 h-full w-full object-cover transition-opacity duration-1000 ease-smooth', k === i ? 'opacity-100' : 'opacity-0')}
            style={k === i && !reduce ? { animation: `${k % 2 ? 'fs-kb-b' : 'fs-kb'} ${interval + 1.5}s ease-out both` } : undefined}
          />
        ))}
        <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-black/20" />
        <div key={a.id} className="absolute bottom-4 left-4 right-24 animate-fade-up">
          <p className="font-mono text-[10px] uppercase tracking-[0.18em] text-white/60">
            {a.place} · {a.year}
          </p>
          <p className="mt-1 truncate text-lg font-medium tracking-tight text-white sm:text-2xl">{a.title}</p>
          <p className="truncate text-xs text-white/60 sm:text-sm">{a.artist}</p>
        </div>
        <div className="absolute bottom-4 right-4 flex items-center gap-1.5">
          <button onClick={() => go(-1)} aria-label="Previous" className="focus-ring grid h-9 w-9 place-items-center rounded-full border border-white/15 bg-black/40 text-white backdrop-blur transition-colors hover:bg-white/15">
            <ChevronLeft className="h-4 w-4" />
          </button>
          <button onClick={() => go(1)} aria-label="Next" className="focus-ring grid h-9 w-9 place-items-center rounded-full border border-white/15 bg-black/40 text-white backdrop-blur transition-colors hover:bg-white/15">
            <ChevronRight className="h-4 w-4" />
          </button>
        </div>
        <button
          onClick={() => setPlaying((p) => !p)}
          aria-label={playing ? 'Pause slideshow' : 'Play slideshow'}
          className="focus-ring absolute right-4 top-4 grid h-10 w-10 place-items-center rounded-full bg-black/40 text-white backdrop-blur"
        >
          <svg viewBox="0 0 36 36" className="absolute inset-0 -rotate-90" aria-hidden="true">
            <circle cx="18" cy="18" r="16" fill="none" stroke="rgba(255,255,255,.18)" strokeWidth="2" />
            <circle
              key={`${i}-${live}`}
              cx="18"
              cy="18"
              r="16"
              fill="none"
              stroke="#7dd3fc"
              strokeWidth="2"
              strokeLinecap="round"
              strokeDasharray="100.5"
              style={{ strokeDashoffset: 100.5, animation: live ? `fs-ring ${interval}s linear forwards` : undefined }}
            />
          </svg>
          {playing ? <Pause className="relative h-3.5 w-3.5 fill-current" /> : <Play className="relative ml-0.5 h-3.5 w-3.5 fill-current" />}
        </button>
      </div>
      <div ref={strip} className="flex gap-2 overflow-x-auto p-3 [scrollbar-width:none]">
        {items.map((it, k) => (
          <button
            key={it.id}
            onClick={() => setI(k)}
            aria-label={`Show ${it.title}`}
            aria-current={k === i}
            className={cn('focus-ring group relative h-14 w-20 shrink-0 overflow-hidden rounded-lg transition-all duration-300 sm:h-16 sm:w-24', k === i ? 'opacity-100' : 'opacity-45 hover:opacity-80')}
          >
            <img src={artwork(it.id, 320, 320)} alt="" className="h-full w-full object-cover" />
            <span className={cn('absolute inset-x-1.5 bottom-1 h-0.5 rounded-full bg-brand-300 transition-transform duration-500 ease-smooth', k === i ? 'scale-x-100' : 'scale-x-0')} />
          </button>
        ))}
      </div>
      <style>{`@keyframes fs-kb{from{transform:scale(1.12) translate(2%,1%)}to{transform:scale(1) translate(0,0)}}@keyframes fs-kb-b{from{transform:scale(1) translate(0,0)}to{transform:scale(1.12) translate(-2%,-1%)}}@keyframes fs-ring{to{stroke-dashoffset:0}}`}</style>
    </div>
  );
}

export function FilmstripViewerDemo() {
  return (
    <div className="mx-auto w-full max-w-2xl">
      <FilmstripViewer />
    </div>
  );
}

/*
 * Procedural artwork for the gallery demos: soft landscapes and abstract mesh
 * gradients with film grain, rendered once to data URLs. Swap `src` for real
 * photos in your app — every gallery component just takes image URLs.
 */

export type Artwork = { id: number; title: string; artist: string; place: string; year: number; tone: 'warm' | 'cool' | 'dusk' | 'mono' };

const PALETTES: string[][] = [
  ['#0b1d3a', '#1f4e79', '#f2a65a', '#f7d9a8'],
  ['#120c26', '#4b2a77', '#e66b9d', '#ffd1b3'],
  ['#06222b', '#0f5f6b', '#7fd1c7', '#e8f6f1'],
  ['#1b1410', '#5b3a26', '#d98c4a', '#f6e1c3'],
  ['#0e0f13', '#2b2f3a', '#8a93a6', '#e6e8ee'],
  ['#0a1a12', '#1f5134', '#9cc98a', '#f1f7da'],
  ['#1a0f14', '#6b1f3a', '#ef6f5e', '#ffd8a8'],
  ['#071426', '#123f73', '#5aa9e6', '#d6ecff'],
  ['#191325', '#3b2d5c', '#b39ddb', '#f3e9ff'],
  ['#201608', '#6e4a12', '#e0b34a', '#fff1c4'],
  ['#0b1216', '#29424f', '#6fa3b8', '#f0e6d2'],
  ['#170b0b', '#4a1414', '#c84b31', '#f5c26b'],
];

export const ARTWORKS: Artwork[] = [
  { id: 0, title: 'Low Tide, Dawn', artist: 'Mira Okafor', place: 'Comporta', year: 2025, tone: 'warm' },
  { id: 1, title: 'Neon Bloom', artist: 'Ilya Varga', place: 'Kyoto', year: 2024, tone: 'dusk' },
  { id: 2, title: 'Glass Lagoon', artist: 'Sana Iqbal', place: 'Faroe Islands', year: 2025, tone: 'cool' },
  { id: 3, title: 'Copper Dunes', artist: 'Teo Marchetti', place: 'Merzouga', year: 2023, tone: 'warm' },
  { id: 4, title: 'Fog Study No. 4', artist: 'Lena Brandt', place: 'Dolomites', year: 2024, tone: 'mono' },
  { id: 5, title: 'Green Hour', artist: 'Ravi Menon', place: 'Munnar', year: 2025, tone: 'cool' },
  { id: 6, title: 'Ember Coast', artist: 'Noor Haddad', place: 'Big Sur', year: 2024, tone: 'warm' },
  { id: 7, title: 'Blue Hour Harbour', artist: 'Jonas Weber', place: 'Bergen', year: 2025, tone: 'cool' },
  { id: 8, title: 'Lavender Field', artist: 'Camille Roy', place: 'Valensole', year: 2023, tone: 'dusk' },
  { id: 9, title: 'Golden Ridge', artist: 'Aiko Tanaka', place: 'Hokkaido', year: 2025, tone: 'warm' },
  { id: 10, title: 'Salt Flats', artist: 'Diego Alvarez', place: 'Uyuni', year: 2024, tone: 'mono' },
  { id: 11, title: 'Red Canyon', artist: 'Hana Kobayashi', place: 'Arizona', year: 2025, tone: 'warm' },
];

let seedState = 1;
const rand = () => {
  seedState = (seedState * 1664525 + 1013904223) >>> 0;
  return seedState / 4294967296;
};

const cache = new Map<string, string>();

/** A deterministic artwork as a data URL. `kind` picks a landscape or an abstract mesh. */
export function artwork(id: number, w = 960, h = 640, kind: 'landscape' | 'mesh' = id % 3 === 1 ? 'mesh' : 'landscape'): string {
  const key = `${id}-${w}-${h}-${kind}`;
  const hit = cache.get(key);
  if (hit) return hit;
  if (typeof document === 'undefined') return '';
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const g = c.getContext('2d');
  if (!g) return '';
  seedState = (id + 1) * 9973;
  const [deep, mid, hot, light] = PALETTES[id % PALETTES.length];

  const sky = g.createLinearGradient(0, 0, 0, h);
  sky.addColorStop(0, deep);
  sky.addColorStop(0.55, mid);
  sky.addColorStop(1, kind === 'mesh' ? deep : hot);
  g.fillStyle = sky;
  g.fillRect(0, 0, w, h);

  // soft light blobs
  const blobs = kind === 'mesh' ? 6 : 3;
  for (let i = 0; i < blobs; i++) {
    const x = rand() * w;
    const y = rand() * h * (kind === 'mesh' ? 1 : 0.6);
    const r = (0.25 + rand() * 0.45) * Math.max(w, h);
    const rg = g.createRadialGradient(x, y, 0, x, y, r);
    rg.addColorStop(0, [hot, light, mid][i % 3] + 'cc');
    rg.addColorStop(1, 'transparent');
    g.globalCompositeOperation = 'screen';
    g.fillStyle = rg;
    g.fillRect(0, 0, w, h);
  }
  g.globalCompositeOperation = 'source-over';

  if (kind === 'landscape') {
    // sun
    const sx = (0.25 + rand() * 0.5) * w;
    const sy = h * (0.38 + rand() * 0.12);
    const sr = Math.min(w, h) * (0.07 + rand() * 0.05);
    const glow = g.createRadialGradient(sx, sy, 0, sx, sy, sr * 5);
    glow.addColorStop(0, light + 'aa');
    glow.addColorStop(1, 'transparent');
    g.fillStyle = glow;
    g.fillRect(0, 0, w, h);
    g.fillStyle = light;
    g.beginPath();
    g.arc(sx, sy, sr, 0, Math.PI * 2);
    g.fill();
    // ridges, back to front
    for (let layer = 0; layer < 4; layer++) {
      const base = h * (0.5 + layer * 0.12);
      const amp = h * (0.12 - layer * 0.02);
      const f1 = 1.5 + rand() * 2;
      const f2 = 4 + rand() * 4;
      const ph = rand() * 10;
      g.beginPath();
      g.moveTo(0, h);
      for (let x = 0; x <= w; x += 4) {
        const u = x / w;
        const y = base - amp * (0.6 * Math.sin(u * f1 * Math.PI + ph) + 0.3 * Math.sin(u * f2 * Math.PI + ph * 2) + 0.1 * Math.sin(u * 23 + ph));
        g.lineTo(x, y);
      }
      g.lineTo(w, h);
      g.closePath();
      const t = layer / 3;
      const lg = g.createLinearGradient(0, base - amp, 0, h);
      lg.addColorStop(0, mix(mid, deep, 0.25 + t * 0.6));
      lg.addColorStop(1, mix(deep, '#000000', t * 0.5));
      g.fillStyle = lg;
      g.globalAlpha = 0.92;
      g.fill();
      g.globalAlpha = 1;
    }
  } else {
    // flowing ribbons
    for (let i = 0; i < 3; i++) {
      g.beginPath();
      const y0 = h * (0.2 + rand() * 0.6);
      g.moveTo(-50, y0);
      g.bezierCurveTo(w * 0.3, y0 - h * (rand() - 0.5), w * 0.7, y0 + h * (rand() - 0.5), w + 50, y0 + h * (rand() - 0.5) * 0.6);
      g.lineWidth = Math.min(w, h) * (0.08 + rand() * 0.12);
      g.strokeStyle = [light, hot, mid][i] + '55';
      g.filter = `blur(${Math.round(Math.min(w, h) * 0.04)}px)`;
      g.stroke();
      g.filter = 'none';
    }
  }

  // vignette
  const vg = g.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.3, w / 2, h / 2, Math.max(w, h) * 0.75);
  vg.addColorStop(0, 'transparent');
  vg.addColorStop(1, 'rgba(0,0,0,0.45)');
  g.fillStyle = vg;
  g.fillRect(0, 0, w, h);

  // film grain
  const img = g.getImageData(0, 0, w, h);
  const d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const n = (rand() - 0.5) * 18;
    d[i] += n;
    d[i + 1] += n;
    d[i + 2] += n;
  }
  g.putImageData(img, 0, 0);

  const url = c.toDataURL('image/jpeg', 0.86);
  cache.set(key, url);
  return url;
}

function mix(a: string, b: string, t: number) {
  const pa = parseInt(a.slice(1), 16);
  const pb = parseInt(b.slice(1), 16);
  const ch = (s: number) => Math.round(((pa >> s) & 255) * (1 - t) + ((pb >> s) & 255) * t);
  return `rgb(${ch(16)},${ch(8)},${ch(0)})`;
}

