import { useEffect, useState } from 'react';
import { cn } from '@/lib/cn';

export type TypewriterTextProps = { phrases: string[]; typeMs?: number; deleteMs?: number; holdMs?: number; className?: string };

/** Types each phrase, holds, deletes it, then moves to the next. */
export function TypewriterText({ phrases, typeMs = 60, deleteMs = 32, holdMs = 1400, className }: TypewriterTextProps) {
  const [i, setI] = useState(0);
  const [n, setN] = useState(0);
  const [del, setDel] = useState(false);
  const word = phrases[i % phrases.length];

  useEffect(() => {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      setN(word.length);
      return;
    }
    let t: number;
    if (!del && n < word.length) t = window.setTimeout(() => setN(n + 1), typeMs);
    else if (!del) t = window.setTimeout(() => setDel(true), holdMs);
    else if (n > 0) t = window.setTimeout(() => setN(n - 1), deleteMs);
    else t = window.setTimeout(() => (setDel(false), setI((x) => x + 1)), 250);
    return () => clearTimeout(t);
  }, [n, del, word, typeMs, deleteMs, holdMs]);

  return (
    <span className={cn('inline-flex items-baseline', className)} aria-label={word}>
      <span aria-hidden>{word.slice(0, n)}</span>
      <span aria-hidden className="ml-0.5 inline-block h-[0.9em] w-[3px] translate-y-[0.1em] animate-blink rounded-full bg-brand-400" />
    </span>
  );
}

export function TypewriterTextDemo() {
  return (
    <h2 className="text-center text-3xl font-semibold tracking-[-0.03em] text-ink-50 sm:text-5xl">
      Build interfaces that
      <br />
      <TypewriterText className="font-serif font-normal italic text-brand-300" phrases={['feel inevitable.', 'ship on Friday.', 'agents can use.', 'people remember.']} />
    </h2>
  );
}

effects/scramble-text.content:
import { useCallback, useEffect, useRef, useState } from 'react';
import { cn } from '@/lib/cn';

const GLYPHS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789#%&*+=/<>';

export type ScrambleTextProps = { text: string; duration?: number; trigger?: 'view' | 'hover' | 'both'; className?: string };

/** Characters cycle through random glyphs and lock into place left to right. */
export function ScrambleText({ text, duration = 900, trigger = 'both', className }: ScrambleTextProps) {
  const [out, setOut] = useState(text);
  const ref = useRef<HTMLSpanElement>(null);
  const raf = useRef(0);

  const run = useCallback(() => {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return setOut(text);
    cancelAnimationFrame(raf.current);
    const start = performance.now();
    const tick = (now: number) => {
      const p = Math.min(1, (now - start) / duration);
      const lock = Math.floor(p * text.length);
      setOut(
        text
          .split('')
          .map((ch, i) => (ch === ' ' || i < lock ? ch : GLYPHS[Math.floor(Math.random() * GLYPHS.length)]))
          .join(''),
      );
      if (p < 1) raf.current = requestAnimationFrame(tick);
    };
    raf.current = requestAnimationFrame(tick);
  }, [text, duration]);

  useEffect(() => {
    if (trigger === 'hover') return;
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(([e]) => e.isIntersecting && (run(), io.disconnect()), { threshold: 0.4 });
    io.observe(el);
    return () => (io.disconnect(), cancelAnimationFrame(raf.current));
  }, [run, trigger]);

  return (
    <span ref={ref} onMouseEnter={trigger !== 'view' ? run : undefined} aria-label={text} className={cn('font-mono tabular-nums', className)}>
      <span aria-hidden>{out}</span>
    </span>
  );
}

export function ScrambleTextDemo() {
  return (
    <div className="flex flex-col items-center gap-4 text-center">
      <ScrambleText text="DECRYPTING THE SIGNAL" className="text-2xl font-medium tracking-[0.14em] text-ink-50 sm:text-4xl" />
      <ScrambleText text="hover me to scramble again" trigger="hover" className="cursor-default text-sm text-brand-300" />
    </div>
  );
}

