import type { CSSProperties, ReactNode } from 'react';
import { cn } from '@/lib/cn';

export type GradientTextProps = { children: ReactNode; colors?: string[]; speed?: number; shine?: boolean; className?: string };

const css = `
@keyframes nice-grad-flow { to { background-position: 200% 50%; } }
@keyframes nice-grad-shine { 0%, 60% { background-position: -150% 0; } 100% { background-position: 250% 0; } }
@media (prefers-reduced-motion: reduce) { .nice-grad, .nice-grad-shine { animation: none !important; } }
`;

/** Text filled with a slowly flowing gradient, with an optional light sweep on top. */
export function GradientText({ children, colors = ['#7dd3fc', '#38bdf8', '#a78bfa', '#7dd3fc'], speed = 6, shine = true, className }: GradientTextProps) {
  const flow: CSSProperties = {
    backgroundImage: `linear-gradient(90deg, ${colors.join(', ')})`,
    backgroundSize: '200% 100%',
    WebkitBackgroundClip: 'text',
    backgroundClip: 'text',
    color: 'transparent',
    animation: `nice-grad-flow ${speed}s linear infinite`,
  };
  return (
    <span className={cn('relative inline-block', className)}>
      <style>{css}</style>
      <span className="nice-grad" style={flow}>
        {children}
      </span>
      {shine && (
        <span
          aria-hidden
          className="nice-grad-shine pointer-events-none absolute inset-0"
          style={{
            backgroundImage: 'linear-gradient(110deg, transparent 40%, rgba(255,255,255,0.85) 50%, transparent 60%)',
            backgroundSize: '200% 100%',
            WebkitBackgroundClip: 'text',
            backgroundClip: 'text',
            color: 'transparent',
            animation: 'nice-grad-shine 3.2s ease-in-out infinite',
          }}
        >
          {children}
        </span>
      )}
    </span>
  );
}

export function GradientTextDemo() {
  return (
    <div className="text-center">
      <p className="text-xs font-medium uppercase tracking-[0.2em] text-ink-500">Introducing</p>
      <h2 className="mt-3 text-4xl font-semibold tracking-[-0.04em] sm:text-6xl">
        <GradientText>Aurora 2.0</GradientText>
      </h2>
      <p className="mt-3 text-sm text-ink-400">A gradient that flows, with a light sweep every few seconds.</p>
    </div>
  );
}

effects/number-ticker.content:
import { useEffect, useRef, useState } from 'react';
import { cn } from '@/lib/cn';

export type NumberTickerProps = { value: number; prefix?: string; suffix?: string; decimals?: number; locale?: string; className?: string };

/** Each digit is a column 0–9 that rolls to its place when the number scrolls into view. */
export function NumberTicker({ value, prefix = '', suffix = '', decimals = 0, locale = 'en-US', className }: NumberTickerProps) {
  const ref = useRef<HTMLSpanElement>(null);
  const [on, setOn] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(([e]) => e.isIntersecting && (setOn(true), io.disconnect()), { threshold: 0.4 });
    io.observe(el);
    return () => io.disconnect();
  }, []);
  const text = value.toLocaleString(locale, { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
  return (
    <span ref={ref} aria-label={prefix + text + suffix} className={cn('inline-flex font-mono tabular-nums leading-none', className)}>
      <span aria-hidden>{prefix}</span>
      {text.split('').map((ch, i) =>
        /\d/.test(ch) ? (
          <span key={i} aria-hidden className="relative inline-block h-[1em] overflow-hidden">
            <span
              className="flex flex-col transition-transform duration-[1600ms] ease-smooth motion-reduce:transition-none"
              style={{ transform: `translateY(-${on ? +ch * 10 : 0}%)`, transitionDelay: `${i * 70}ms` }}
            >
              {Array.from({ length: 10 }, (_, d) => (
                <span key={d} className="h-[1em]">{d}</span>
              ))}
            </span>
          </span>
        ) : (
          <span key={i} aria-hidden>{ch}</span>
        ),
      )}
      <span aria-hidden>{suffix}</span>
    </span>
  );
}

export function NumberTickerDemo() {
  const [k, setK] = useState(0);
  const stats = [
    { v: 1284930, p: '$', s: '', l: 'Revenue this quarter' },
