        className={cn(
          'absolute inset-y-3 flex flex-col rounded-2xl bg-ink-900 shadow-pop transition-transform duration-[420ms] ease-[cubic-bezier(0.32,0.72,0,1)]',
          side === 'right' ? 'right-3' : 'left-3',
          visible ? 'translate-x-0' : hidden,
