import { useEffect, useRef, useState, type ReactNode, type RefObject } from 'react';
import { ArrowDown, BarChart3, Layers, Sparkles, Zap } from 'lucide-react';
import { cn } from '@/lib/cn';

/** Reveals children when they intersect the given scroll root. */
export function Reveal({ children, root, delay = 0, className }: { children: ReactNode; root?: RefObject<HTMLElement>; delay?: number; className?: string }) {
  const ref = useRef<HTMLDivElement>(null);
  const [shown, setShown] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(([e]) => setShown(e.isIntersecting), { root: root?.current ?? null, threshold: 0.2, rootMargin: '0px 0px -8% 0px' });
    io.observe(el);
    return () => io.disconnect();
  }, [root]);
  return (
    <div
      ref={ref}
      style={{ transitionDelay: shown ? `${delay}ms` : '0ms' }}
      className={cn(
        'transition-all duration-700 ease-smooth',
        shown ? 'translate-y-0 scale-100 opacity-100 blur-0' : 'translate-y-8 scale-[0.98] opacity-0 blur-[3px]',
        className,
      )}
    >
      {children}
    </div>
  );
}

/** Tracks scroll progress (0..1) and scrollTop of a container. */
export function useScrollProgress(ref: RefObject<HTMLElement>) {
  const [state, setState] = useState({ progress: 0, top: 0 });
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    let raf = 0;
    const onScroll = () => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        const max = el.scrollHeight - el.clientHeight;
        setState({ progress: max > 0 ? el.scrollTop / max : 0, top: el.scrollTop });
      });
    };
    el.addEventListener('scroll', onScroll, { passive: true });
    return () => {
      el.removeEventListener('scroll', onScroll);
      cancelAnimationFrame(raf);
    };
  }, [ref]);
  return state;
}

const FEATURES = [
  { icon: Zap, title: 'Instant previews', body: 'Every push gets a live URL in under 20 seconds.', tint: 'text-amber-300 bg-amber-500/10' },
  { icon: Layers, title: 'Branch databases', body: 'Isolated Postgres copies for each pull request.', tint: 'text-brand-300 bg-brand-500/10' },
  { icon: BarChart3, title: 'Real-user metrics', body: 'Core Web Vitals from actual visitors, not lab runs.', tint: 'text-emerald-300 bg-emerald-500/10' },
  { icon: Sparkles, title: 'AI code review', body: 'Catches regressions before your teammates do.', tint: 'text-sky-300 bg-sky-500/10' },
];

export function ScrollAnimationDemo() {
  const scroller = useRef<HTMLDivElement>(null);
  const { progress, top } = useScrollProgress(scroller);

  return (
    <div className="relative mx-auto h-[420px] w-full max-w-xl overflow-hidden rounded-2xl bg-ink-950 shadow-card">
      <div className="absolute inset-x-0 top-0 z-20 h-0.5 bg-white/5">
        <div className="h-full origin-left bg-gradient-to-r from-brand-500 to-teal-400" style={{ transform: `scaleX(${progress})` }} />
      </div>
      <div className="absolute right-3 top-3 z-20 rounded-full bg-ink-900/80 px-2 py-0.5 font-mono text-[11px] text-ink-300 shadow-hairline backdrop-blur">
        {Math.round(progress * 100)}%
      </div>
      <div ref={scroller} className="h-full overflow-y-auto overscroll-contain">
        <section className="relative flex h-[420px] flex-col items-center justify-center overflow-hidden text-center">
          <div
            className="absolute -left-10 top-10 h-48 w-48 rounded-full bg-brand-500/30 blur-3xl"
            style={{ transform: `translateY(${top * 0.5}px)` }}
          />
          <div
            className="absolute -right-10 bottom-0 h-56 w-56 rounded-full bg-teal-400/20 blur-3xl"
            style={{ transform: `translateY(${top * -0.3}px)` }}
          />
          <div style={{ transform: `translateY(${top * 0.35}px)`, opacity: Math.max(0, 1 - top / 300) }} className="relative px-6">
            <p className="text-xs font-medium uppercase tracking-[0.2em] text-brand-300">Nice Cloud</p>
            <h3 className="mt-3 text-3xl font-semibold tracking-tight text-ink-50">Ship faster, sleep better.</h3>
            <p className="mt-3 text-sm text-ink-400">Scroll inside this frame</p>
            <ArrowDown className="mx-auto mt-4 h-4 w-4 animate-float text-ink-400" />
          </div>
        </section>
        <section className="space-y-3 px-6 pb-10">
          {FEATURES.map((f, i) => (
            <Reveal key={f.title} root={scroller} delay={i % 2 ? 60 : 0}>
              <div className="flex items-start gap-4 rounded-2xl bg-ink-900 p-5 shadow-card">
                <span className={cn('flex h-10 w-10 shrink-0 items-center justify-center rounded-xl', f.tint)}>
                  <f.icon className="h-5 w-5" />
                </span>
                <div>
                  <p className="font-medium text-ink-50">{f.title}</p>
                  <p className="mt-1 text-sm text-ink-400">{f.body}</p>
                </div>
              </div>
            </Reveal>
          ))}
          <Reveal root={scroller}>
            <div className="grid grid-cols-3 gap-3 pt-4">
              {[['99.99%', 'Uptime'], ['18 ms', 'p50 latency'], ['42', 'Regions']].map(([v, l]) => (
                <div key={l} className="rounded-xl bg-ink-900 p-4 text-center shadow-hairline">
                  <p className="text-xl font-semibold text-ink-50">{v}</p>
                  <p className="mt-1 text-xs text-ink-400">{l}</p>
                </div>
              ))}
            </div>
          </Reveal>
          <Reveal root={scroller}>
            <p className="pt-8 text-center text-sm text-ink-400">That’s the end — scroll back up to replay.</p>
          </Reveal>
        </section>
      </div>
    </div>
  );
}

components/loader.content:
import { useEffect, useState, type ReactNode } from 'react';
import { cn } from '@/lib/cn';

export type LoaderVariant = 'ring' | 'dots' | 'bars' | 'orbit' | 'pulse' | 'progress' | 'skeleton' | 'gradient';

export function SpinnerRing({ size = 28, className }: { size?: number; className?: string }) {
  return (
    <span className={cn('relative inline-block', className)} style={{ width: size, height: size }} role="status" aria-label="Loading">
      <span className="absolute inset-0 rounded-full border-2 border-white/10" />
      <span className="absolute inset-0 animate-spin rounded-full border-2 border-transparent border-t-brand-400 [animation-duration:700ms]" />
    </span>
  );
}

export function DotsLoader({ className }: { className?: string }) {
  return (
    <span className={cn('flex items-center gap-1.5', className)} role="status" aria-label="Loading">
      <style>{'@keyframes dot-hop{0%,80%,100%{transform:translateY(0);opacity:.35}40%{transform:translateY(-6px);opacity:1}}'}</style>
      {[0, 1, 2].map((i) => (
        <span key={i} className="h-2 w-2 rounded-full bg-ink-50" style={{ animation: `dot-hop 1.1s ease-in-out ${i * 140}ms infinite` }} />
      ))}
    </span>
  );
}

export function BarsLoader({ className }: { className?: string }) {
  return (
    <span className={cn('flex h-7 items-center gap-1', className)} role="status" aria-label="Loading">
      {[0, 1, 2, 3, 4].map((i) => (
        <span key={i} className="h-full w-1 origin-center animate-bar-bounce rounded-full bg-brand-400" style={{ animationDelay: `${i * 110}ms` }} />
      ))}
    </span>
  );
}

export function OrbitLoader({ className }: { className?: string }) {
  return (
    <span className={cn('relative inline-block h-10 w-10', className)} role="status" aria-label="Loading">
      <span className="absolute inset-0 rounded-full border border-white/10" />
      <span className="absolute inset-0 animate-spin [animation-duration:1.4s]">
        <span className="absolute -top-1 left-1/2 h-2 w-2 -translate-x-1/2 rounded-full bg-brand-400 shadow-[0_0_10px_2px_rgba(56,189,248,0.6)]" />
      </span>
      <span className="absolute inset-2.5 animate-spin rounded-full border border-white/10 [animation-direction:reverse] [animation-duration:1s]">
        <span className="absolute -top-[3px] left-1/2 h-1.5 w-1.5 -translate-x-1/2 rounded-full bg-teal-300" />
      </span>
    </span>
  );
}

export function PulseLoader({ className }: { className?: string }) {
  return (
    <span className={cn('relative flex h-10 w-10 items-center justify-center', className)} role="status" aria-label="Loading">
      <span className="absolute h-4 w-4 animate-pulse-ring rounded-full bg-brand-400" />
      <span className="absolute h-4 w-4 animate-pulse-ring rounded-full bg-brand-400 [animation-delay:0.8s]" />
      <span className="relative h-3.5 w-3.5 rounded-full bg-brand-400" />
    </span>
  );
}

export function ProgressLoader({ className }: { className?: string }) {
  const [p, setP] = useState(0);
  useEffect(() => {
    const t = window.setInterval(() => setP((v) => (v >= 100 ? 0 : Math.min(100, v + Math.random() * 14))), 380);
    return () => window.clearInterval(t);
  }, []);
  return (
    <div className={cn('w-36', className)} role="progressbar" aria-valuenow={Math.round(p)}>
      <div className="mb-1.5 flex justify-between text-[11px] text-ink-400">
        <span>Uploading</span>
        <span className="tabular-nums">{Math.round(p)}%</span>
      </div>
      <div className="h-1.5 overflow-hidden rounded-full bg-white/10">
        <div
          className={cn('relative h-full rounded-full bg-gradient-to-r from-brand-500 to-teal-400', p > 0 && 'transition-[width] duration-300 ease-smooth')}
          style={{ width: `${p}%` }}
        >
          <span className="absolute inset-0 animate-shimmer bg-[linear-gradient(90deg,transparent,rgba(255,255,255,0.45),transparent)] bg-[length:200%_100%]" />
        </div>
      </div>
    </div>
  );
}

export function SkeletonCard({ className }: { className?: string }) {
  const bar = 'animate-shimmer rounded-md bg-[linear-gradient(90deg,#232328_0%,#36363e_50%,#232328_100%)] bg-[length:200%_100%]';
  return (
    <div className={cn('w-40 space-y-2.5', className)} role="status" aria-label="Loading">
      <div className="flex items-center gap-2">
        <span className={cn(bar, 'h-7 w-7 rounded-full')} />
        <span className="flex-1 space-y-1.5">
          <span className={cn(bar, 'block h-2 w-3/4')} />
          <span className={cn(bar, 'block h-2 w-1/2')} />
        </span>
      </div>
      <span className={cn(bar, 'block h-12 w-full rounded-lg')} />
    </div>
  );
}

export function GradientSpinner({ size = 36, className }: { size?: number; className?: string }) {
  return (
    <span
      role="status"
      aria-label="Loading"
      className={cn('inline-block animate-spin rounded-full [animation-duration:900ms]', className)}
      style={{
        width: size,
        height: size,
        background: 'conic-gradient(from 0deg, transparent 0deg, #38bdf8 200deg, #5eead4 340deg, transparent 360deg)',
        WebkitMask: 'radial-gradient(farthest-side, transparent calc(100% - 3px), #000 calc(100% - 3px))',
        mask: 'radial-gradient(farthest-side, transparent calc(100% - 3px), #000 calc(100% - 3px))',
      }}
    />
  );
}

/** Single entry point for every loader style. */
export function Loader({ variant = 'ring', className }: { variant?: LoaderVariant; className?: string }) {
  const map: Record<LoaderVariant, ReactNode> = {
    ring: <SpinnerRing className={className} />,
    dots: <DotsLoader className={className} />,
    bars: <BarsLoader className={className} />,
    orbit: <OrbitLoader className={className} />,
    pulse: <PulseLoader className={className} />,
    progress: <ProgressLoader className={className} />,
    skeleton: <SkeletonCard className={className} />,
    gradient: <GradientSpinner className={className} />,
  };
  return <>{map[variant]}</>;
}

const ALL: Array<{ name: string; node: ReactNode }> = [
  { name: 'Spinner ring', node: <SpinnerRing /> },
  { name: 'Dots', node: <DotsLoader /> },
  { name: 'Bars', node: <BarsLoader /> },
  { name: 'Orbit', node: <OrbitLoader /> },
  { name: 'Pulse', node: <PulseLoader /> },
  { name: 'Progress', node: <ProgressLoader /> },
  { name: 'Skeleton', node: <SkeletonCard /> },
  { name: 'Gradient', node: <GradientSpinner /> },
];

export function LoaderDemo() {
  return (
    <div className="mx-auto grid w-full max-w-3xl grid-cols-2 gap-3 sm:grid-cols-4">
      {ALL.map((l, i) => (
        <div
          key={l.name}
          style={{ animationDelay: `${i * 50}ms` }}
          className="group flex h-36 animate-fade-up flex-col [animation-fill-mode:backwards] items-center justify-between rounded-2xl bg-ink-900 p-4 shadow-card transition-all duration-300 ease-smooth hover:-translate-y-0.5 hover:shadow-pop"
        >
          <div className="flex flex-1 items-center justify-center">{l.node}</div>
          <p className="text-xs text-ink-400 transition-colors group-hover:text-ink-200">{l.name}</p>
        </div>
      ))}
    </div>
  );
}

components/theme-toggle.content:
import { useId, useState, type CSSProperties } from 'react';
import { Monitor, Moon, Sun } from 'lucide-react';
import { cn } from '@/lib/cn';

export type ThemeMode = 'light' | 'dark' | 'system';

/** A sun that morphs into a moon: rays retract, a mask circle slides in to carve the crescent. */
export function SunMoonToggle({ dark, onChange, className }: { dark: boolean; onChange: (dark: boolean) => void; className?: string }) {
  const id = useId();
  const ease = 'cubic-bezier(0.34,1.56,0.64,1)';
  return (
    <button
      onClick={() => onChange(!dark)}
      aria-label={dark ? 'Switch to light theme' : 'Switch to dark theme'}
      className={cn(
        'focus-ring flex h-11 w-11 items-center justify-center rounded-xl shadow-hairline transition-colors duration-500 active:scale-90',
        dark ? 'bg-ink-850 text-ink-50 hover:bg-ink-800' : 'bg-amber-400/10 text-amber-300 hover:bg-amber-400/15',
        className,
      )}
    >
      <svg viewBox="0 0 24 24" className="h-5 w-5 overflow-visible" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round">
        <mask id={id}>
          <rect x="0" y="0" width="24" height="24" fill="white" />
          <circle r="9" fill="black" style={{ transition: `transform 600ms ${ease}`, transform: dark ? 'translate(17px, 7px)' : 'translate(30px, -6px)' }} />
        </mask>
        <circle
          cx="12"
          cy="12"
          r={dark ? 9 : 5}
          fill="currentColor"
          stroke="none"
          mask={`url(#${id})`}
          style={{ r: dark ? 9 : 5, transition: `r 600ms ${ease}` } as CSSProperties}
        />
        <g
          style={{
            transformOrigin: '12px 12px',
            transition: `transform 600ms ${ease}, opacity 300ms`,
            transform: dark ? 'rotate(-90deg) scale(0.4)' : 'rotate(0deg) scale(1)',
            opacity: dark ? 0 : 1,
          }}
        >
          {Array.from({ length: 8 }, (_, i) => {
            const a = (i * Math.PI) / 4;
            return <line key={i} x1={12 + Math.cos(a) * 8} y1={12 + Math.sin(a) * 8} x2={12 + Math.cos(a) * 10.5} y2={12 + Math.sin(a) * 10.5} />;
          })}
        </g>
      </svg>
    </button>
  );
}

const MODES: Array<{ id: ThemeMode; icon: typeof Sun; label: string }> = [
  { id: 'light', icon: Sun, label: 'Light' },
  { id: 'dark', icon: Moon, label: 'Dark' },
  { id: 'system', icon: Monitor, label: 'System' },
];

export function ThemeSegmented({ value, onChange }: { value: ThemeMode; onChange: (m: ThemeMode) => void }) {
  const idx = MODES.findIndex((m) => m.id === value);
  return (
    <div role="radiogroup" className="relative grid grid-cols-3 rounded-xl bg-ink-950 p-1 shadow-hairline">
      <span
        className="absolute inset-y-1 left-1 w-[calc((100%-8px)/3)] rounded-lg bg-ink-800 shadow-hairline transition-transform duration-500 ease-spring"
        style={{ transform: `translateX(${idx * 100}%)` }}
      />
      {MODES.map((m) => (
        <button
          key={m.id}
          role="radio"
          aria-checked={value === m.id}
          onClick={() => onChange(m.id)}
          className={cn(
            'focus-ring relative z-10 flex items-center justify-center gap-1.5 rounded-lg px-3 py-1.5 text-xs font-medium transition-colors duration-300',
            value === m.id ? 'text-ink-50' : 'text-ink-400 hover:text-ink-200',
          )}
        >
          <m.icon className={cn('h-3.5 w-3.5 transition-transform duration-500 ease-spring', value === m.id && 'rotate-[360deg] scale-110')} />
          {m.label}
        </button>
      ))}
    </div>
  );
}

function PreviewCard({ light }: { light: boolean }) {
  return (
    <div
      className={cn(
        'w-full max-w-xs rounded-2xl p-5 transition-all duration-700 ease-smooth',
        light ? 'bg-white text-ink-900 shadow-[0_12px_40px_-12px_rgba(0,0,0,0.5)]' : 'bg-ink-900 text-ink-50 shadow-card',
      )}
    >
      <div className="flex items-center gap-3">
        <span className="h-9 w-9 rounded-full bg-gradient-to-br from-brand-400 to-teal-400" />
        <div>
          <p className="text-sm font-medium">Noah Bennett</p>
          <p className={cn('text-xs transition-colors duration-700', light ? 'text-ink-500' : 'text-ink-400')}>Product designer</p>
        </div>
      </div>
      <p className={cn('mt-4 text-sm leading-relaxed transition-colors duration-700', light ? 'text-ink-600' : 'text-ink-300')}>
        Shipped the new onboarding flow — activation is up 18% this week.
      </p>
      <div className={cn('mt-4 h-1.5 overflow-hidden rounded-full transition-colors duration-700', light ? 'bg-ink-100' : 'bg-white/10')}>
        <div className="h-full w-[68%] rounded-full bg-brand-500" />
      </div>
    </div>
  );
}

export function ThemeToggleDemo() {
  const [mode, setMode] = useState<ThemeMode>('dark');
  const systemDark = typeof window !== 'undefined' && window.matchMedia('(prefers-color-scheme: dark)').matches;
  const dark = mode === 'dark' || (mode === 'system' && systemDark);
  return (
    <div className="mx-auto flex w-full max-w-md flex-col items-center gap-6">
      <div className="flex items-center gap-3">
        <SunMoonToggle dark={dark} onChange={(d) => setMode(d ? 'dark' : 'light')} />
        <ThemeSegmented value={mode} onChange={setMode} />
      </div>
      <PreviewCard light={!dark} />
    </div>
  );
}

components/action-swap.content:
import { useEffect, useRef, useState, type ComponentType } from 'react';
import { Check, Copy, Heart, Pause, Play, UserPlus, Users } from 'lucide-react';
import { cn } from '@/lib/cn';

type Face = { icon: ComponentType<{ className?: string }>; label?: string };

export type ActionSwapProps = {
  active: boolean;
  onToggle: () => void;
  idle: Face;
  done: Face;
  className?: string;
  activeClassName?: string;
  idleClassName?: string;
};

/** Cross-swaps two icon/label faces with blur + scale + vertical slide. Both faces share one grid cell so width never jumps. */
export function ActionSwap({ active, onToggle, idle, done, className, activeClassName, idleClassName }: ActionSwapProps) {
  const face = (f: Face, on: boolean, dir: 1 | -1) => (
    <span
      aria-hidden={!on}
      className={cn(
        'col-start-1 row-start-1 flex items-center justify-center gap-2 transition-all duration-300 ease-spring',
        on ? 'translate-y-0 scale-100 opacity-100 blur-0' : cn('scale-50 opacity-0 blur-[4px]', dir === 1 ? 'translate-y-3' : '-translate-y-3'),
      )}
    >
      <f.icon className="h-4 w-4" />
      {f.label && <span>{f.label}</span>}
    </span>
  );
  return (
    <button
      onClick={onToggle}
      aria-pressed={active}
      className={cn(
        'focus-ring grid h-10 items-center overflow-hidden rounded-xl px-4 text-sm font-medium transition-all duration-300 active:scale-[0.95]',
        active
          ? activeClassName ?? 'bg-ink-800 text-ink-50 shadow-hairline'
          : idleClassName ?? 'bg-ink-850 text-ink-200 shadow-hairline hover:bg-ink-800',
        className,
      )}
    >
      {face(idle, !active, -1)}
      {face(done, active, 1)}
    </button>
  );
}

export function CopyButton({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  const timer = useRef<number>();
  useEffect(() => () => window.clearTimeout(timer.current), []);
  return (
    <ActionSwap
      active={copied}
      onToggle={() => {
        navigator.clipboard?.writeText(text).catch(() => undefined);
        setCopied(true);
        window.clearTimeout(timer.current);
        timer.current = window.setTimeout(() => setCopied(false), 1600);
      }}
      idle={{ icon: Copy, label: 'Copy' }}
      done={{ icon: Check, label: 'Copied' }}
      activeClassName="bg-emerald-500/10 text-emerald-300 shadow-[inset_0_0_0_1px_rgba(16,185,129,0.3)]"
    />
  );
}

const PARTICLES = 10;

/** Heart with a burst of particles + ring on like. */
export function LikeButton({ count = 128 }: { count?: number }) {
  const [liked, setLiked] = useState(false);
  const [burst, setBurst] = useState(0);
  return (
    <button
      onClick={() => {
        setLiked((l) => !l);
        if (!liked) setBurst((b) => b + 1);
      }}
      aria-pressed={liked}
      className={cn(
        'focus-ring flex h-10 items-center gap-2 rounded-xl px-3.5 text-sm font-medium shadow-hairline transition-all duration-300 active:scale-[0.95]',
        liked ? 'bg-rose-500/10 text-rose-300' : 'bg-ink-850 text-ink-200 hover:bg-ink-800',
      )}
    >
      <span className="relative flex h-4 w-4 items-center justify-center">
        <style>{'@keyframes like-burst{0%{transform:rotate(var(--a)) translateY(0) scale(1);opacity:1}100%{transform:rotate(var(--a)) translateY(-16px) scale(0);opacity:0}}@keyframes like-ring{0%{transform:scale(.2);opacity:.8}100%{transform:scale(2.4);opacity:0}}'}</style>
        {burst > 0 && liked && (
          <span key={burst} className="pointer-events-none absolute inset-0">
            <span className="absolute inset-0 rounded-full border-2 border-rose-400" style={{ animation: 'like-ring 500ms ease-out both' }} />
            {Array.from({ length: PARTICLES }, (_, i) => (
              <span
                key={i}
                className={cn('absolute left-1/2 top-1/2 -ml-[2px] -mt-[2px] h-1 w-1 rounded-full', i % 2 ? 'bg-amber-300' : 'bg-rose-400')}
                style={{ ['--a' as string]: `${(360 / PARTICLES) * i}deg`, animation: 'like-burst 600ms cubic-bezier(0.16,1,0.3,1) both' }}
              />
            ))}
          </span>
        )}
        <Heart className={cn('h-4 w-4 transition-all duration-500 ease-spring', liked ? 'scale-110 fill-rose-400 text-rose-400' : 'scale-100')} />
      </span>
      <span className="relative h-5 overflow-hidden tabular-nums">
        <span className={cn('flex flex-col transition-transform duration-500 ease-spring', liked && '-translate-y-5')}>
          <span className="h-5 leading-5">{count}</span>
          <span className="h-5 leading-5">{count + 1}</span>
        </span>
      </span>
    </button>
  );
}

export function ActionSwapDemo() {
  const [following, setFollowing] = useState(false);
  const [playing, setPlaying] = useState(false);
  return (
    <div className="flex flex-wrap items-center justify-center gap-3">
      <CopyButton text="npx lumen add action-swap" />
      <ActionSwap
        active={following}
        onToggle={() => setFollowing((f) => !f)}
        idle={{ icon: UserPlus, label: 'Follow' }}
        done={{ icon: Users, label: 'Following' }}
        className="min-w-[132px]"
        activeClassName="bg-ink-800 text-ink-50 shadow-hairline"
      />
      <ActionSwap
        active={playing}
        onToggle={() => setPlaying((p) => !p)}
        idle={{ icon: Play }}
        done={{ icon: Pause }}
        className="w-10 rounded-full px-0"
        idleClassName="bg-ink-50 text-ink-950 hover:bg-white"
        activeClassName="bg-brand-500 text-white shadow-glow"
      />
      <LikeButton />
    </div>
  );
}

components/expandable-control.content:
import { useCallback, useEffect, useRef, useState, type ReactNode } from 'react';
import { Pause, Play, SkipBack, SkipForward, Volume2, VolumeX } from 'lucide-react';
import { cn } from '@/lib/cn';
import { useClickOutside, useEscape } from './hooks';

export type ExpandableControlProps = {
  collapsed: ReactNode;
  expanded: ReactNode;
  collapsedSize?: { width: number; height: number };
  expandedSize?: { width: number; height: number };
  className?: string;
};

/** A compact pill that springs open into a full control surface. */
export function ExpandableControl({
  collapsed,
  expanded,
  collapsedSize = { width: 240, height: 52 },
  expandedSize = { width: 360, height: 212 },
  className,
}: ExpandableControlProps) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  const close = useCallback(() => setOpen(false), []);
  useEscape(open, close);
  useClickOutside([ref], open, close);
  const size = open ? expandedSize : collapsedSize;

  return (
    <div
      ref={ref}
      onClick={() => !open && setOpen(true)}
      style={{ width: size.width, height: size.height, borderRadius: open ? 28 : size.height / 2 }}
      className={cn(
        'relative max-w-full overflow-hidden bg-ink-900 shadow-pop transition-all duration-[600ms] ease-[cubic-bezier(0.34,1.3,0.64,1)]',
        !open && 'cursor-pointer hover:scale-[1.02] active:scale-[0.98]',
        className,
      )}
    >
      <div className={cn('absolute inset-0 transition-all', open ? 'pointer-events-none scale-95 opacity-0 blur-sm duration-150' : 'scale-100 opacity-100 blur-0 delay-150 duration-300')}>
        {collapsed}
      </div>
      <div
        className={cn('absolute left-0 top-0 transition-all', open ? 'scale-100 opacity-100 blur-0 delay-150 duration-500' : 'pointer-events-none scale-[0.97] opacity-0 blur-sm duration-150')}
        style={{ width: expandedSize.width, height: expandedSize.height }}
      >
        {expanded}
      </div>
    </div>
  );
}

function Eq({ on }: { on: boolean }) {
  return (
    <span className="flex h-4 items-end gap-[3px]">
      {[0, 1, 2, 3].map((i) => (
        <span
          key={i}
          className={cn('w-[3px] origin-bottom rounded-full bg-brand-400', on ? 'animate-bar-bounce' : 'scale-y-[0.3]')}
          style={{ height: '100%', animationDelay: `${i * 150}ms`, animationDuration: `${0.8 + i * 0.15}s` }}
        />
      ))}
    </span>
  );
}

const fmt = (s: number) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;
const TRACK = { title: 'Midnight Transit', artist: 'Kaito & The Lanterns', length: 214 };
const ART = 'radial-gradient(circle at 30% 30%, #7dd3fc, transparent 60%), radial-gradient(circle at 70% 80%, #f59e0b, transparent 55%), #142b57';

export function ExpandableControlDemo() {
  const [playing, setPlaying] = useState(true);
  const [t, setT] = useState(63);
  const [vol, setVol] = useState(70);

  useEffect(() => {
    if (!playing) return;
    const id = window.setInterval(() => setT((v) => (v + 1) % TRACK.length), 1000);
    return () => window.clearInterval(id);
  }, [playing]);

  const iconBtn = 'focus-ring flex h-10 w-10 items-center justify-center rounded-full text-ink-200 transition hover:bg-white/5 hover:text-ink-50 active:scale-90';

  return (
    <div className="flex h-[240px] flex-col items-center justify-center gap-3">
      <ExpandableControl
        collapsed={
          <div className="flex h-full items-center gap-3 pl-2 pr-4">
            <span className="h-9 w-9 shrink-0 rounded-full" style={{ background: ART, animation: playing ? 'spin 8s linear infinite' : undefined }} />
            <span className="min-w-0 flex-1">
              <span className="block truncate text-sm font-medium text-ink-50">{TRACK.title}</span>
              <span className="block truncate text-xs text-ink-400">{TRACK.artist}</span>
            </span>
            <Eq on={playing} />
          </div>
        }
        expanded={
          <div className="flex h-full flex-col p-5" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center gap-4">
              <span className="h-16 w-16 shrink-0 rounded-2xl shadow-card" style={{ background: ART }} />
              <div className="min-w-0 flex-1">
                <p className="truncate font-medium text-ink-50">{TRACK.title}</p>
                <p className="truncate text-sm text-ink-400">{TRACK.artist}</p>
              </div>
              <Eq on={playing} />
            </div>
            <div className="mt-4">
              <input type="range" min={0} max={TRACK.length} value={t} onChange={(e) => setT(Number(e.target.value))} aria-label="Seek" className="h-1 w-full cursor-pointer accent-brand-500" />
              <div className="mt-1 flex justify-between font-mono text-[11px] text-ink-500">
                <span>{fmt(t)}</span>
                <span>-{fmt(TRACK.length - t)}</span>
              </div>
            </div>
            <div className="mt-auto flex items-center justify-between">
              <div className="flex items-center gap-1">
                <button aria-label="Previous" className={iconBtn} onClick={() => setT(0)}><SkipBack className="h-4 w-4" /></button>
                <button aria-label={playing ? 'Pause' : 'Play'} onClick={() => setPlaying((p) => !p)} className="focus-ring flex h-10 w-10 items-center justify-center rounded-full bg-ink-50 text-ink-950 transition hover:bg-white active:scale-90">
                  {playing ? <Pause key="pa" className="h-4 w-4 animate-scale-in" /> : <Play key="pl" className="h-4 w-4 animate-scale-in" />}
                </button>
                <button aria-label="Next" className={iconBtn} onClick={() => setT(0)}><SkipForward className="h-4 w-4" /></button>
              </div>
              <div className="flex items-center gap-2">
                <button aria-label="Mute" onClick={() => setVol((v) => (v ? 0 : 70))} className="text-ink-400 transition hover:text-ink-100">
                  {vol ? <Volume2 className="h-4 w-4" /> : <VolumeX className="h-4 w-4" />}
                </button>
                <input type="range" min={0} max={100} value={vol} onChange={(e) => setVol(Number(e.target.value))} aria-label="Volume" className="h-1 w-20 cursor-pointer accent-brand-500" />
              </div>
            </div>
          </div>
        }
      />
      <p className="text-xs text-ink-500">Click the pill · Esc or click outside to collapse</p>
    </div>
  );
}

import { useEffect, useState, type ReactNode, type RefObject } from 'react';
import { createPortal } from 'react-dom';

/**
 * Keeps an element mounted while it animates out.
 * `mounted` controls rendering, `visible` drives the enter/exit classes.
 */
export function usePresence(open: boolean, exitMs = 220) {
  const [mounted, setMounted] = useState(open);
  const [visible, setVisible] = useState(open);

  useEffect(() => {
    if (open) {
      setMounted(true);
      let inner = 0;
      const outer = requestAnimationFrame(() => {
        inner = requestAnimationFrame(() => setVisible(true));
      });
      return () => {
        cancelAnimationFrame(outer);
        cancelAnimationFrame(inner);
      };
    }
    setVisible(false);
    const t = window.setTimeout(() => setMounted(false), exitMs);
    return () => window.clearTimeout(t);
  }, [open, exitMs]);

  return { mounted, visible };
}

/** Calls `handler` when Escape is pressed while `active`. */
export function useEscape(active: boolean, handler: () => void) {
  useEffect(() => {
    if (!active) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') handler();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [active, handler]);
}

/** Calls `handler` on pointerdown outside every provided ref while `active`. */
export function useClickOutside(
  refs: Array<RefObject<HTMLElement>>,
  active: boolean,
  handler: () => void,
) {
  useEffect(() => {
    if (!active) return;
    const onDown = (e: PointerEvent) => {
      const target = e.target as Node;
      if (refs.some((r) => r.current?.contains(target))) return;
      handler();
    };
    document.addEventListener('pointerdown', onDown);
    return () => document.removeEventListener('pointerdown', onDown);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [active, handler]);
}

/**
 * Renders overlays into document.body so `position: fixed` is relative to the
 * viewport even when an ancestor has a transform (e.g. entrance animations).
 */
export function Portal({ children }: { children: ReactNode }) {
  if (typeof document === 'undefined') return null;
  return createPortal(children, document.body);
}

