import { useCallback, useMemo, useRef, useState } from 'react';
import { Heart, Loader2 } from 'lucide-react';
import { cn } from '@/lib/cn';

export type MasonryItem = { id: number; title: string; author: string; height: number; gradient: string; likes: number };

const GRADIENTS = [
  'from-brand-400 via-sky-500 to-teal-400',
  'from-amber-300 via-orange-400 to-rose-500',
  'from-emerald-300 via-teal-400 to-sky-500',
  'from-rose-400 via-pink-500 to-amber-300',
  'from-sky-300 via-brand-500 to-brand-800',
  'from-teal-300 via-emerald-500 to-ink-800',
  'from-amber-200 via-amber-400 to-emerald-500',
  'from-ink-300 via-ink-500 to-ink-800',
];
const TITLES = ['Aurora study', 'Low tide', 'Neon dusk', 'Glass forms', 'Quiet fields', 'Solar drift', 'Coastline', 'Monolith', 'Haze', 'Prism walk', 'After rain', 'Ember'];
const AUTHORS = ['Mira', 'Daniel', 'Sana', 'Leo', 'Ana', 'Kenji'];

export function makeItems(start: number, count: number): MasonryItem[] {
  return Array.from({ length: count }, (_, k) => {
    const id = start + k;
    const seed = (id * 9301 + 49297) % 233280;
    return {
      id,
      title: TITLES[id % TITLES.length],
      author: AUTHORS[(id * 7) % AUTHORS.length],
      height: 120 + (seed % 140),
      gradient: GRADIENTS[(id * 5) % GRADIENTS.length],
      likes: 20 + (seed % 900),
    };
  });
}

export type InfiniteMasonryProps = {
  columns?: number;
  pageSize?: number;
  maxItems?: number;
  threshold?: number;
  height?: number;
};

export function InfiniteMasonry({ columns = 3, pageSize = 9, maxItems = 54, threshold = 160, height = 440 }: InfiniteMasonryProps) {
  const [items, setItems] = useState(() => makeItems(0, pageSize * 2));
  const [loading, setLoading] = useState(false);
  const [liked, setLiked] = useState<Set<number>>(new Set());
  const loadingRef = useRef(false);
  const done = items.length >= maxItems;

  const loadMore = useCallback(() => {
    if (loadingRef.current || done) return;
    loadingRef.current = true;
    setLoading(true);
    window.setTimeout(() => {
      setItems((xs) => [...xs, ...makeItems(xs.length, pageSize)]);
      setLoading(false);
      loadingRef.current = false;
    }, 1100);
  }, [done, pageSize]);

  const cols = useMemo(() => {
    const out: Array<Array<MasonryItem | { skeleton: number; height: number }>> = Array.from({ length: columns }, () => []);
    const heights = new Array(columns).fill(0);
    const place = (it: MasonryItem | { skeleton: number; height: number }) => {
      const c = heights.indexOf(Math.min(...heights));
      out[c].push(it);
      heights[c] += it.height;
    };
    items.forEach(place);
    if (loading) Array.from({ length: columns * 2 }, (_, i) => place({ skeleton: i, height: 130 + (i % 3) * 40 }));
    return out;
  }, [items, loading, columns]);

  return (
    <div
      onScroll={(e) => {
        const el = e.currentTarget;
        if (el.scrollHeight - el.scrollTop - el.clientHeight < threshold) loadMore();
      }}
      className="relative w-full overflow-y-auto rounded-2xl bg-ink-950/60 p-3 shadow-card"
      style={{ height }}
    >
      <div className="flex gap-3">
        {cols.map((col, ci) => (
          <div key={ci} className="flex min-w-0 flex-1 flex-col gap-3">
            {col.map((it) =>
              'skeleton' in it ? (
                <div key={`s${it.skeleton}`} className="relative overflow-hidden rounded-xl bg-ink-850 shadow-hairline" style={{ height: it.height }}>
                  <div className="absolute inset-0 animate-pulse bg-white/[0.03]" />
                  <div className="absolute bottom-3 left-3 space-y-1.5">
                    <div className="h-2.5 w-20 rounded-full bg-white/[0.06]" />
                    <div className="h-2 w-12 rounded-full bg-white/[0.04]" />
                  </div>
                </div>
              ) : (
                <article
                  key={it.id}
                  className={cn('group relative animate-fade-up overflow-hidden rounded-xl bg-gradient-to-br shadow-card', it.gradient)}
                  style={{ height: it.height, animationDelay: `${(it.id % pageSize) * 40}ms` }}
                >
                  <div className="absolute inset-0 bg-gradient-to-t from-ink-950/80 via-ink-950/0 to-transparent opacity-80 transition-opacity duration-300 group-hover:opacity-100" />
                  <div className="absolute inset-0 scale-110 bg-[radial-gradient(circle_at_30%_20%,rgba(255,255,255,0.35),transparent_55%)] transition-transform duration-700 ease-smooth group-hover:scale-100" />
                  <button
                    aria-label="Like"
                    onClick={() => setLiked((s) => { const n = new Set(s); n.has(it.id) ? n.delete(it.id) : n.add(it.id); return n; })}
                    className="absolute right-2 top-2 flex h-7 w-7 translate-y-1 items-center justify-center rounded-full bg-ink-950/50 text-white opacity-0 backdrop-blur transition-all duration-200 group-hover:translate-y-0 group-hover:opacity-100 active:scale-90"
                  >
                    <Heart className={cn('h-3.5 w-3.5 transition-colors', liked.has(it.id) && 'fill-rose-400 text-rose-400')} />
                  </button>
                  <div className="absolute inset-x-3 bottom-2.5 text-white">
                    <p className="truncate text-sm font-medium">{it.title}</p>
                    <p className="text-[11px] text-white/70">@{it.author.toLowerCase()} · {it.likes + (liked.has(it.id) ? 1 : 0)} likes</p>
                  </div>
                </article>
              ),
            )}
          </div>
        ))}
      </div>
      <div className="flex h-14 items-center justify-center text-xs text-ink-500">
        {loading ? (
          <span className="flex items-center gap-2"><Loader2 className="h-3.5 w-3.5 animate-spin" /> Loading more</span>
        ) : done ? (
          'You’ve reached the end ✦'
        ) : (
          'Scroll for more'
        )}
      </div>
    </div>
  );
}

export function InfiniteMasonryDemo() {
  return (
    <div className="mx-auto w-full max-w-2xl">
      <InfiniteMasonry />
    </div>
  );
}

blocks/project-folder.content:
import { useState } from 'react';
import { cn } from '@/lib/cn';

export type ProjectFolderProps = {
  title: string;
  meta: string;
  color?: 'brand' | 'amber' | 'emerald' | 'rose';
  papers?: string[];
  open?: boolean;
  onClick?: () => void;
};

const TONES = {
  brand: { back: 'from-brand-700 to-brand-900', front: 'from-brand-500 to-brand-700', glow: 'rgba(56,189,248,0.35)' },
  amber: { back: 'from-amber-600 to-amber-800', front: 'from-amber-400 to-amber-600', glow: 'rgba(251,191,36,0.3)' },
  emerald: { back: 'from-emerald-700 to-emerald-900', front: 'from-emerald-400 to-emerald-600', glow: 'rgba(52,211,153,0.3)' },
  rose: { back: 'from-rose-700 to-rose-900', front: 'from-rose-400 to-rose-600', glow: 'rgba(251,113,133,0.3)' },
};

const FAN = [
  { x: -34, y: -38, r: -14 },
  { x: 0, y: -52, r: 0 },
  { x: 34, y: -38, r: 14 },
];

export function ProjectFolder({ title, meta, color = 'brand', papers = ['Brief', 'Wireframes', 'Assets'], open, onClick }: ProjectFolderProps) {
  const [hover, setHover] = useState(false);
  const active = open ?? hover;
  const tone = TONES[color];

  return (
    <button
      onClick={onClick}
      onPointerEnter={() => setHover(true)}
      onPointerLeave={() => setHover(false)}
      onFocus={() => setHover(true)}
      onBlur={() => setHover(false)}
      className="focus-ring group flex flex-col items-center gap-4 rounded-2xl p-3 outline-none"
    >
      <div
        className="relative h-[120px] w-[160px] transition-transform duration-500 ease-spring"
        style={{ transform: active ? 'translateY(-4px)' : 'none', filter: active ? `drop-shadow(0 18px 24px ${tone.glow})` : 'drop-shadow(0 8px 16px rgba(0,0,0,0.5))' }}
      >
        {/* back + tab */}
        <div className={cn('absolute left-0 top-0 h-5 w-16 rounded-t-lg bg-gradient-to-b', tone.back)} />
        <div className={cn('absolute inset-x-0 bottom-0 top-3 rounded-xl rounded-tl-none bg-gradient-to-b', tone.back)} />
        {/* papers */}
        {papers.slice(0, 3).map((p, i) => {
          const f = FAN[i];
          return (
            <div
              key={p}
              className="absolute bottom-3 left-1/2 flex h-[92px] w-[110px] flex-col gap-1.5 rounded-lg bg-ink-50 p-2.5 shadow-card transition-transform duration-500 ease-spring"
              style={{
                transform: active
                  ? `translateX(calc(-50% + ${f.x}px)) translateY(${f.y}px) rotate(${f.r}deg)`
                  : `translateX(-50%) translateY(${-6 - i * 3}px) rotate(${(i - 1) * 2}deg)`,
                transitionDelay: `${active ? i * 50 : (2 - i) * 30}ms`,
              }}
            >
              <span className="truncate text-left text-[10px] font-medium text-ink-900">{p}</span>
              <span className="h-1 w-4/5 rounded-full bg-ink-200" />
              <span className="h-1 w-3/5 rounded-full bg-ink-200" />
              <span className="h-1 w-2/3 rounded-full bg-ink-200" />
            </div>
          );
        })}
        {/* front */}
        <div
          className={cn('absolute inset-x-0 bottom-0 h-[84px] origin-bottom rounded-xl bg-gradient-to-b shadow-[inset_0_1px_0_rgba(255,255,255,0.25)] transition-transform duration-500 ease-spring', tone.front)}
          style={{ transform: active ? 'perspective(500px) rotateX(-34deg)' : 'perspective(500px) rotateX(-6deg)' }}
        >
          <div className="absolute inset-x-3 top-2 h-px bg-white/20" />
        </div>
      </div>
      <div className="text-center">
        <p className="text-sm font-medium text-ink-100">{title}</p>
        <p className="text-xs text-ink-400">{meta}</p>
      </div>
    </button>
  );
}

export function ProjectFolderDemo() {
  const [selected, setSelected] = useState<string | null>(null);
  const folders = [
    { title: 'Brand refresh', meta: '24 files · 3 members', color: 'brand' as const, papers: ['Moodboard', 'Logo v4', 'Guidelines'] },
    { title: 'Mobile app', meta: '112 files · 8 members', color: 'amber' as const, papers: ['Flows', 'Screens', 'Specs'] },
    { title: 'Q3 Launch', meta: '9 files · 2 members', color: 'emerald' as const, papers: ['Plan', 'Copy', 'Press kit'] },
  ];
  return (
    <div className="flex flex-col items-center gap-6 pt-8">
      <div className="flex flex-wrap justify-center gap-6">
        {folders.map((f) => (
          <ProjectFolder key={f.title} {...f} open={selected === f.title ? true : undefined} onClick={() => setSelected((s) => (s === f.title ? null : f.title))} />
        ))}
      </div>
      <p className="h-4 text-xs text-ink-500">Hover a folder · click to pin it open</p>
    </div>
  );
}

blocks/card-folder.content:
import { useState } from 'react';
import { Check, Wallet } from 'lucide-react';
import { cn } from '@/lib/cn';

export type WalletCard = { id: string; brand: string; last4: string; holder: string; gradient: string; balance: string };

const CARDS: WalletCard[] = [
  { id: 'a', brand: 'Visa', last4: '4242', holder: 'Mira Chen', gradient: 'from-brand-400 via-brand-600 to-brand-900', balance: '$4,820.12' },
  { id: 'b', brand: 'Mastercard', last4: '8812', holder: 'Mira Chen', gradient: 'from-amber-300 via-orange-500 to-rose-600', balance: '$1,204.50' },
  { id: 'c', brand: 'Amex', last4: '1005', holder: 'Mira Chen', gradient: 'from-emerald-300 via-teal-500 to-sky-700', balance: '$12,930.00' },
  { id: 'd', brand: 'Debit', last4: '7731', holder: 'Mira Chen', gradient: 'from-ink-500 via-ink-700 to-ink-900', balance: '$389.77' },
];

export type CardFolderProps = { cards?: WalletCard[]; selected: string | null; onSelect: (id: string | null) => void };

export function CardFolder({ cards = CARDS, selected, onSelect }: CardFolderProps) {
  const [hover, setHover] = useState(false);
  const [lift, setLift] = useState<string | null>(null);
  const open = hover && !selected;
  const mid = (cards.length - 1) / 2;

  return (
    <div
      className="relative h-[300px] w-[300px]"
      onPointerEnter={() => setHover(true)}
      onPointerLeave={() => setHover(false)}
    >
      {/* back of wallet */}
      <div className="absolute inset-x-2 bottom-0 h-[150px] rounded-3xl bg-ink-800 shadow-card" />
      {cards.map((c, i) => {
        const isSel = selected === c.id;
        let transform = `translateX(-50%) translateY(${-60 - (cards.length - 1 - i) * 16}px)`;
        if (open) transform = `translateX(-50%) translateY(${lift === c.id ? -112 : -92}px) rotate(${(i - mid) * 11}deg) translateX(${(i - mid) * 6}px)`;
        if (selected) transform = isSel ? 'translateX(-50%) translateY(-138px) scale(1.04)' : `translateX(-50%) translateY(${-24 - (cards.length - 1 - i) * 6}px) scale(0.94)`;
        return (
          <button
            key={c.id}
            onClick={() => onSelect(isSel ? null : c.id)}
            onPointerEnter={() => setLift(c.id)}
            onPointerLeave={() => setLift(null)}
            aria-pressed={isSel}
            className={cn(
              'focus-ring absolute bottom-0 left-1/2 flex h-[160px] w-[256px] origin-bottom flex-col justify-between rounded-2xl bg-gradient-to-br p-4 text-left text-white shadow-pop transition-all duration-500 ease-spring',
              c.gradient,
            )}
            style={{ transform, zIndex: isSel ? 40 : i + 1, transitionDelay: open ? `${i * 30}ms` : '0ms' }}
          >
            <div className="flex items-start justify-between">
              <span className="text-sm font-semibold tracking-wide">{c.brand}</span>
              <span className={cn('flex h-5 w-5 items-center justify-center rounded-full bg-white text-ink-900 transition-all duration-300', isSel ? 'scale-100 opacity-100' : 'scale-50 opacity-0')}>
                <Check className="h-3 w-3" />
              </span>
            </div>
            <div className="h-7 w-9 rounded-md bg-gradient-to-br from-amber-100/90 to-amber-400/80 shadow-[inset_0_0_0_1px_rgba(0,0,0,0.15)]" />
            <div className="flex items-end justify-between">
              <span className="font-mono text-sm tracking-[0.2em]">•••• {c.last4}</span>
              <span className="text-[11px] text-white/70">{c.holder}</span>
            </div>
          </button>
        );
      })}
      {/* front pocket */}
      <div className="pointer-events-none absolute inset-x-0 bottom-0 z-30 h-[118px] rounded-3xl bg-gradient-to-b from-ink-700 to-ink-850 shadow-[inset_0_1px_0_rgba(255,255,255,0.08),0_-8px_24px_-8px_rgba(0,0,0,0.6)]">
        <div className="absolute inset-x-6 top-3 border-t border-dashed border-white/10" />
        <div className="absolute bottom-4 left-5 flex items-center gap-2 text-ink-300">
          <Wallet className="h-4 w-4" />
          <span className="text-xs font-medium">{cards.length} cards</span>
        </div>
      </div>
    </div>
  );
}

export function CardFolderDemo() {
  const [selected, setSelected] = useState<string | null>(null);
  const card = CARDS.find((c) => c.id === selected);
  return (
    <div className="flex flex-col items-center gap-5 pt-4">
      <CardFolder selected={selected} onSelect={setSelected} />
      <div className="h-12 text-center">
        {card ? (
          <div key={card.id} className="animate-fade-up">
            <p className="text-lg font-medium tabular-nums text-ink-50">{card.balance}</p>
            <p className="text-xs text-ink-400">{card.brand} •• {card.last4} · tap again to return</p>
          </div>
        ) : (
          <p className="pt-3 text-xs text-ink-500">Hover the wallet to fan out · click a card to select</p>
        )}
      </div>
    </div>
  );
}

blocks/fixtures.content:
import { useEffect, useState } from 'react';
import { Bell, Trophy } from 'lucide-react';
import { cn } from '@/lib/cn';

type Team = { name: string; short: string; color: string };
export type Fixture = { id: string; home: Team; away: Team; status: 'live' | 'ft' | 'upcoming'; score?: [number, number]; minute?: number; kickoff?: string; league: string };

const T = (name: string, short: string, color: string): Team => ({ name, short, color });
const ARS = T('Arsenal', 'ARS', 'bg-rose-500'), CHE = T('Chelsea', 'CHE', 'bg-brand-600'), LIV = T('Liverpool', 'LIV', 'bg-rose-700');
const MCI = T('Man City', 'MCI', 'bg-sky-400'), TOT = T('Tottenham', 'TOT', 'bg-ink-200'), NEW = T('Newcastle', 'NEW', 'bg-ink-600');
const AVL = T('Aston Villa', 'AVL', 'bg-amber-700'), BHA = T('Brighton', 'BHA', 'bg-brand-400');

export const FIXTURE_DAYS: Array<{ id: string; label: string; date: string; fixtures: Fixture[] }> = [
  { id: 'y', label: 'Yesterday', date: 'Sat 14', fixtures: [
    { id: '1', home: LIV, away: TOT, status: 'ft', score: [3, 1], league: 'Premier League' },
    { id: '2', home: BHA, away: NEW, status: 'ft', score: [0, 0], league: 'Premier League' },
  ] },
  { id: 't', label: 'Today', date: 'Sun 15', fixtures: [
    { id: '3', home: ARS, away: CHE, status: 'live', score: [2, 1], minute: 67, league: 'Premier League' },
    { id: '4', home: MCI, away: AVL, status: 'live', score: [1, 1], minute: 38, league: 'Premier League' },
    { id: '5', home: NEW, away: LIV, status: 'upcoming', kickoff: '19:45', league: 'Premier League' },
  ] },
  { id: 'm', label: 'Tomorrow', date: 'Mon 16', fixtures: [
    { id: '6', home: TOT, away: ARS, status: 'upcoming', kickoff: '17:30', league: 'Premier League' },
    { id: '7', home: CHE, away: BHA, status: 'upcoming', kickoff: '20:00', league: 'FA Cup' },
    { id: '8', home: AVL, away: MCI, status: 'upcoming', kickoff: '20:00', league: 'FA Cup' },
  ] },
];

function Crest({ team }: { team: Team }) {
  return (
    <span className={cn('flex h-8 w-8 shrink-0 items-center justify-center rounded-full text-[10px] font-semibold text-ink-950 shadow-[inset_0_-2px_0_rgba(0,0,0,0.2)]', team.color)}>
      {team.short}
    </span>
  );
}

export function FixtureRow({ f, index }: { f: Fixture; index: number }) {
  const [minute, setMinute] = useState(f.minute ?? 0);
  const [remind, setRemind] = useState(false);
  useEffect(() => {
    if (f.status !== 'live') return;
    const id = window.setInterval(() => setMinute((m) => Math.min(90, m + 1)), 4000);
    return () => window.clearInterval(id);
  }, [f.status]);

  return (
    <div className="flex animate-fade-up items-center gap-3 rounded-xl px-3 py-3 transition-colors hover:bg-white/[0.03]" style={{ animationDelay: `${index * 60}ms` }}>
      <div className="flex flex-1 items-center justify-end gap-2.5 text-right">
        <span className="truncate text-sm font-medium text-ink-100">{f.home.name}</span>
        <Crest team={f.home} />
      </div>
      <div className="flex w-24 flex-col items-center">
        {f.status === 'upcoming' ? (
          <>
            <span className="font-mono text-sm text-ink-200">{f.kickoff}</span>
            <button
              onClick={() => setRemind((r) => !r)}
              className={cn('mt-0.5 flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-medium transition-all active:scale-95', remind ? 'bg-brand-500/15 text-brand-300' : 'text-ink-500 hover:text-ink-200')}
            >
              <Bell className={cn('h-2.5 w-2.5', remind && 'animate-wiggle fill-current')} /> {remind ? 'Reminder set' : 'Remind'}
            </button>
          </>
        ) : (
          <>
            <span className="font-mono text-xl font-medium tabular-nums text-ink-50">
              {f.score?.[0]} <span className="text-ink-600">–</span> {f.score?.[1]}
            </span>
            {f.status === 'live' ? (
              <span className="flex items-center gap-1.5 text-[10px] font-medium text-emerald-400">
                <span className="relative flex h-1.5 w-1.5">
                  <span className="absolute inset-0 animate-pulse-ring rounded-full bg-emerald-400" />
                  <span className="relative h-1.5 w-1.5 rounded-full bg-emerald-400" />
                </span>
                LIVE {minute}’
              </span>
            ) : (
              <span className="text-[10px] font-medium text-ink-500">FT</span>
            )}
          </>
        )}
      </div>
      <div className="flex flex-1 items-center gap-2.5">
        <Crest team={f.away} />
        <span className="truncate text-sm font-medium text-ink-100">{f.away.name}</span>
      </div>
    </div>
  );
}

export function Fixtures({ days = FIXTURE_DAYS, defaultDay = 't' }: { days?: typeof FIXTURE_DAYS; defaultDay?: string }) {
  const [day, setDay] = useState(defaultDay);
  const idx = Math.max(0, days.findIndex((d) => d.id === day));
  const current = days[idx];
  const live = current.fixtures.filter((f) => f.status === 'live').length;

  return (
    <div className="w-full max-w-md overflow-hidden rounded-2xl bg-ink-900 shadow-card">
      <div className="flex items-center justify-between px-4 pb-3 pt-4">
        <div className="flex items-center gap-2">
          <Trophy className="h-4 w-4 text-amber-400" />
          <span className="text-sm font-medium text-ink-50">Fixtures</span>
        </div>
        {live > 0 && <span className="animate-fade-in rounded-full bg-emerald-500/10 px-2 py-0.5 text-[11px] font-medium text-emerald-300">{live} live now</span>}
      </div>
      <div className="relative mx-4 grid rounded-xl bg-ink-950/60 p-1" style={{ gridTemplateColumns: `repeat(${days.length}, 1fr)` }}>
        <span
          className="absolute inset-y-1 left-1 rounded-lg bg-ink-800 shadow-hairline transition-transform duration-500 ease-spring"
          style={{ width: `calc((100% - 8px) / ${days.length})`, transform: `translateX(${idx * 100}%)` }}
        />
        {days.map((d) => (
          <button key={d.id} onClick={() => setDay(d.id)} className={cn('focus-ring relative z-10 rounded-lg py-1.5 text-center transition-colors', day === d.id ? 'text-ink-50' : 'text-ink-400 hover:text-ink-200')}>
            <span className="block text-xs font-medium">{d.label}</span>
            <span className="block text-[10px] text-ink-500">{d.date}</span>
          </button>
        ))}
      </div>
      <div key={day} className="p-2 pt-3">
        <p className="px-3 pb-1 text-[11px] font-medium uppercase tracking-wider text-ink-500">{current.fixtures[0]?.league}</p>
        {current.fixtures.map((f, i) => <FixtureRow key={f.id} f={f} index={i} />)}
      </div>
    </div>
  );
}

export function FixturesDemo() {
  return (
    <div className="flex justify-center">
      <Fixtures />
    </div>
  );
}

blocks/availability-scheduler.content:
import { useState } from 'react';
import { Check, Plus, Trash2 } from 'lucide-react';
import { cn } from '@/lib/cn';

export type TimeRange = { id: number; start: string; end: string };
export type DaySchedule = { day: string; enabled: boolean; ranges: TimeRange[] };

const TIMES = Array.from({ length: 33 }, (_, i) => {
  const mins = 6 * 60 + i * 30;
  return `${String(Math.floor(mins / 60)).padStart(2, '0')}:${mins % 60 === 0 ? '00' : '30'}`;
});

let uid = 100;
const range = (start = '09:00', end = '17:00'): TimeRange => ({ id: uid++, start, end });

export const DEFAULT_WEEK: DaySchedule[] = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'].map((day, i) => ({
  day,
  enabled: i < 5,
  ranges: i === 2 ? [range('09:00', '12:00'), range('13:30', '18:00')] : [range()],
}));

function Switch({ on, onChange, label }: { on: boolean; onChange: () => void; label: string }) {
  return (
    <button
      role="switch"
      aria-checked={on}
      aria-label={label}
      onClick={onChange}
      className={cn('focus-ring relative h-5 w-9 shrink-0 rounded-full transition-colors duration-300', on ? 'bg-brand-500' : 'bg-ink-700')}
    >
      <span className={cn('absolute left-0.5 top-0.5 h-4 w-4 rounded-full bg-white shadow transition-transform duration-300 ease-spring', on && 'translate-x-4')} />
    </button>
  );
}

function TimeSelect({ value, onChange, label }: { value: string; onChange: (v: string) => void; label: string }) {
  return (
    <select
      aria-label={label}
      value={value}
      onChange={(e) => onChange(e.target.value)}
      className="focus-ring h-8 cursor-pointer appearance-none rounded-lg bg-ink-850 px-2.5 font-mono text-xs text-ink-100 shadow-hairline transition-colors hover:bg-ink-800"
    >
      {TIMES.map((t) => <option key={t} value={t}>{t}</option>)}
    </select>
  );
}

export type AvailabilitySchedulerProps = { value: DaySchedule[]; onChange: (next: DaySchedule[]) => void };

export function AvailabilityScheduler({ value, onChange }: AvailabilitySchedulerProps) {
  const [leaving, setLeaving] = useState<number[]>([]);
  const update = (i: number, patch: Partial<DaySchedule>) => onChange(value.map((d, j) => (j === i ? { ...d, ...patch } : d)));

  const removeRange = (i: number, id: number) => {
    setLeaving((l) => [...l, id]);
    window.setTimeout(() => {
      onChange(value.map((d, j) => (j === i ? { ...d, ranges: d.ranges.filter((r) => r.id !== id), enabled: d.ranges.length > 1 } : d)));
      setLeaving((l) => l.filter((x) => x !== id));
    }, 260);
  };

  return (
    <div className="divide-y divide-white/5">
      {value.map((d, i) => (
        <div key={d.day} className="flex gap-4 py-3">
          <div className="flex w-32 shrink-0 items-center gap-3 self-start pt-1.5">
            <Switch on={d.enabled} label={`Toggle ${d.day}`} onChange={() => update(i, { enabled: !d.enabled, ranges: d.ranges.length ? d.ranges : [range()] })} />
            <span className={cn('text-sm font-medium transition-colors', d.enabled ? 'text-ink-100' : 'text-ink-500')}>{d.day.slice(0, 3)}</span>
          </div>
          <div className="min-w-0 flex-1">
            <div className={cn('grid transition-all duration-500 ease-smooth', d.enabled ? 'grid-rows-[1fr] opacity-100' : 'grid-rows-[0fr] opacity-0')}>
              <div className="overflow-hidden">
                {d.ranges.map((r, ri) => {
                  const out = leaving.includes(r.id);
                  return (
                    <div key={r.id} className={cn('grid transition-all duration-300 ease-smooth', out ? 'grid-rows-[0fr] opacity-0' : 'grid-rows-[1fr] opacity-100')}>
                      <div className="overflow-hidden">
                        <div className={cn('flex items-center gap-2 py-1', !out && 'animate-fade-up')}>
                          <TimeSelect label="Start time" value={r.start} onChange={(v) => update(i, { ranges: d.ranges.map((x) => (x.id === r.id ? { ...x, start: v } : x)) })} />
                          <span className="text-ink-600">–</span>
                          <TimeSelect label="End time" value={r.end} onChange={(v) => update(i, { ranges: d.ranges.map((x) => (x.id === r.id ? { ...x, end: v } : x)) })} />
                          {r.end <= r.start && <span className="animate-fade-in text-[11px] text-rose-400">Invalid</span>}
                          <div className="ml-auto flex gap-0.5">
                            {ri === 0 && (
                              <button aria-label="Add range" onClick={() => update(i, { ranges: [...d.ranges, range('18:00', '20:00')] })} className="focus-ring flex h-8 w-8 items-center justify-center rounded-lg text-ink-400 transition-all hover:bg-white/5 hover:text-ink-100 active:scale-90">
                                <Plus className="h-4 w-4" />
                              </button>
                            )}
                            <button aria-label="Remove range" onClick={() => removeRange(i, r.id)} className="focus-ring flex h-8 w-8 items-center justify-center rounded-lg text-ink-400 transition-all hover:bg-rose-500/10 hover:text-rose-300 active:scale-90">
                              <Trash2 className="h-3.5 w-3.5" />
                            </button>
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
            {!d.enabled && <p className="animate-fade-in pt-1.5 text-sm text-ink-500">Unavailable</p>}
          </div>
        </div>
      ))}
    </div>
  );
}

export function AvailabilitySchedulerDemo() {
  const [week, setWeek] = useState(DEFAULT_WEEK);
  const [saved, setSaved] = useState(false);
  const hours = week.filter((d) => d.enabled).reduce((sum, d) => sum + d.ranges.reduce((s, r) => {
    const [sh, sm] = r.start.split(':').map(Number); const [eh, em] = r.end.split(':').map(Number);
    return s + Math.max(0, eh * 60 + em - sh * 60 - sm) / 60;
  }, 0), 0);

  return (
    <div className="mx-auto w-full max-w-lg rounded-2xl bg-ink-900 p-5 shadow-card">
      <div className="mb-2 flex items-center justify-between">
        <div>
          <p className="text-sm font-medium text-ink-50">Working hours</p>
          <p className="text-xs text-ink-400">{hours.toFixed(1)}h available per week · Europe/London</p>
        </div>
        <button
          onClick={() => { setSaved(true); window.setTimeout(() => setSaved(false), 1800); }}
          className={cn('focus-ring flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-xs font-medium transition-all active:scale-95', saved ? 'bg-emerald-500/15 text-emerald-300' : 'bg-ink-50 text-ink-950 hover:bg-white')}
        >
          {saved && <Check className="h-3.5 w-3.5 animate-scale-in" />} {saved ? 'Saved' : 'Save changes'}
        </button>
      </div>
      <AvailabilityScheduler value={week} onChange={setWeek} />
    </div>
  );
}

