import { useLayoutEffect, useRef, useState, type ReactNode } from 'react';
import { ArrowUpRight, TrendingDown, TrendingUp } from 'lucide-react';
import { cn } from '@/lib/cn';

export type MorphTab = { id: string; label: string; content: ReactNode };

export type MorphingTabsProps = { tabs: MorphTab[]; defaultValue?: string; onChange?: (id: string) => void };

export function MorphingTabs({ tabs, defaultValue, onChange }: MorphingTabsProps) {
  const [value, setValue] = useState(defaultValue ?? tabs[0].id);
  const [dir, setDir] = useState<1 | -1>(1);
  const [box, setBox] = useState({ left: 0, right: 0, ready: false });
  const listRef = useRef<HTMLDivElement>(null);
  const refs = useRef<Record<string, HTMLButtonElement | null>>({});
  const idx = tabs.findIndex((t) => t.id === value);

  useLayoutEffect(() => {
    const measureNow = () => {
      const el = refs.current[value];
      const list = listRef.current;
      if (!el || !list) return;
      setBox({ left: el.offsetLeft, right: list.clientWidth - el.offsetLeft - el.offsetWidth, ready: true });
    };
    measureNow();
    window.addEventListener('resize', measureNow);
    return () => window.removeEventListener('resize', measureNow);
  }, [value]);

  const select = (id: string) => {
    const next = tabs.findIndex((t) => t.id === id);
    setDir(next > idx ? 1 : -1);
    setValue(id);
    onChange?.(id);
  };

  const lead = 'cubic-bezier(0.34,1.3,0.64,1) 380ms';
  const trail = 'cubic-bezier(0.34,1.2,0.64,1) 420ms 90ms';

  return (
    <div className="w-full">
      <div ref={listRef} role="tablist" className="relative flex rounded-xl bg-ink-950/60 p-1 shadow-hairline">
        <span
          className={cn('absolute inset-y-1 rounded-lg bg-ink-800 shadow-[0_0_0_1px_rgba(255,255,255,0.08),0_4px_12px_-2px_rgba(0,0,0,0.5)]', !box.ready && 'opacity-0')}
          style={{
            left: box.left,
            right: box.right,
            transition: dir === 1 ? `right ${lead}, left ${trail}` : `left ${lead}, right ${trail}`,
          }}
        />
        {tabs.map((t) => (
          <button
            key={t.id}
            ref={(el) => (refs.current[t.id] = el)}
            role="tab"
            aria-selected={value === t.id}
            onClick={() => select(t.id)}
            className={cn('focus-ring relative z-10 flex-1 rounded-lg px-4 py-2 text-sm font-medium transition-colors duration-300', value === t.id ? 'text-ink-50' : 'text-ink-400 hover:text-ink-200')}
          >
            {t.label}
          </button>
        ))}
      </div>
      <div className="mt-4 grid">
        {tabs.map((t, i) => {
          const on = t.id === value;
          const offset = i < idx ? -16 : 16;
          return (
            <div
              key={t.id}
              role="tabpanel"
              aria-hidden={!on}
              className={cn('[grid-area:1/1] transition-all duration-500 ease-smooth', on ? 'opacity-100 blur-0' : 'pointer-events-none opacity-0 blur-sm')}
              style={{ transform: on ? 'none' : `translateX(${offset}px)`, transitionDelay: on ? '80ms' : '0ms' }}
            >
              {t.content}
            </div>
          );
        })}
      </div>
    </div>
  );
}

function Stat({ label, value, delta }: { label: string; value: string; delta: number }) {
  const up = delta >= 0;
  return (
    <div className="rounded-xl bg-ink-850 p-3.5 shadow-hairline">
      <p className="text-xs text-ink-400">{label}</p>
      <p className="mt-1 text-xl font-medium tabular-nums text-ink-50">{value}</p>
      <p className={cn('mt-1 flex items-center gap-1 text-xs', up ? 'text-emerald-400' : 'text-rose-400')}>
        {up ? <TrendingUp className="h-3 w-3" /> : <TrendingDown className="h-3 w-3" />}
        {up ? '+' : ''}{delta}% vs last period
      </p>
    </div>
  );
}

const PERIODS = [
  { id: 'day', label: 'Today', stats: [['Revenue', '$4,281', 12.4], ['Visitors', '18,204', 4.1], ['Conversion', '3.8%', -0.6]] },
  { id: 'week', label: 'Week', stats: [['Revenue', '$28,940', 8.2], ['Visitors', '121,880', 11.9], ['Conversion', '4.1%', 1.2]] },
  { id: 'month', label: 'Month', stats: [['Revenue', '$118,302', 21.7], ['Visitors', '502,114', 18.3], ['Conversion', '4.4%', 2.4]] },
  { id: 'year', label: 'Year', stats: [['Revenue', '$1.24M', 64.0], ['Visitors', '5.9M', 48.2], ['Conversion', '3.9%', -1.1]] },
] as const;

export function MorphingTabsDemo() {
  return (
    <div className="mx-auto w-full max-w-lg rounded-2xl bg-ink-900 p-4 shadow-card">
      <div className="mb-4 flex items-center justify-between px-1">
        <p className="text-sm font-medium text-ink-50">Overview</p>
        <a href="#" onClick={(e) => e.preventDefault()} className="flex items-center gap-1 text-xs text-ink-400 transition-colors hover:text-ink-100">
          Full report <ArrowUpRight className="h-3 w-3" />
        </a>
      </div>
      <MorphingTabs
        defaultValue="week"
        tabs={PERIODS.map((p) => ({
          id: p.id,
          label: p.label,
          content: (
            <div className="grid grid-cols-3 gap-2">
              {p.stats.map(([l, v, d]) => <Stat key={l} label={l} value={v} delta={d} />)}
            </div>
          ),
        }))}
      />
    </div>
  );
}

blocks/swipeable-list.content:
import { useRef, useState, type ReactNode } from 'react';
import { Archive, RefreshCw, Trash2 } from 'lucide-react';
import { cn } from '@/lib/cn';

const REVEAL = 80;

export type SwipeRowProps = {
  children: ReactNode;
  onArchive: () => void;
  onDelete: () => void;
};

export function SwipeRow({ children, onArchive, onDelete }: SwipeRowProps) {
  const [x, setX] = useState(0);
  const [dragging, setDragging] = useState(false);
  const [gone, setGone] = useState<null | 'left' | 'right'>(null);
  const start = useRef({ px: 0, x: 0, w: 1 });

  const commit = (side: 'left' | 'right') => {
    setGone(side);
    setX(side === 'right' ? start.current.w : -start.current.w);
    window.setTimeout(side === 'right' ? onArchive : onDelete, 540);
  };

  const onUp = () => {
    if (!dragging) return;
    setDragging(false);
    const w = start.current.w;
    if (x > w * 0.45) return commit('right');
    if (x < -w * 0.45) return commit('left');
    if (x > REVEAL * 0.6) return setX(REVEAL);
    if (x < -REVEAL * 0.6) return setX(-REVEAL);
    setX(0);
  };

  const progress = Math.min(1, Math.abs(x) / (start.current.w * 0.45));
  return (
    <div className={cn('grid transition-all duration-300 ease-smooth', gone ? 'grid-rows-[0fr] opacity-0 delay-200' : 'grid-rows-[1fr]')}>
      <div className="overflow-hidden">
        <div className="relative overflow-hidden rounded-xl">
          <div className={cn('absolute inset-0 flex items-center justify-between transition-colors', x > 0 ? 'bg-emerald-500' : x < 0 ? 'bg-rose-500' : 'bg-transparent')}>
            <button onClick={() => commit('right')} tabIndex={-1} className="flex h-full items-center gap-2 pl-5 text-sm font-medium text-ink-950" style={{ opacity: x > 0 ? 1 : 0 }}>
              <Archive className="h-4 w-4 transition-transform duration-200" style={{ transform: `scale(${0.7 + progress * 0.5})` }} /> Archive
            </button>
            <button onClick={() => commit('left')} tabIndex={-1} className="flex h-full items-center gap-2 pr-5 text-sm font-medium text-white" style={{ opacity: x < 0 ? 1 : 0 }}>
              Delete <Trash2 className="h-4 w-4 transition-transform duration-200" style={{ transform: `scale(${0.7 + progress * 0.5})` }} />
            </button>
          </div>
          <div
            onPointerDown={(e) => {
              if (gone) return;
              e.currentTarget.setPointerCapture(e.pointerId);
              start.current = { px: e.clientX, x, w: e.currentTarget.offsetWidth };
              setDragging(true);
            }}
            onPointerMove={(e) => {
              if (!dragging) return;
              const raw = start.current.x + e.clientX - start.current.px;
              const max = start.current.w * 0.7;
              setX(Math.abs(raw) > max ? Math.sign(raw) * (max + (Math.abs(raw) - max) * 0.25) : raw);
            }}
            onPointerUp={onUp}
            onPointerCancel={onUp}
            className={cn('relative touch-pan-y select-none bg-ink-850', dragging ? 'cursor-grabbing' : 'cursor-grab transition-transform duration-500 ease-spring')}
            style={{ transform: `translateX(${x}px)` }}
          >
            {children}
          </div>
        </div>
      </div>
    </div>
  );
}

export type MailItem = { id: number; from: string; subject: string; preview: string; time: string; color: string };

const MAIL: MailItem[] = [
  { id: 1, from: 'Mira Chen', subject: 'Onboarding v2 is ready', preview: 'I tightened the copy on step two and…', time: '9:41', color: 'from-amber-300 to-rose-400' },
  { id: 2, from: 'Vercel', subject: 'Deployment ready', preview: 'lumen-ui-docs deployed to production', time: '9:12', color: 'from-ink-200 to-ink-500' },
  { id: 3, from: 'Daniel Okafor', subject: 'Re: perf budget', preview: 'Bundle is down 18% after the split…', time: '8:57', color: 'from-brand-300 to-brand-600' },
  { id: 4, from: 'Linear', subject: '3 issues assigned to you', preview: 'LUM-212 Command palette arrow nav…', time: 'Yesterday', color: 'from-sky-300 to-teal-500' },
  { id: 5, from: 'Stripe', subject: 'Payout sent', preview: '$12,480.00 is on its way to your bank', time: 'Mon', color: 'from-emerald-300 to-teal-600' },
];

export function SwipeableListDemo() {
  const [items, setItems] = useState(MAIL);
  const [log, setLog] = useState<string | null>(null);
  const remove = (id: number, verb: string) => {
    const m = items.find((x) => x.id === id);
    setItems((xs) => xs.filter((x) => x.id !== id));
    setLog(`${verb} “${m?.subject}”`);
  };
  return (
    <div className="mx-auto w-full max-w-sm">
      <div className="space-y-1.5 rounded-2xl bg-ink-900 p-1.5 shadow-card">
        {items.map((m) => (
          <SwipeRow key={m.id} onArchive={() => remove(m.id, 'Archived')} onDelete={() => remove(m.id, 'Deleted')}>
            <div className="flex items-center gap-3 px-3 py-3">
              <span className={cn('h-9 w-9 shrink-0 rounded-full bg-gradient-to-br', m.color)} />
              <div className="min-w-0 flex-1">
                <div className="flex items-baseline justify-between gap-2">
                  <p className="truncate text-sm font-medium text-ink-50">{m.from}</p>
                  <span className="shrink-0 text-[11px] text-ink-500">{m.time}</span>
                </div>
                <p className="truncate text-xs text-ink-200">{m.subject}</p>
                <p className="truncate text-xs text-ink-500">{m.preview}</p>
              </div>
            </div>
          </SwipeRow>
        ))}
        {items.length === 0 && (
          <div className="flex animate-scale-in flex-col items-center gap-3 py-10 text-sm text-ink-400">
            Inbox zero ✦
            <button onClick={() => setItems(MAIL)} className="flex items-center gap-1.5 rounded-full bg-ink-850 px-3 py-1.5 text-xs text-ink-200 shadow-hairline hover:text-ink-50">
              <RefreshCw className="h-3 w-3" /> Reset
            </button>
          </div>
        )}
      </div>
      <p className="mt-3 h-4 text-center text-xs text-ink-500">{log ? <span key={log} className="animate-fade-in">{log}</span> : 'Drag a row left to delete, right to archive'}</p>
    </div>
  );
}

blocks/file-upload.content:
import { useEffect, useRef, useState } from 'react';
import { CheckCircle2, File, FileText, Image, Music, Upload, X } from 'lucide-react';
import { cn } from '@/lib/cn';

export type UploadItem = { id: number; name: string; size: number; type: string; progress: number; leaving?: boolean };

const fmtSize = (b: number) => (b > 1e6 ? `${(b / 1e6).toFixed(1)} MB` : `${Math.max(1, Math.round(b / 1e3))} KB`);
const iconFor = (t: string) => (t.startsWith('image') ? Image : t.startsWith('audio') ? Music : t.includes('pdf') || t.startsWith('text') ? FileText : File);

let nextId = 1;

export type FileUploadProps = { accept?: string; maxSizeMb?: number; multiple?: boolean; defaultItems?: UploadItem[] };

export function FileUpload({ accept, maxSizeMb = 25, multiple = true, defaultItems = [] }: FileUploadProps) {
  const [items, setItems] = useState<UploadItem[]>(defaultItems);
  const [over, setOver] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const depth = useRef(0);
  const input = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!items.some((i) => i.progress < 100 && !i.leaving)) return;
    const id = window.setInterval(() => {
      setItems((xs) => xs.map((x) => (x.progress < 100 ? { ...x, progress: Math.min(100, x.progress + 4 + Math.random() * 14 * (2e6 / Math.max(x.size, 4e5))) } : x)));
    }, 180);
    return () => window.clearInterval(id);
  }, [items]);

  const add = (files: FileList | null) => {
    if (!files) return;
    const list = Array.from(files);
    const tooBig = list.filter((f) => f.size > maxSizeMb * 1e6);
    setError(tooBig.length ? `${tooBig[0].name} is over ${maxSizeMb} MB` : null);
    const ok = list.filter((f) => f.size <= maxSizeMb * 1e6).map((f) => ({ id: nextId++, name: f.name, size: f.size, type: f.type, progress: 0 }));
    setItems((xs) => [...ok, ...xs]);
  };

  const remove = (id: number) => {
    setItems((xs) => xs.map((x) => (x.id === id ? { ...x, leaving: true } : x)));
    window.setTimeout(() => setItems((xs) => xs.filter((x) => x.id !== id)), 300);
  };

  return (
    <div className="w-full max-w-md space-y-3">
      <div
        role="button"
        tabIndex={0}
        onClick={() => input.current?.click()}
        onKeyDown={(e) => (e.key === 'Enter' || e.key === ' ') && input.current?.click()}
        onDragEnter={(e) => { e.preventDefault(); depth.current++; setOver(true); }}
        onDragOver={(e) => e.preventDefault()}
        onDragLeave={() => { depth.current--; if (depth.current <= 0) setOver(false); }}
        onDrop={(e) => { e.preventDefault(); depth.current = 0; setOver(false); add(e.dataTransfer.files); }}
        className={cn(
          'focus-ring group relative flex cursor-pointer flex-col items-center justify-center gap-3 overflow-hidden rounded-2xl border border-dashed px-6 py-9 text-center transition-all duration-300 ease-smooth',
          over ? 'scale-[1.02] border-brand-400 bg-brand-500/10 shadow-glow' : 'border-white/10 bg-ink-900 hover:border-white/20 hover:bg-ink-850',
        )}
      >
        <div className={cn('pointer-events-none absolute inset-0 bg-[radial-gradient(circle_at_50%_0%,rgba(56,189,248,0.25),transparent_60%)] transition-opacity duration-500', over ? 'opacity-100' : 'opacity-0')} />
        <span className={cn('relative flex h-12 w-12 items-center justify-center rounded-2xl bg-ink-800 text-ink-200 shadow-hairline transition-all duration-500 ease-spring', over ? '-translate-y-1 scale-110 bg-brand-500 text-white' : 'group-hover:-translate-y-0.5')}>
          <Upload className={cn('h-5 w-5 transition-transform duration-500 ease-spring', over && '-translate-y-0.5')} />
        </span>
        <div className="relative">
          <p className="text-sm font-medium text-ink-100">{over ? 'Drop to upload' : 'Drag files here or click to browse'}</p>
          <p className="mt-1 text-xs text-ink-500">PNG, JPG, PDF or MP3 · up to {maxSizeMb} MB</p>
        </div>
        <input ref={input} type="file" multiple={multiple} accept={accept} className="hidden" onChange={(e) => { add(e.target.files); e.target.value = ''; }} />
      </div>
      {error && <p key={error} className="animate-wiggle text-xs text-rose-400">{error}</p>}
      <div>
        {items.map((it) => {
          const Icon = iconFor(it.type);
          const done = it.progress >= 100;
          return (
            <div key={it.id} className={cn('grid transition-all duration-300 ease-smooth', it.leaving ? 'grid-rows-[0fr] scale-95 opacity-0' : 'grid-rows-[1fr]')}>
              <div className="overflow-hidden">
                <div className="mb-2 flex animate-fade-up items-center gap-3 rounded-xl bg-ink-900 p-3 shadow-card">
                  <span className={cn('flex h-9 w-9 shrink-0 items-center justify-center rounded-lg transition-colors duration-500', done ? 'bg-emerald-500/15 text-emerald-300' : 'bg-ink-800 text-ink-300')}>
                    <Icon className="h-4 w-4" />
                  </span>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center justify-between gap-2 text-xs">
                      <span className="truncate font-medium text-ink-100">{it.name}</span>
                      <span className="shrink-0 tabular-nums text-ink-500">{done ? fmtSize(it.size) : `${Math.floor(it.progress)}%`}</span>
                    </div>
                    <div className={cn('mt-2 h-1 overflow-hidden rounded-full bg-ink-800 transition-opacity duration-500', done && 'opacity-0')}>
                      <div className="h-full rounded-full bg-gradient-to-r from-brand-500 to-sky-400 transition-[width] duration-200" style={{ width: `${it.progress}%` }} />
                    </div>
                  </div>
                  {done ? (
                    <CheckCircle2 className="h-4 w-4 shrink-0 animate-scale-in text-emerald-400" />
                  ) : null}
                  <button aria-label={`Remove ${it.name}`} onClick={() => remove(it.id)} className="focus-ring flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-ink-500 transition-colors hover:bg-white/5 hover:text-ink-100">
                    <X className="h-3.5 w-3.5" />
                  </button>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

export function FileUploadDemo() {
  return (
    <div className="flex min-h-[360px] items-start justify-center">
      <FileUpload
        defaultItems={[
          { id: -1, name: 'launch-keynote.pdf', size: 8_420_000, type: 'application/pdf', progress: 36 },
          { id: -2, name: 'hero-shot@2x.png', size: 2_810_000, type: 'image/png', progress: 100 },
        ]}
      />
    </div>
  );
}

