import { useEffect, useMemo, useState } from 'react';
import { Check, Clock, TrendingUp, Users } from 'lucide-react';
import { cn } from '@/lib/cn';

function series(seed: number, n: number, end: number) {
  let v = end - 18;
  const out: number[] = [];
  for (let i = 0; i < n; i++) {
    const r = Math.sin(i * 1.7 + seed) * 0.5 + Math.sin(i * 0.37 + seed * 2) * 0.5;
    v = Math.max(5, Math.min(95, v + r * 4 + (end - v) * 0.06));
    out.push(v);
  }
  out[n - 1] = end;
  return out;
}

export function Sparkline({ data, width = 320, height = 88, hover, onHover }: { data: number[]; width?: number; height?: number; hover: number | null; onHover: (i: number | null) => void }) {
  const pts = data.map((v, i) => [(i / (data.length - 1)) * width, height - (v / 100) * height] as const);
  const line = pts.map(([x, y], i) => `${i ? 'L' : 'M'}${x.toFixed(1)},${y.toFixed(1)}`).join(' ');
  const hp = hover !== null ? pts[hover] : null;
  const [drawn, setDrawn] = useState(false);
  useEffect(() => {
    const r = requestAnimationFrame(() => setDrawn(true));
    return () => cancelAnimationFrame(r);
  }, []);
  return (
    <div
      className="relative"
      style={{ height }}
      onPointerMove={(e) => {
        const r = e.currentTarget.getBoundingClientRect();
        onHover(Math.max(0, Math.min(data.length - 1, Math.round(((e.clientX - r.left) / r.width) * (data.length - 1)))));
      }}
      onPointerLeave={() => onHover(null)}
    >
      <svg viewBox={`0 0 ${width} ${height}`} className="absolute inset-0 h-full w-full overflow-visible" preserveAspectRatio="none">
        <defs>
          <linearGradient id="pm-fill" x1="0" x2="0" y1="0" y2="1">
            <stop offset="0%" stopColor="#34d399" stopOpacity="0.25" />
            <stop offset="100%" stopColor="#34d399" stopOpacity="0" />
          </linearGradient>
        </defs>
        <line x1="0" x2={width} y1={height / 2} y2={height / 2} stroke="rgba(255,255,255,0.06)" strokeDasharray="3 4" />
        <path d={`${line} L${width},${height} L0,${height} Z`} fill="url(#pm-fill)" className={cn('transition-opacity delay-300 duration-700', drawn ? 'opacity-100' : 'opacity-0')} />
        <path
          d={line}
          fill="none"
          stroke="#34d399"
          strokeWidth="2"
          strokeLinejoin="round"
          pathLength={1}
          strokeDasharray="1"
          style={{ strokeDashoffset: drawn ? 0 : 1, transition: 'stroke-dashoffset 1200ms cubic-bezier(0.16,1,0.3,1)' }}
        />
      </svg>
      {hp && (
        <>
          <span className="pointer-events-none absolute inset-y-0 w-px bg-white/15" style={{ left: `${(hp[0] / width) * 100}%` }} />
          <span
            className="pointer-events-none absolute h-2.5 w-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full bg-emerald-400 ring-2 ring-ink-900"
            style={{ left: `${(hp[0] / width) * 100}%`, top: hp[1] }}
          />
        </>
      )}
    </div>
  );
}

const RANGES = { '1D': 24, '1W': 42, '1M': 60, ALL: 90 } as const;
type Range = keyof typeof RANGES;

export function PredictionMarket({ question = 'Will ETH close above $4,000 on Dec 31?', initialYes = 64 }: { question?: string; initialYes?: number }) {
  const [yes, setYes] = useState(initialYes);
  const [range, setRange] = useState<Range>('1W');
  const [hover, setHover] = useState<number | null>(null);
  const [side, setSide] = useState<'yes' | 'no'>('yes');
  const [amount, setAmount] = useState(50);
  const [bought, setBought] = useState(false);
  const data = useMemo(() => series(RANGES[range], RANGES[range], yes), [range, yes]);

  const price = (side === 'yes' ? yes : 100 - yes) / 100;
  const shares = amount / price;
  const payout = shares;
  const ret = ((payout - amount) / Math.max(amount, 1)) * 100;
  const shown = hover !== null ? data[hover] : yes;

  const buy = () => {
    if (!amount) return;
    setBought(true);
    setYes((y) => Math.max(3, Math.min(97, y + (side === 'yes' ? 1 : -1) * Math.max(1, Math.round(amount / 60)))));
    window.setTimeout(() => setBought(false), 1800);
  };

  return (
    <div className="w-full max-w-md rounded-2xl bg-ink-900 p-5 shadow-card">
      <div className="flex items-start gap-3">
        <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-gradient-to-br from-sky-300 to-brand-600 text-sm font-semibold text-white">Ξ</span>
        <div>
          <p className="text-sm font-medium leading-snug text-ink-50">{question}</p>
          <p className="mt-1 flex items-center gap-3 text-[11px] text-ink-500">
            <span className="flex items-center gap-1"><TrendingUp className="h-3 w-3" />$2.4M vol</span>
            <span className="flex items-center gap-1"><Users className="h-3 w-3" />8,912</span>
            <span className="flex items-center gap-1"><Clock className="h-3 w-3" />Ends Dec 31</span>
          </p>
        </div>
      </div>

      <div className="mt-5 flex items-end justify-between">
        <p className="text-3xl font-medium tabular-nums text-emerald-400">{Math.round(shown)}%<span className="ml-1.5 text-sm text-ink-400">chance</span></p>
        <div className="flex gap-0.5 rounded-lg bg-ink-950/60 p-0.5">
          {(Object.keys(RANGES) as Range[]).map((r) => (
            <button key={r} onClick={() => setRange(r)} className={cn('rounded-md px-2 py-0.5 text-[11px] font-medium transition-colors', range === r ? 'bg-ink-800 text-ink-50 shadow-hairline' : 'text-ink-500 hover:text-ink-200')}>{r}</button>
          ))}
        </div>
      </div>
      <div className="mt-3" key={range}>
        <Sparkline data={data} hover={hover} onHover={setHover} />
      </div>

      <div className="mt-4 flex h-2 overflow-hidden rounded-full bg-ink-800">
        <div className="h-full bg-emerald-400 transition-[width] duration-700 ease-spring" style={{ width: `${yes}%` }} />
        <div className="h-full flex-1 bg-rose-400/80" />
      </div>
      <div className="mt-1.5 flex justify-between text-[11px] font-medium"><span className="text-emerald-400">Yes {yes}¢</span><span className="text-rose-400">No {100 - yes}¢</span></div>

      <div className="mt-4 rounded-xl bg-ink-850 p-3 shadow-hairline">
        <div className="relative grid grid-cols-2 rounded-lg bg-ink-950/60 p-0.5">
          <span className={cn('absolute inset-y-0.5 left-0.5 w-[calc(50%-2px)] rounded-md transition-all duration-500 ease-spring', side === 'yes' ? 'translate-x-0 bg-emerald-500/20' : 'translate-x-full bg-rose-500/20')} />
          {(['yes', 'no'] as const).map((s) => (
            <button key={s} onClick={() => setSide(s)} className={cn('relative py-1.5 text-sm font-medium capitalize transition-colors', side === s ? (s === 'yes' ? 'text-emerald-300' : 'text-rose-300') : 'text-ink-400')}>
              Buy {s} · {s === 'yes' ? yes : 100 - yes}¢
            </button>
          ))}
        </div>
        <div className="mt-3 flex items-center gap-2">
          <div className="flex flex-1 items-center rounded-lg bg-ink-950/60 px-3 shadow-hairline focus-within:shadow-glow">
            <span className="text-ink-500">$</span>
            <input value={amount || ''} placeholder="0" inputMode="numeric" onChange={(e) => setAmount(Math.min(100000, Number(e.target.value.replace(/\D/g, '')) || 0))} className="h-9 w-full bg-transparent pl-1 text-sm tabular-nums text-ink-50 outline-none" />
          </div>
          {[10, 50, 100].map((v) => (
            <button key={v} onClick={() => setAmount((a) => a + v)} className="h-9 rounded-lg bg-ink-800 px-2.5 text-xs font-medium text-ink-300 transition-all hover:text-ink-50 active:scale-95">+{v}</button>
          ))}
        </div>
        <div className="mt-3 space-y-1 text-xs">
          <div className="flex justify-between text-ink-400"><span>Shares</span><span className="tabular-nums text-ink-200">{shares.toFixed(2)}</span></div>
          <div className="flex justify-between text-ink-400">
            <span>Potential payout</span>
            <span className="tabular-nums font-medium text-emerald-400">${payout.toFixed(2)} <span className="text-ink-500">(+{ret.toFixed(0)}%)</span></span>
          </div>
        </div>
        <button
          onClick={buy}
          disabled={!amount}
          className={cn('mt-3 flex h-10 w-full items-center justify-center gap-2 rounded-lg text-sm font-medium transition-all active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-40', bought ? 'bg-ink-50 text-ink-950' : side === 'yes' ? 'bg-emerald-500 text-ink-950 hover:bg-emerald-400' : 'bg-rose-500 text-white hover:bg-rose-400')}
        >
          {bought ? <><Check className="h-4 w-4 animate-scale-in" /> Order filled</> : `Buy ${side === 'yes' ? 'Yes' : 'No'} · $${amount}`}
        </button>
      </div>
    </div>
  );
}

export function PredictionMarketDemo() {
  return (
    <div className="flex justify-center">
      <PredictionMarket />
    </div>
  );
}

blocks/wallet-card.content:
import { useState } from 'react';
import { ArrowDown, ArrowUpRight, Check, Copy, Eye, EyeOff, Loader2, RefreshCw } from 'lucide-react';
import { cn } from '@/lib/cn';
import { NumberTicker } from '@/components/ui/motion/NumberTicker';

export type Asset = { symbol: string; name: string; amount: number; price: number; change: number; color: string };

const ASSETS: Asset[] = [
  { symbol: 'ETH', name: 'Ethereum', amount: 3.214, price: 3421.18, change: 2.4, color: 'from-sky-300 to-brand-600' },
  { symbol: 'BTC', name: 'Bitcoin', amount: 0.1821, price: 64210.5, change: -0.8, color: 'from-amber-300 to-orange-600' },
  { symbol: 'SOL', name: 'Solana', amount: 41.2, price: 168.42, change: 6.1, color: 'from-teal-300 to-emerald-600' },
  { symbol: 'USDC', name: 'USD Coin', amount: 2480.5, price: 1, change: 0, color: 'from-brand-400 to-brand-700' },
];

const usd = (n: number) => n.toLocaleString('en-US', { style: 'currency', currency: 'USD' });
type Panel = null | 'send' | 'receive';

export function WalletCard({ assets = ASSETS, address = '0x71C9…3f8A' }: { assets?: Asset[]; address?: string }) {
  const [hidden, setHidden] = useState(false);
  const [panel, setPanel] = useState<Panel>(null);
  const [copied, setCopied] = useState(false);
  const [sendAmt, setSendAmt] = useState('');
  const [sending, setSending] = useState<'idle' | 'busy' | 'done'>('idle');
  const [list, setList] = useState(assets);
  const total = list.reduce((s, a) => s + a.amount * a.price, 0);
  const change = list.reduce((s, a) => s + a.amount * a.price * (a.change / 100), 0);

  const send = () => {
    const v = parseFloat(sendAmt);
    if (!v) return;
    setSending('busy');
    window.setTimeout(() => {
      setList((l) => l.map((a) => (a.symbol === 'USDC' ? { ...a, amount: Math.max(0, a.amount - v) } : a)));
      setSending('done');
      window.setTimeout(() => { setSending('idle'); setPanel(null); setSendAmt(''); }, 1200);
    }, 1200);
  };

  return (
    <div className="w-full max-w-sm overflow-hidden rounded-3xl bg-ink-900 shadow-card">
      <div className="relative overflow-hidden p-5">
        <div className="pointer-events-none absolute -right-16 -top-20 h-56 w-56 rounded-full bg-brand-500/20 blur-3xl" />
        <div className="relative flex items-center justify-between">
          <span className="text-xs font-medium text-ink-400">Total balance</span>
          <button aria-label={hidden ? 'Show balance' : 'Hide balance'} onClick={() => setHidden((h) => !h)} className="focus-ring flex h-7 w-7 items-center justify-center rounded-lg text-ink-400 transition-colors hover:bg-white/5 hover:text-ink-100">
            {hidden ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
          </button>
        </div>
        <div className="relative mt-1 h-10 text-4xl font-medium tracking-tight text-ink-50">
          <span className={cn('absolute inset-0 transition-all duration-500 ease-smooth', hidden ? 'opacity-0 blur-md' : 'opacity-100 blur-0')}>
            <NumberTicker value={total} format={usd} />
          </span>
          <span className={cn('absolute inset-0 flex items-center gap-1.5 transition-all duration-500 ease-smooth', hidden ? 'opacity-100' : 'translate-y-2 opacity-0')}>
            {Array.from({ length: 6 }, (_, i) => <span key={i} className="h-3 w-3 rounded-full bg-ink-500" style={{ transitionDelay: `${i * 30}ms` }} />)}
          </span>
        </div>
        <p className={cn('relative mt-1 text-xs', change >= 0 ? 'text-emerald-400' : 'text-rose-400')}>
          {hidden ? '••••' : `${change >= 0 ? '+' : ''}${usd(change)}`} today
        </p>
        <div className="relative mt-5 grid grid-cols-2 gap-2">
          {(['send', 'receive'] as const).map((p) => (
            <button
              key={p}
              onClick={() => setPanel((x) => (x === p ? null : p))}
              className={cn('focus-ring flex h-10 items-center justify-center gap-2 rounded-xl text-sm font-medium capitalize transition-all active:scale-[0.97]', panel === p ? 'bg-ink-50 text-ink-950' : p === 'send' ? 'bg-brand-500 text-white hover:bg-brand-400' : 'bg-ink-800 text-ink-100 shadow-hairline hover:bg-ink-700')}
            >
              {p === 'send' ? <ArrowUpRight className="h-4 w-4" /> : <ArrowDown className="h-4 w-4" />} {p}
            </button>
          ))}
        </div>
        <div className={cn('grid transition-all duration-500 ease-smooth', panel ? 'mt-3 grid-rows-[1fr] opacity-100' : 'grid-rows-[0fr] opacity-0')}>
          <div className="overflow-hidden">
            {panel === 'receive' && (
              <div className="flex animate-fade-up items-center gap-3 rounded-xl bg-ink-850 p-3 shadow-hairline">
                <div className="grid h-12 w-12 shrink-0 grid-cols-5 gap-px rounded-md bg-white p-1">
                  {Array.from({ length: 25 }, (_, i) => <span key={i} className={cn('rounded-[1px]', (i * 7) % 3 ? 'bg-ink-950' : 'bg-white')} />)}
                </div>
                <div className="min-w-0 flex-1">
                  <p className="text-[11px] text-ink-500">Your address · Ethereum</p>
                  <p className="font-mono text-sm text-ink-100">{address}</p>
                </div>
                <button aria-label="Copy address" onClick={() => { setCopied(true); window.setTimeout(() => setCopied(false), 1400); }} className="focus-ring flex h-8 w-8 items-center justify-center rounded-lg text-ink-300 hover:bg-white/5">
                  {copied ? <Check className="h-4 w-4 animate-scale-in text-emerald-400" /> : <Copy className="h-4 w-4" />}
                </button>
              </div>
            )}
            {panel === 'send' && (
              <div className="flex animate-fade-up items-center gap-2 rounded-xl bg-ink-850 p-2 shadow-hairline">
                <input autoFocus inputMode="decimal" value={sendAmt} onChange={(e) => /^\d*\.?\d*$/.test(e.target.value) && setSendAmt(e.target.value)} placeholder="Amount in USDC" className="h-9 min-w-0 flex-1 bg-transparent px-2 text-sm tabular-nums text-ink-50 outline-none placeholder:text-ink-500" />
                <button onClick={send} disabled={!parseFloat(sendAmt) || sending !== 'idle'} className={cn('flex h-9 items-center gap-1.5 rounded-lg px-3 text-xs font-medium transition-all disabled:opacity-50', sending === 'done' ? 'bg-emerald-500 text-ink-950' : 'bg-brand-500 text-white')}>
                  {sending === 'busy' && <Loader2 className="h-3.5 w-3.5 animate-spin" />}
                  {sending === 'done' ? <><Check className="h-3.5 w-3.5" /> Sent</> : 'Send'}
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
      <div className="border-t border-white/5 p-2">
        <div className="flex items-center justify-between px-3 py-2">
          <span className="text-xs font-medium text-ink-400">Assets</span>
          <button aria-label="Refresh" onClick={() => setList((l) => l.map((a) => ({ ...a, price: a.symbol === 'USDC' ? 1 : a.price * (1 + (Math.random() - 0.5) * 0.03) })))} className="group text-ink-500 hover:text-ink-200">
            <RefreshCw className="h-3.5 w-3.5 transition-transform duration-500 group-active:rotate-180" />
          </button>
        </div>
        {list.map((a, i) => (
