import { useRef, useState } from 'react';
import { CheckCircle2, Loader2, Lock, RefreshCw } from 'lucide-react';
import { cn } from '@/lib/cn';

export type OtpStatus = 'idle' | 'verifying' | 'success' | 'error';

export type OtpInputProps = {
  length?: number;
  onComplete: (code: string) => Promise<boolean>;
  status: OtpStatus;
  disabled?: boolean;
};

export function OtpInput({ length = 6, onComplete, status, disabled }: OtpInputProps) {
  const [digits, setDigits] = useState<string[]>(() => Array(length).fill(''));
  const [focus, setFocus] = useState(0);
  const refs = useRef<Array<HTMLInputElement | null>>([]);
  const [shakeKey, setShakeKey] = useState(0);
  const locked = disabled || status === 'verifying' || status === 'success';

  const go = (i: number) => refs.current[Math.max(0, Math.min(length - 1, i))]?.focus();

  const commit = async (next: string[]) => {
    setDigits(next);
    if (next.every(Boolean)) {
      refs.current.forEach((r) => r?.blur());
      const ok = await onComplete(next.join(''));
      if (!ok) {
        setShakeKey((k) => k + 1);
        window.setTimeout(() => { setDigits(Array(length).fill('')); go(0); }, 450);
      }
    }
  };

  const fill = (start: number, text: string) => {
    const chars = text.replace(/\D/g, '').slice(0, length - start).split('');
    if (!chars.length) return;
    const next = [...digits];
    chars.forEach((c, k) => (next[start + k] = c));
    go(start + chars.length);
    void commit(next);
  };

  return (
    <div key={shakeKey} className={cn('flex gap-2', shakeKey > 0 && status === 'error' && 'animate-wiggle')}>
      {digits.map((d, i) => {
        const tone =
          status === 'success' ? 'bg-emerald-500/10 text-emerald-300 shadow-[0_0_0_1px_rgba(52,211,153,0.5)]'
          : status === 'error' ? 'bg-rose-500/10 text-rose-300 shadow-[0_0_0_1px_rgba(251,113,133,0.5)]'
          : focus === i && !locked ? 'bg-ink-850 text-ink-50 shadow-glow' : 'bg-ink-850 text-ink-50 shadow-hairline';
        return (
          <div key={i} className="relative">
            <input
              ref={(el) => (refs.current[i] = el)}
              aria-label={`Digit ${i + 1}`}
              inputMode="numeric"
              autoComplete={i === 0 ? 'one-time-code' : 'off'}
              maxLength={1}
              value={d}
              disabled={locked}
              onFocus={(e) => { setFocus(i); e.currentTarget.select(); }}
              onBlur={() => setFocus(-1)}
              onChange={(e) => fill(i, e.target.value.slice(-1))}
              onPaste={(e) => { e.preventDefault(); fill(i, e.clipboardData.getData('text')); }}
              onKeyDown={(e) => {
                if (e.key === 'Backspace') {
                  e.preventDefault();
                  const next = [...digits];
                  if (next[i]) next[i] = '';
                  else if (i > 0) { next[i - 1] = ''; go(i - 1); }
                  setDigits(next);
                }
                if (e.key === 'ArrowLeft') go(i - 1);
                if (e.key === 'ArrowRight') go(i + 1);
              }}
              className={cn(
                'h-14 w-11 rounded-xl text-center font-mono text-xl font-medium caret-transparent outline-none transition-all duration-300 ease-spring disabled:cursor-default sm:w-12',
                tone,
                d && status === 'idle' && 'scale-[1.04]',
              )}
              style={{ transitionDelay: status === 'success' ? `${i * 50}ms` : '0ms' }}
            />
            {focus === i && !d && !locked && <span className="pointer-events-none absolute left-1/2 top-1/2 h-6 w-px -translate-x-1/2 -translate-y-1/2 animate-blink bg-brand-400" />}
            {i === length / 2 - 1 && <span className="absolute -right-[7px] top-1/2 h-px w-1.5 bg-ink-600" />}
          </div>
        );
      })}
    </div>
  );
}

export function OtpInputDemo() {
  const [status, setStatus] = useState<OtpStatus>('idle');
  const [round, setRound] = useState(0);
  const verify = (code: string) =>
    new Promise<boolean>((resolve) => {
      setStatus('verifying');
      window.setTimeout(() => {
        const ok = code === '424242';
        setStatus(ok ? 'success' : 'error');
        if (!ok) window.setTimeout(() => setStatus('idle'), 900);
        resolve(ok);
      }, 1100);
    });

  return (
    <div className="mx-auto flex w-full max-w-sm flex-col items-center rounded-2xl bg-ink-900 px-6 py-8 text-center shadow-card">
      <span className={cn('flex h-11 w-11 items-center justify-center rounded-2xl transition-colors duration-500', status === 'success' ? 'bg-emerald-500/15 text-emerald-400' : 'bg-ink-800 text-ink-200')}>
        {status === 'success' ? <CheckCircle2 className="h-5 w-5 animate-scale-in" /> : <Lock className="h-5 w-5" />}
      </span>
      <p className="mt-4 text-base font-medium text-ink-50">{status === 'success' ? 'Verified' : 'Enter verification code'}</p>
      <p className="mt-1 text-sm text-ink-400">We sent a 6-digit code to m•••@lumen.dev</p>
      <div className="mt-6">
        <OtpInput key={round} status={status} onComplete={verify} />
      </div>
      <div className="mt-5 flex h-5 items-center justify-center text-xs">
        {status === 'verifying' && <span className="flex animate-fade-in items-center gap-2 text-ink-300"><Loader2 className="h-3.5 w-3.5 animate-spin" /> Verifying…</span>}
        {status === 'error' && <span className="animate-fade-in text-rose-400">Invalid code — try 424242</span>}
        {status === 'success' && (
          <button onClick={() => { setStatus('idle'); setRound((r) => r + 1); }} className="flex animate-fade-in items-center gap-1.5 text-ink-400 hover:text-ink-100">
            <RefreshCw className="h-3 w-3" /> Start over
          </button>
        )}
        {status === 'idle' && <span className="text-ink-500">Hint: the code is 424242</span>}
      </div>
    </div>
  );
}

blocks/sign-up-form.content:
import { useState, type FormEvent } from 'react';
import { ArrowRight, Check, Eye, EyeOff, Github, Loader2, Lock, Mail, Twitter } from 'lucide-react';
import { cn } from '@/lib/cn';

export function passwordScore(pw: string) {
  const checks = [pw.length >= 8, /[A-Z]/.test(pw) && /[a-z]/.test(pw), /\d/.test(pw), /[^A-Za-z0-9]/.test(pw)];
  return { checks, score: checks.filter(Boolean).length };
}

const LEVELS = [
  { label: 'Too weak', color: 'bg-rose-500', text: 'text-rose-400' },
  { label: 'Weak', color: 'bg-rose-500', text: 'text-rose-400' },
  { label: 'Fair', color: 'bg-amber-400', text: 'text-amber-400' },
  { label: 'Good', color: 'bg-sky-400', text: 'text-sky-400' },
  { label: 'Strong', color: 'bg-emerald-400', text: 'text-emerald-400' },
];
const RULES = ['8+ characters', 'Upper & lowercase', 'A number', 'A symbol'];

export type SignUpFormProps = { onSubmit?: (data: { email: string; password: string }) => Promise<void> };

export function SignUpForm({ onSubmit = () => new Promise((r) => setTimeout(r, 1300)) }: SignUpFormProps) {
  const [email, setEmail] = useState('');
  const [pw, setPw] = useState('');
  const [show, setShow] = useState(false);
  const [touched, setTouched] = useState({ email: false, pw: false });
  const [state, setState] = useState<'idle' | 'loading' | 'done'>('idle');
  const [shake, setShake] = useState(0);
  const { checks, score } = passwordScore(pw);
  const emailErr = !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ? (email ? 'Enter a valid email address' : 'Email is required') : null;
  const pwErr = score < 3 ? 'Use a stronger password' : null;
  const level = LEVELS[pw ? score : 0];

  const submit = async (e: FormEvent) => {
    e.preventDefault();
    setTouched({ email: true, pw: true });
    if (emailErr || pwErr) return setShake((s) => s + 1);
    setState('loading');
    await onSubmit({ email, password: pw });
    setState('done');
  };

  if (state === 'done') {
    return (
      <div className="flex w-full max-w-sm animate-scale-in flex-col items-center rounded-2xl bg-ink-900 px-6 py-10 text-center shadow-card">
        <span className="relative flex h-14 w-14 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400">
          <span className="absolute inset-0 animate-pulse-ring rounded-full bg-emerald-500/30" />
          <Check className="relative h-6 w-6 animate-scale-in" />
        </span>
        <p className="mt-5 text-lg font-medium text-ink-50">Check your inbox</p>
        <p className="mt-1 text-sm text-ink-400">We sent a confirmation link to <span className="text-ink-200">{email}</span></p>
        <button onClick={() => { setState('idle'); setPw(''); setTouched({ email: false, pw: false }); }} className="mt-6 text-xs text-ink-400 transition-colors hover:text-ink-100">Use a different email</button>
      </div>
    );
  }

  const field = 'flex h-11 items-center gap-2.5 rounded-xl bg-ink-850 px-3 transition-shadow duration-200 focus-within:shadow-glow';
  return (
    <form onSubmit={submit} noValidate className="w-full max-w-sm rounded-2xl bg-ink-900 p-6 shadow-card">
      <p className="text-lg font-medium text-ink-50">Create your account</p>
      <p className="mt-1 text-sm text-ink-400">Start building with NiceUI in seconds.</p>
      <div className="mt-5 grid grid-cols-2 gap-2">
        {[{ icon: Github, label: 'GitHub' }, { icon: Twitter, label: 'Twitter' }].map(({ icon: Icon, label }) => (
          <button key={label} type="button" className="focus-ring flex h-10 items-center justify-center gap-2 rounded-xl bg-ink-850 text-sm font-medium text-ink-100 shadow-hairline transition-all hover:bg-ink-800 active:scale-[0.97]">
            <Icon className="h-4 w-4" /> {label}
          </button>
        ))}
      </div>
      <div className="my-5 flex items-center gap-3 text-[11px] uppercase tracking-wider text-ink-500">
        <span className="h-px flex-1 bg-white/5" /> or <span className="h-px flex-1 bg-white/5" />
      </div>
      <div key={shake} className={cn('space-y-3', shake > 0 && 'animate-wiggle')}>
        <div>
          <label className={cn(field, touched.email && emailErr ? 'shadow-[0_0_0_1px_rgba(251,113,133,0.5)]' : 'shadow-hairline')}>
            <Mail className="h-4 w-4 text-ink-500" />
            <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} onBlur={() => setTouched((t) => ({ ...t, email: true }))} placeholder="you@company.com" className="h-full flex-1 bg-transparent text-sm text-ink-50 outline-none placeholder:text-ink-500" />
          </label>
          <p className={cn('overflow-hidden text-xs text-rose-400 transition-all duration-300', touched.email && emailErr ? 'mt-1.5 max-h-5 opacity-100' : 'max-h-0 opacity-0')}>{emailErr}</p>
        </div>
        <div>
          <label className={cn(field, touched.pw && pwErr ? 'shadow-[0_0_0_1px_rgba(251,113,133,0.5)]' : 'shadow-hairline')}>
            <Lock className="h-4 w-4 text-ink-500" />
            <input type={show ? 'text' : 'password'} value={pw} onChange={(e) => setPw(e.target.value)} onBlur={() => setTouched((t) => ({ ...t, pw: true }))} placeholder="Password" className="h-full flex-1 bg-transparent text-sm text-ink-50 outline-none placeholder:text-ink-500" />
            <button type="button" aria-label={show ? 'Hide password' : 'Show password'} onClick={() => setShow((s) => !s)} className="text-ink-500 transition-colors hover:text-ink-200">
              {show ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
            </button>
          </label>
          <div className={cn('grid transition-all duration-500 ease-smooth', pw ? 'grid-rows-[1fr] opacity-100' : 'grid-rows-[0fr] opacity-0')}>
            <div className="overflow-hidden">
              <div className="mt-2.5 flex items-center gap-2">
                <div className="flex flex-1 gap-1">
                  {[0, 1, 2, 3].map((i) => (
                    <span key={i} className="h-1 flex-1 overflow-hidden rounded-full bg-ink-800">
                      <span className={cn('block h-full origin-left rounded-full transition-all duration-500 ease-spring', level.color, i < score ? 'scale-x-100' : 'scale-x-0')} style={{ transitionDelay: `${i * 40}ms` }} />
                    </span>
                  ))}
                </div>
                <span className={cn('w-14 text-right text-[11px] font-medium transition-colors', level.text)}>{level.label}</span>
              </div>
              <div className="mt-2 grid grid-cols-2 gap-1">
                {RULES.map((r, i) => (
                  <span key={r} className={cn('flex items-center gap-1.5 text-[11px] transition-colors duration-300', checks[i] ? 'text-ink-200' : 'text-ink-500')}>
                    <span className={cn('flex h-3.5 w-3.5 items-center justify-center rounded-full transition-all duration-300', checks[i] ? 'bg-emerald-500 text-ink-950' : 'bg-ink-800')}>
                      <Check className={cn('h-2.5 w-2.5 transition-transform duration-300 ease-spring', checks[i] ? 'scale-100' : 'scale-0')} />
                    </span>
                    {r}
                  </span>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
      <button type="submit" disabled={state === 'loading'} className="focus-ring group mt-5 flex h-11 w-full items-center justify-center gap-2 rounded-xl bg-ink-50 text-sm font-medium text-ink-950 transition-all hover:bg-white active:scale-[0.98] disabled:opacity-70">
        {state === 'loading' ? <><Loader2 className="h-4 w-4 animate-spin" /> Creating account…</> : <>Create account <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-0.5" /></>}
      </button>
      <p className="mt-4 text-center text-xs text-ink-500">By continuing you agree to our Terms and Privacy Policy.</p>
    </form>
  );
}

export function SignUpFormDemo() {
  return (
    <div className="flex justify-center">
      <SignUpForm />
    </div>
  );
}

blocks/bloom-menu.content:
import { useCallback, useRef, useState, type ComponentType } from 'react';
import { Camera, FileText, Image, Mic, Plus, Calendar, MapPin } from 'lucide-react';
import { cn } from '@/lib/cn';
import { useClickOutside, useEscape } from '@/components/ui/motion/hooks';

export type BloomItem = { id: string; label: string; icon: ComponentType<{ className?: string }>; tint: string };

export type BloomMenuProps = {
  items: BloomItem[];
  radius?: number;
  /** Arc in degrees, centered on `direction`. 360 for a full ring. */
  spread?: number;
  /** Angle in degrees the arc points toward (−90 = up). */
  direction?: number;
  onSelect?: (item: BloomItem) => void;
};

export function BloomMenu({ items, radius = 92, spread = 360, direction = -90, onSelect }: BloomMenuProps) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  const close = useCallback(() => setOpen(false), []);
  useEscape(open, close);
  useClickOutside([ref], open, close);

  const full = spread >= 360;
  const step = full ? 360 / items.length : spread / Math.max(1, items.length - 1);
  const start = full ? direction : direction - spread / 2;

  return (
    <div ref={ref} className="relative flex h-14 w-14 items-center justify-center">
      <span
        className={cn('pointer-events-none absolute rounded-full bg-brand-500/10 shadow-[0_0_0_1px_rgba(56,189,248,0.15)] transition-all duration-500 ease-spring', open ? 'opacity-100' : 'opacity-0')}
        style={{ width: open ? radius * 2 + 64 : 56, height: open ? radius * 2 + 64 : 56 }}
      />
      {items.map((it, i) => {
        const a = ((start + step * i) * Math.PI) / 180;
        const x = Math.cos(a) * radius;
        const y = Math.sin(a) * radius;
        const Icon = it.icon;
        return (
          <button
            key={it.id}
            aria-label={it.label}
            tabIndex={open ? 0 : -1}
            onClick={() => { onSelect?.(it); setOpen(false); }}
            className={cn('focus-ring group absolute flex h-12 w-12 items-center justify-center rounded-full text-white shadow-pop transition-all ease-spring hover:brightness-110', it.tint, open ? 'opacity-100' : 'pointer-events-none opacity-0')}
            style={{
              transform: open ? `translate(${x}px, ${y}px) scale(1)` : 'translate(0,0) scale(0.3)',
              transitionDuration: open ? '550ms' : '250ms',
              transitionDelay: `${(open ? i : items.length - 1 - i) * 40}ms`,
            }}
          >
            <Icon className="h-5 w-5 transition-transform duration-300 ease-spring group-hover:scale-125 group-active:scale-90" />
            <span className={cn('pointer-events-none absolute whitespace-nowrap rounded-md bg-ink-800 px-2 py-1 text-[11px] font-medium text-ink-50 opacity-0 shadow-pop transition-all duration-200 group-hover:opacity-100', y < 0 ? '-top-8' : '-bottom-8')}>
              {it.label}
            </span>
          </button>
        );
      })}
      <button
