        <p className="mx-auto mt-6 max-w-md text-[16px] leading-relaxed text-ink-300">{description}</p>
        <div className="mt-10 flex flex-wrap justify-center gap-3">
          <PrimaryButton cta={primary} />
          <GhostButton cta={secondary} />
        </div>
