      <div className="mx-auto max-w-3xl">
        <Eyebrow>{eyebrow}</Eyebrow>
        <h1 className="mt-7 text-[42px] font-medium leading-[1.02] tracking-[-0.05em] text-ink-50 sm:text-7xl">
