                type="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder={placeholder}
                aria-label="Email address"
                className="h-10 min-w-0 flex-1 bg-transparent px-4 text-sm text-ink-50 outline-none placeholder:text-ink-500"
