  description?: string;
  primary?: Cta;
  secondary?: Cta;
  className?: string;
};

const ORBIT_RINGS: { r: number; dur: number; icons: typeof Zap[] }[] = [
  { r: 130, dur: 26, icons: [Figma, GitBranch, Database] },
  { r: 205, dur: 38, icons: [Code2, Globe, Layers, Zap] },
  { r: 280, dur: 52, icons: [Sparkles, Bell, TrendingUp, Star, Check] },
