              <div
                className="pointer-events-none absolute top-1/2 h-5 w-5 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-brand-300 bg-ink-950 shadow-[0_0_0_6px_rgba(125,211,252,.15)]"
                style={{ left: `${pct}%` }}
