          {chip?.on === o && (
            <span className={cn('rounded-full px-1.5 py-px text-[10px] font-medium transition-colors', o === value ? 'bg-brand-950/15 text-brand-950' : 'bg-brand-300/10 text-brand-300')}>{chip.label}</span>
