        <p className="mt-0.5 text-[12px] text-ink-500">{r.date}</p>
      </div>
      <span
        aria-hidden
        className={cn(
          'absolute left-0 top-1.5 h-3 w-3 rounded-full border-2 transition-all duration-700 md:left-[159px]',
